class _BrandScale(tk.Canvas):
    """绘制截图中的圆形滑块，同时保留 Tk Scale 的常用接口。"""

    def __init__(self, master, *args, **kwargs):
        self._from = float(kwargs.pop("from_", 0.0))
        self._to = float(kwargs.pop("to", 1.0))
        self._resolution = float(kwargs.pop("resolution", 1.0))
        self._orient = kwargs.pop("orient", "horizontal")
        self._variable = kwargs.pop("variable", None)
        self._command = kwargs.pop("command", None)
        self._showvalue = bool(kwargs.pop("showvalue", False))
        self._length = int(kwargs.pop("length", 100))
        self._text_color = kwargs.pop("fg", BRAND_COLORS["white"])
        self._track_color = SLIDER_COLORS["track"]
        self._thumb_color = SLIDER_COLORS["thumb"]
        self._thumb_active_color = SLIDER_COLORS["thumb_active"]
        self._halo_color = SLIDER_COLORS["halo"]
        self._halo_active_color = SLIDER_COLORS["halo_active"]
        self._halo_border_color = SLIDER_COLORS["halo_border"]
        self._dragging = False
        self._hovering = False
        self._updating_variable = False
        self._variable_trace = None
        self._value = self._from
        self._state = kwargs.pop("state", tk.NORMAL)

        kwargs.pop("troughcolor", None)
        kwargs.pop("activebackground", None)
        kwargs.pop("sliderrelief", None)
        kwargs.pop("sliderlength", None)
        kwargs.pop("width", None)
        kwargs.pop("relief", None)
        kwargs.pop("bd", None)
        kwargs.setdefault("highlightthickness", 0)
        kwargs.setdefault("borderwidth", 0)
        kwargs.setdefault("bg", kwargs.pop("background", BRAND_COLORS["bg"]))
        kwargs.setdefault("takefocus", 1)
        if self._orient == "horizontal":
            kwargs.setdefault("width", self._length)
            kwargs.setdefault("height", 42 if self._showvalue else 32)
        else:
            kwargs.setdefault("width", 42 if self._showvalue else 32)
            kwargs.setdefault("height", self._length)
        super().__init__(master, *args, **kwargs)

        if self._variable is not None:
            try:
                self._value = self._coerce_value(self._variable.get())
                self._variable_trace = self._variable.trace_add(
                    "write", self._on_variable_changed
                )
            except (tk.TclError, TypeError, ValueError):
                self._value = self._from
        self.bind("<Configure>", lambda _event: self._redraw())
        self.bind("<Enter>", self._on_enter)
        self.bind("<Leave>", self._on_leave)
        self.bind("<ButtonPress-1>", self._on_press)
        self.bind("<B1-Motion>", self._on_drag)
        self.bind("<ButtonRelease-1>", self._on_release)
        self.bind("<KeyPress-Left>", lambda _event: self._step(-1))
        self.bind("<KeyPress-Down>", lambda _event: self._step(-1))
        self.bind("<KeyPress-Right>", lambda _event: self._step(1))
        self.bind("<KeyPress-Up>", lambda _event: self._step(1))
        self.bind("<Home>", lambda _event: self._set_from_user(self._from))
        self.bind("<End>", lambda _event: self._set_from_user(self._to))
        self._redraw()

    def destroy(self):
        if self._variable is not None and self._variable_trace:
            try:
                self._variable.trace_remove("write", self._variable_trace)
            except tk.TclError:
                pass
        super().destroy()

    def _coerce_value(self, value):
        try:
            value = float(value)
        except (TypeError, ValueError):
            value = self._from
        low, high = sorted((self._from, self._to))
        value = max(low, min(high, value))
        if self._resolution > 0:
            value = self._from + round((value - self._from) / self._resolution) * self._resolution
            value = max(low, min(high, value))
        return value

    def _format_value(self, value):
        if self._resolution >= 1:
            return str(int(round(value)))
        return "{:g}".format(value)

    def _on_variable_changed(self, *_args):
        if self._updating_variable or self._variable is None:
            return
        try:
            self._value = self._coerce_value(self._variable.get())
        except (tk.TclError, TypeError, ValueError):
            self._value = self._from
        self._redraw()

    def _set_value(self, value, notify=False):
        value = self._coerce_value(value)
        changed = value != self._value
        self._value = value
        if self._variable is not None:
            self._updating_variable = True
            try:
                if isinstance(self._variable, tk.IntVar):
                    self._variable.set(int(round(value)))
                elif self._resolution >= 1:
                    self._variable.set(int(round(value)))
                else:
                    self._variable.set(value)
            finally:
                self._updating_variable = False
        self._redraw()
        if notify and changed and callable(self._command):
            self._command(self._format_value(value))

    def _set_from_user(self, value):
        if self._state == tk.DISABLED:
            return "break"
        self._set_value(value, notify=True)
        return "break"

    def _track_bounds(self):
        if self._orient == "horizontal":
            return 14.0, max(15.0, self.winfo_width() - 14.0)
        return 14.0, max(15.0, self.winfo_height() - 14.0)

    def _value_from_position(self, position):
        start, end = self._track_bounds()
        ratio = 0.0 if end <= start else (position - start) / (end - start)
        ratio = max(0.0, min(1.0, ratio))
        return self._from + ratio * (self._to - self._from)

    def _position_from_value(self):
        span = self._to - self._from
        ratio = 0.0 if span == 0 else (self._value - self._from) / span
        start, end = self._track_bounds()
        return start + max(0.0, min(1.0, ratio)) * (end - start)

    def _on_press(self, event):
        self.focus_set()
        if self._orient == "horizontal":
            position = event.x
        else:
            position = self.winfo_height() - event.y
        self._dragging = True
        return self._set_from_user(self._value_from_position(position))

    def _on_drag(self, event):
        if not self._dragging:
            return "break"
        if self._orient == "horizontal":
            position = event.x
        else:
            position = self.winfo_height() - event.y
        return self._set_from_user(self._value_from_position(position))

    def _on_release(self, _event):
        self._dragging = False

    def _on_enter(self, _event):
        self._hovering = True
        self._redraw()

    def _on_leave(self, _event):
        if not self._dragging:
            self._hovering = False
            self._redraw()

    def _step(self, direction):
        step = self._resolution if self._resolution > 0 else (self._to - self._from) / 100.0
        return self._set_from_user(self._value + direction * step)

    def _redraw(self):
        if not self.winfo_exists():
            return
        self.delete("all")
        width = max(1, self.winfo_width())
        height = max(1, self.winfo_height())
        track_width = 6
        radius = 12
        if self._orient == "horizontal":
            start, end = self._track_bounds()
            center_y = height - 12 if self._showvalue else height / 2
            self.create_line(
                start,
                center_y,
                end,
                center_y,
                fill=self._track_color,
                width=track_width,
                capstyle=tk.ROUND,
            )
            thumb_x, thumb_y = self._position_from_value(), center_y
        else:
            start, end = self._track_bounds()
            center_x = width - 12 if self._showvalue else width / 2
            self.create_line(
                center_x,
                height - start,
                center_x,
                height - end,
                fill=self._track_color,
                width=track_width,
                capstyle=tk.ROUND,
            )
            thumb_x, thumb_y = center_x, height - self._position_from_value()
        halo_color = (
            self._halo_active_color
            if self._hovering or self._dragging
            else self._halo_color
        )
        thumb_color = (
            self._thumb_active_color
            if self._hovering or self._dragging
            else self._thumb_color
        )
        self.create_oval(
            thumb_x - radius,
            thumb_y - radius,
            thumb_x + radius,
            thumb_y + radius,
            fill=halo_color,
            outline=self._halo_border_color,
            width=1,
        )
        inner_radius = 9
        self.create_oval(
            thumb_x - inner_radius,
            thumb_y - inner_radius,
            thumb_x + inner_radius,
            thumb_y + inner_radius,
            fill=thumb_color,
            outline=thumb_color,
            width=1,
        )
        if self._showvalue:
            if self._orient == "horizontal":
                self.create_text(
                    width - 4,
                    9,
                    text=self._format_value(self._value),
                    anchor="e",
                    fill=self._text_color,
                    font=("Microsoft YaHei UI", 8),
                )
            else:
                self.create_text(
                    9,
                    4,
                    text=self._format_value(self._value),
                    anchor="nw",
                    fill=self._text_color,
                    font=("Microsoft YaHei UI", 8),
                )

    def get(self, *coordinates):
        if coordinates:
            position = coordinates[0]
            return self._value_from_position(float(position))
        if self._resolution >= 1:
            return int(round(self._value))
        return self._value

    def set(self, value):
        self._set_value(value, notify=False)

    def configure(self, cnf=None, **kwargs):
        if isinstance(cnf, dict):
            kwargs = dict(cnf, **kwargs)
            cnf = None
        redraw = False
        if "background" in kwargs and "bg" not in kwargs:
            kwargs["bg"] = kwargs.pop("background")
        for key, attribute in (
            ("fg", "_text_color"),
            ("troughcolor", "_track_color"),
        ):
            if key in kwargs:
                setattr(self, attribute, kwargs.pop(key))
                redraw = True
        if "activebackground" in kwargs:
            kwargs.pop("activebackground")
        if "from_" in kwargs:
            self._from = float(kwargs.pop("from_"))
            redraw = True
        if "to" in kwargs:
            self._to = float(kwargs.pop("to"))
            redraw = True
        if "resolution" in kwargs:
            self._resolution = float(kwargs.pop("resolution"))
            redraw = True
        if "variable" in kwargs:
            variable = kwargs.pop("variable")
            if self._variable is not None and self._variable_trace:
                try:
                    self._variable.trace_remove("write", self._variable_trace)
                except tk.TclError:
                    pass
            self._variable = variable
            self._variable_trace = None
            if variable is not None:
                self._variable_trace = variable.trace_add(
                    "write", self._on_variable_changed
                )
                self._on_variable_changed()
            redraw = True
        if "command" in kwargs:
            self._command = kwargs.pop("command")
        if "showvalue" in kwargs:
            self._showvalue = bool(kwargs.pop("showvalue"))
            redraw = True
        if "length" in kwargs:
            self._length = int(kwargs.pop("length"))
            if self._orient == "horizontal":
                kwargs.setdefault("width", self._length)
            else:
                kwargs.setdefault("height", self._length)
            redraw = True
        for key in ("sliderrelief", "sliderlength", "width", "relief", "bd"):
            kwargs.pop(key, None)
        if "state" in kwargs:
            self._state = kwargs["state"]
        result = super().configure(cnf, **kwargs)
        if redraw:
            self._redraw()
        return result

    config = configure


def _brand_scale(master, *args, **kwargs):
    return _BrandScale(master, *args, **kwargs)


