        self.root.geometry(
            "{}x{}+80+80".format(
                int(round(360 * initial_dpi_scale)),
                int(round(440 * initial_dpi_scale)),
            )
        )
        self.root.minsize(280, 320)
        self.root.protocol("WM_DELETE_WINDOW", self.quit_app)
        self.root.bind("<Escape>", lambda event: self._handle_pet_escape())
        self._quit_binding_sequence = self._tk_shortcut(
            self.shortcuts.get("quit", "Ctrl+Q")
        )
