    def _initialize_brand_switch_images(self, style):
        if Image is None or ImageDraw is None or ImageTk is None:
            self._brand_switch_images = None
            return
        if getattr(self, "_brand_switch_images", None):
            return
        scale = 3
        width, height = 46, 26
        diameter = 21
        images = []
        for active in (False, True):
            image = Image.new(
                "RGBA",
                (width * scale, height * scale),
                (0, 0, 0, 0),
            )
            draw = ImageDraw.Draw(image)
            track = (
                BRAND_COLORS["cyan"]
                if active
                else SWITCH_COLORS["off_track"]
            )
            draw.rounded_rectangle(
                (0, 0, (width - 1) * scale, (height - 1) * scale),
                radius=(height // 2) * scale,
                fill=track,
            )
            left = (width - diameter - 3) if active else 3
            top = (height - diameter) // 2
            draw.ellipse(
                (
                    left * scale,
                    top * scale,
                    (left + diameter) * scale,
                    (top + diameter) * scale,
                ),
                fill="#F8FAFB",
                outline="#E1E6E8",
                width=scale,
            )
            image = image.resize(
                (width, height),
                Image.Resampling.LANCZOS
                if hasattr(Image, "Resampling")
                else Image.LANCZOS,
            )
            images.append(ImageTk.PhotoImage(image, master=self.root))
        self._brand_switch_images = tuple(images)
        try:
            style.element_create(
                "Brand.Switch.indicator",
                "image",
                images[0],
                ("selected", images[1]),
                border=0,
                sticky="",
            )
            self._brand_switch_element_available = True
        except tk.TclError:
            self._brand_switch_element_available = False

    def _brand_switch_style(self, background, foreground, font=None):
        if not getattr(self, "_brand_switch_element_available", False):
            return None
        background = str(background or BRAND_COLORS["bg"])
        foreground = str(foreground or BRAND_COLORS["white"])
        style_name = "Brand.Switch.BG{}.FG{}.TCheckbutton".format(
            re.sub(r"[^A-Za-z0-9]", "", background),
            re.sub(r"[^A-Za-z0-9]", "", foreground),
        )
        style = ttk.Style(self.root)
        style.layout(
            style_name,
            [
                (
                    "Checkbutton.padding",
                    {
                        "sticky": "nswe",
                        "children": [
                            (
                                "Brand.Switch.indicator",
                                {"side": "left", "sticky": ""},
                            ),
                            (
                                "Checkbutton.focus",
                                {
                                    "side": "left",
                                    "sticky": "w",
                                    "children": [
                                        ("Checkbutton.label", {"sticky": "nswe"})
                                    ],
                                },
                            ),
                        ],
                    },
                )
            ],
        )
        style.configure(
            style_name,
            background=background,
            foreground=foreground,
            focuscolor=background,
            borderwidth=0,
            padding=(2, 2),
            font=font or ("Microsoft YaHei UI", 9),
        )
        style.map(
            style_name,
            background=[("active", background), ("disabled", background)],
            foreground=[("disabled", BRAND_COLORS["muted"])],
        )
        return style_name

    @staticmethod
    def _brand_scrollbar(parent, **options):
        return _BrandScrollbar(parent, **options)

    def _brand_checkbutton(self, parent, **options):
        original_options = dict(options)
        background = options.pop("bg", None)
        if background is None:
            try:
                background = parent.cget("bg")
            except tk.TclError:
                background = BRAND_COLORS["bg"]
        foreground = options.pop("fg", BRAND_COLORS["white"])
        options.pop("activebackground", None)
        options.pop("activeforeground", None)
        options.pop("selectcolor", None)
        options.pop("highlightthickness", None)
        options.pop("bd", None)
        font = options.pop("font", None)
        options.pop("anchor", None)
        cursor = options.pop("cursor", None)
        style_name = self._brand_switch_style(background, foreground, font)
        if style_name is None:
            original_options.setdefault("bg", background)
            original_options.setdefault("fg", foreground)
            return tk.Checkbutton(parent, **original_options)
        if cursor:
            options["cursor"] = cursor
        return ttk.Checkbutton(parent, style=style_name, **options)

    def _style_brand_tree(self, parent):
        """给正式设置/角色编辑窗口的 Tk 控件统一品牌色，不改变业务绑定。"""
        try:
            widget_type = parent.winfo_class()
        except tk.TclError:
            return
        try:
            current_bg = str(parent.cget("bg"))
        except (tk.TclError, TypeError):
            current_bg = ""
        default_backgrounds = {
            "",
            "SystemButtonFace",
            "SystemWindow",
            "#d9d9d9",
            "#f0f0f0",
        }
        if widget_type in ("Frame", "Labelframe", "Canvas") and current_bg in default_backgrounds:
            try:
                parent.configure(bg=BRAND_COLORS["bg"])
            except tk.TclError:
                pass
        elif widget_type == "Label" and current_bg in default_backgrounds:
            try:
                parent.configure(
                    bg=BRAND_COLORS["bg"],
                    fg=BRAND_COLORS["white"],
                )
            except tk.TclError:
                pass
        elif widget_type in ("Entry", "Text", "Listbox") and current_bg in default_backgrounds:
            try:
                parent.configure(
                    bg=BRAND_COLORS["panel"],
                    fg=BRAND_COLORS["white"],
                    insertbackground=BRAND_COLORS["white"],
                    relief="flat",
                    bd=0,
                )
                if widget_type == "Listbox":
                    parent.configure(
                        selectbackground=BRAND_COLORS["cyan"],
                        selectforeground=BRAND_COLORS["dark"],
                    )
            except tk.TclError:
                pass
        elif widget_type in ("Button", "Checkbutton") and current_bg in default_backgrounds:
            try:
                parent.configure(
                    bg=BRAND_COLORS["panel_soft"],
                    fg=BRAND_COLORS["white"],
                    activebackground=BRAND_COLORS["cyan"],
                    activeforeground=BRAND_COLORS["dark"],
                    relief="flat",
                    bd=0,
                )
                if widget_type == "Checkbutton":
                    parent.configure(
                        selectcolor=BRAND_COLORS["panel"],
                    )
            except tk.TclError:
                pass
        elif widget_type == "Scale":
            try:
                parent.configure(
                    bg=BRAND_COLORS["bg"],
                    fg=BRAND_COLORS["white"],
                    troughcolor=BRAND_COLORS["panel_soft"],
                    activebackground=BRAND_COLORS["line"],
                    highlightthickness=0,
                    bd=0,
                    sliderrelief=tk.RAISED,
                    sliderlength=30,
                    width=16,
                )
            except tk.TclError:
                pass
        for child in parent.winfo_children():
            self._style_brand_tree(child)

    def _start_tray(self):
        self.tray = WindowsTrayIcon(
            "{} - {}".format(APP_NAME, self._character_display_name()),
            on_show=lambda: self._enqueue_tray_event("show"),
            on_tasks=lambda: self._enqueue_tray_event("tasks"),
            on_topmost=lambda: self._enqueue_tray_event("topmost"),
            on_quit=lambda: self._enqueue_tray_event("quit"),
            on_menu=lambda: self._enqueue_tray_event("menu"),
            on_characters=lambda: self._enqueue_tray_event("characters"),
            on_switch_character=lambda request: self._tray_event_queue.put(("switch", request)),
            menu_items=self._get_tray_menu_items(),
            icon_path=ICON_PATH,
        )
        self.tray.start()
        self._tray_event_poll_after_id = self._safe_root_after(
            40,
            self._poll_tray_events,
        )

    def _enqueue_tray_event(self, event_name):
        """托盘线程只入队，所有 Tk 操作统一在主线程执行。"""
        self._tray_event_queue.put(str(event_name))

    def _poll_tray_events(self):
        self._tray_event_poll_after_id = None
        try:
            if not self.root.winfo_exists():
                return
        except tk.TclError:
            return
        while True:
            try:
                event_name = self._tray_event_queue.get_nowait()
            except queue.Empty:
                break
            if isinstance(event_name, tuple):
                kind, request = event_name
                if kind == "switch":
                    self._handle_character_launch(request)
                elif kind == "switch_ready":
                    self.switch_character(request)
                elif kind == "switch_error":
                    messagebox.showerror("角色切换失败", request, parent=self.root)
                continue
            if event_name == "show":
                self._show_from_tray()
            elif event_name == "menu":
                self._show_tray_popup_menu()
            elif event_name == "tasks":
                self.show_control_page("tasks")
            elif event_name == "characters":
                self.show_control_page("characters")
            elif event_name == "topmost":
                self.toggle_topmost()
            elif event_name == "quit":
                self.quit_app()
                return
        self._tray_event_poll_after_id = self._safe_root_after(
            40,
            self._poll_tray_events,
        )

    def _handle_character_launch(self, request):
        seen = getattr(self, "_character_launch_requests", set())
        token = request["request_id"]
        if token in seen:
            return
        if len(seen) >= 256:
            seen.clear()
        seen.add(token)
        self._character_launch_requests = seen

        def prepare():
            try:
                character_id = request["character_id"]
                if request.get("package"):
                    from core.backup import import_signed_directory
                    from core.package_signature import verify_package
                    manifest = verify_package(request["package"])
                    if manifest["character_id"] != character_id:
                        raise ValueError("启动器角色 ID 与角色包不一致。")
                    import_signed_directory(request["package"])
                self._tray_event_queue.put(("switch_ready", character_id))
            except Exception as error:
                self._tray_event_queue.put(("switch_error", str(error)))
        threading.Thread(target=prepare, daemon=True).start()

    def _get_tray_menu_items(self):
        next_id = 1

        def convert(items):
            nonlocal next_id
            converted = []
            for item in items:
                label, action, children = self._context_menu_item_parts(item)
                item_id = next_id
                next_id += 1
                callback = (
                    lambda selected=action: self._safe_root_after(0, selected)
                    if selected is not None
                    else None
                )
                converted.append(
                    (
                        item_id,
                        label,
                        callback,
                        convert(children),
                    )
                )
            return tuple(converted)

        return convert(self._get_tray_actions())

    def _get_tray_actions(self):
        return (
            ("输入", self._show_inline_input),
            ("角色", self._show_pet_role_panel),
            ("历史对话", lambda: self._show_control_center("conversation")),
            ("任务提醒", lambda: self._show_control_center("tasks")),
            ("设置", self.show_config),
            ("关闭鼠标穿透" if self.store.settings.get("mouse_passthrough", False)
             else "开启鼠标穿透", self.toggle_mouse_passthrough),
            ("退出桌宠", self.quit_app),
        )

    def _ensure_pet_toolbar(self):
        toolbar = getattr(self, "_pet_toolbar", None)
        if toolbar is None:
            toolbar = self._pet_toolbar = PetToolbar(self)
        return toolbar

    def _show_pet_role_panel(self):
        self._close_context_actions()
        self._ensure_pet_toolbar().show_role()

    def _handle_pet_escape(self):
        toolbar = getattr(self, "_pet_toolbar", None)
        if toolbar is not None and toolbar.opened:
            toolbar.close()
            return "break"
        self.toggle_topmost()
        return "break"

    def _refresh_tray_menu(self):
        tray = getattr(self, "tray", None)
        if tray is not None:
            tray.set_menu_items(self._get_tray_menu_items())

    def _set_window_icon(self, window):
        logo_path = existing_asset(LOGO_PATH)
        icon_path = existing_asset(ICON_PATH)
        try:
            if logo_path:
                self._logo_image = tk.PhotoImage(file=str(logo_path))
                window.iconphoto(True, self._logo_image)
            elif icon_path:
                window.iconbitmap(str(icon_path))
        except tk.TclError:
            pass

    def _style_branded_window(self, window):
        self._set_window_icon(window)
        try:
            window.configure(bg=self.theme["window"])
        except tk.TclError:
            pass

    def _show_from_tray(self):
        if not self.root.winfo_exists():
            return
        self.root.deiconify()
        self._sync_pet_topmost(lift=True)
        self._schedule_portrait_refresh(0)

    def _get_context_menu_actions(self):
        return (
            ("输入", self._show_inline_input),
            ("角色", self._show_pet_role_panel),
            ("历史对话", lambda: self._show_control_center("conversation")),
            ("设置", self.show_config),
        )

    def _live2d_control_values(self, renderer=None):
        renderer = renderer or getattr(self, "renderer", None)
        if not isinstance(renderer, Live2DRenderer):
            return {}
        return {
            "follow": renderer._follow_enabled,
            "paused": (renderer._preview_snapshot["paused"]
                       if renderer._preview_snapshot is not None else renderer._paused),
            "idle_action_interval": renderer._idle_action_interval,
            "auto_behavior": renderer._auto_behavior,
        }

    def _apply_live2d_preferences(self, renderer, character_id=None):
        if not isinstance(renderer, Live2DRenderer):
            return
        all_preferences = self.store.settings.get("live2d_controls", {})
        preferences = all_preferences.get(character_id or self.character_id, {}) if isinstance(all_preferences, dict) else {}
        if not isinstance(preferences, dict):
            return
        follow = renderer._renderer_config.get("mouse_follow", {})
        renderer.set_mouse_follow(preferences.get("follow", follow.get("enabled", False)))
        renderer.set_paused(preferences.get("paused", False))
        renderer.set_behavior_preferences(preferences)

    def _set_live2d_control(self, key, value):
        renderer = getattr(self, "renderer", None)
        if not isinstance(renderer, Live2DRenderer):
            return False
        values = self._live2d_control_values(renderer)
        if key not in values:
            return False
        try:
            value = float(value) if key == "idle_action_interval" else bool(value)
        except (TypeError, ValueError):
            return False
        if key == "idle_action_interval":
            if not math.isfinite(value):
                return False
            bounds = {"idle_action_interval": (8, 120)}
            minimum, maximum = bounds[key]
            value = max(minimum, min(maximum, value))
        if values[key] == value:
            return True
        renderer.end_preview()
        dialog = getattr(self, "_control_dialog", None)
        if dialog is not None and dialog.winfo_exists() and not getattr(self, "_control_draft_active", False):
            self._control_snapshot = self._capture_control_snapshot()
            self._control_draft_active = True
        if key == "follow":
            renderer.set_mouse_follow(value)
        elif key == "paused":
            renderer.set_paused(value)
        elif key == "idle_action_interval":
            renderer.set_idle_action_interval(value)
        elif key == "auto_behavior":
            renderer.set_behavior_preferences({**renderer.behavior_preferences(), "auto_behavior": value})
        else:
            return False
        self._record_live2d_preferences(renderer)
        self._sync_live2d_settings_controls()
        return True

    def _record_live2d_preferences(self, renderer):
        preferences = copy.deepcopy(self.store.settings.get("live2d_controls", {}))
        if not isinstance(preferences, dict):
            preferences = {}
        preferences[self.character_id] = {**self._live2d_control_values(renderer),
                                          **renderer.behavior_preferences()}
        self.store.settings["live2d_controls"] = preferences
        editor = getattr(self, "_control_edit_context", None)
        if editor and editor["character_id"] == self.character_id:
            editor["live2d_controls_draft"] = copy.deepcopy(preferences[self.character_id])
        if not getattr(self, "_control_draft_active", False):
            self.store.save_settings({"live2d_controls": preferences})

    def _set_live2d_behavior_preferences(self, preferences):
        renderer = getattr(self, "renderer", None)
        if not isinstance(renderer, Live2DRenderer) or not isinstance(preferences, dict):
            return False
        mapping = preferences.get("emotion_expressions", {})
        valid = set(renderer.expression_options()) | set(renderer._parameters_by_state) | set(renderer._expression_by_state)
        if not isinstance(mapping, dict) or any(
            not isinstance(candidates, list) or not candidates or any(key not in valid for key in candidates)
            for candidates in mapping.values()
        ):
            return False
        motion_mapping = preferences.get("intent_motions", {})
        valid_motions = set(renderer.safe_motion_options())
        if not isinstance(motion_mapping, dict) or any(key not in INTENT_LABELS for key in motion_mapping) or any(
            not isinstance(candidates, list) or any(
                not isinstance(item, list) or len(item) != 2
                or not isinstance(item[0], str) or not isinstance(item[1], int)
                or (item[0], item[1]) not in valid_motions
                for item in candidates
            )
            for candidates in motion_mapping.values()
        ):
            return False
        dialog = getattr(self, "_control_dialog", None)
        if dialog is not None and dialog.winfo_exists() and not getattr(self, "_control_draft_active", False):
            self._control_snapshot = self._capture_control_snapshot()
            self._control_draft_active = True
        renderer.set_behavior_preferences({**renderer.behavior_preferences(), **preferences})
        self._record_live2d_preferences(renderer)
        return True

    @staticmethod
    def _live2d_motion_label(group, index, filename=""):
        labels = {"nod": "点头", "shake": "摇头", "blink": "眨眼", "look": "左右观察",
                  "lean": "倾身", "leanforward": "前倾", "wave": "挥手",
                  "glance": "瞥视", "gesture": "姿态动作", "tilt": "侧倾", "jump": "小跳"}
        label = labels.get(group.casefold(), group)
        slug = Path(filename).name.casefold().removesuffix(".motion3.json").rsplit(".", 1)[-1]
        if any("\u4e00" <= character <= "\u9fff" for character in slug):
            return slug
        names = {
            "nodcontinuous": "连续点头", "nodemphatic": "重点头",
            "shakeback": "后仰摇头", "shakeforward": "前倾摇头",
            "lookright": "向右看", "lookleft": "向左看",
            "glanceup": "向上瞥视", "glancedown": "向下瞥视",
            "bashful": "扭捏", "swayforward": "前倾摇摆",
            "peekforward": "轻探身", "leanforwarddeep": "大幅前倾",
            "tiltleft": "向左倾", "tiltright": "向右倾",
            "hopback": "后仰小跳", "hopcontinuous": "连续小跳",
            "hopbackfast": "后仰快跳", "hop": "小跳",
            "hopleft": "向左跳", "hopright": "向右跳",
        }
        if slug in names:
            return names[slug]
        if group.casefold() == "lean":
            name = Path(filename).name.casefold()
            if "back" in name or "后倾" in name or "后仰" in name:
                label = "后倾"
            elif "forward" in name or "前倾" in name:
                label = "前倾"
        return label

    @staticmethod
    def _context_menu_item_parts(item):
        label = str(item[0])
        action = item[1] if len(item) > 1 else None
        children = item[2] if len(item) > 2 else ()
        return label, action, tuple(children or ())

    @staticmethod
    def _portrait_auto_actions_enabled(config):
        rules = config.get("portrait_rules", {})
        return bool(rules.get("auto_actions", False)) if isinstance(rules, dict) else False

    def _set_portrait_auto_actions(self, enabled):
        config = copy.deepcopy(self.character_config)
        if self._is_live2d_character_config(config):
            return False
        rules = config.get("portrait_rules")
        if not isinstance(rules, dict):
            rules = {}
            config["portrait_rules"] = rules
        rules["auto_actions"] = bool(enabled)
        try:
            save_character_config(self.character_id, config)
        except (OSError, ValueError) as error:
            messagebox.showerror("动作设置失败", str(error), parent=self.root)
            return False
        self.character_config = config
        self._sync_control_snapshot_character(self.character_id)
        return True

    def _switch_runtime_portrait_action(self, action_id, persist=True, render=True):
        if self._is_live2d_character_config(self.character_config):
            return False
        config = copy.deepcopy(self.character_config)
        outfits = self._portrait_outfits(config)
        outfit_id = self._active_portrait_outfit_id(config)
        outfit = next(item for item in outfits if item["id"] == outfit_id)
        action_id = self._normalize_portrait_action_id(action_id)
        if action_id and not any(item["id"] == action_id for item in outfit["actions"]):
            return False
        choices = self._portrait_action_choices(outfit)
        if not any(item["id"] == action_id for item in choices):
            action_id = choices[0]["id"]
        outfit["active_action_id"] = action_id
        config["portrait_outfits"] = outfits
        if persist:
            try:
                save_character_config(self.character_id, config)
            except (OSError, ValueError) as error:
                messagebox.showerror("切换动作失败", str(error), parent=self.root)
                return False
        self.character_config = config
        renderer = getattr(self, "renderer", None)
        if isinstance(renderer, StaticPortraitRenderer):
            renderer.state_definitions = self._configured_state_definitions()
        if render:
            self._refresh_state_buttons()
            self._render_state()
        if persist:
            self._sync_control_snapshot_character(self.character_id)
        return True

    def _choose_reply_portrait_action(self, state):
        outfit = self._active_portrait_outfit(self.character_config)
        choices = self._portrait_action_choices(outfit)
        candidates = []
        for emotion in emotion_fallback_chain(state):
            candidates = [
                item["id"] for item in choices
                if self._reply_portrait_exact_state(emotion, item["id"]) is not None
            ]
            if candidates:
                break
        current = self._active_portrait_action_id(self.character_config)
        alternatives = [key for key in candidates if key != current]
        return random.choice(alternatives or candidates) if candidates else current

    def _reply_portrait_exact_state(self, state, action_id=None):
        """Inspect original resources, never the editor's idle-filled definitions."""
        config = self.character_config
        outfit = self._active_portrait_outfit(config)
        selected = (self._active_portrait_action_id(config)
                    if action_id is None else action_id)
        action = self._portrait_action(outfit, selected)
        assets = action.get("portrait_assets", {})
        raw_states = config.get("states", {})
        if not isinstance(raw_states, dict):
            raw_states = {}
        removed = self._portrait_removed_state_keys(config) if not selected else set()
        for key in dict.fromkeys((state, *assets, *raw_states)):
            if key in removed:
                continue
            raw = raw_states.get(key, {})
            raw = raw if isinstance(raw, dict) else {"label": str(raw)}
            if key != state and self._preset_emotion_key(key, raw.get("label", key)) != state:
                continue
            definition = dict(raw)
            definition.setdefault("label", STATE_LABELS.get(key, key))
            definition["portrait_assets"] = assets.get(key, {})
            legacy_folder = not selected and outfit["id"] == "default" and not assets
            if legacy_folder and not definition["portrait_assets"]:
                definition["portrait_assets"] = raw.get("portrait_assets", {})
            path = self._portrait_mode_asset_path(
                key, "full", self.character_dir, definition=definition,
                outfit_id="default" if legacy_folder else "__action__",
            )
            if path is not None:
                return key
        return None

    def _reply_portrait_display_state(self, state):
        if state == "idle":
            return "idle"
        for candidate in emotion_fallback_chain(state):
            key = self._reply_portrait_exact_state(candidate)
            if key is not None:
                return key
        return "idle"

    def _context_screen_bounds(self, metrics):
        screen = (0, 0, int(self.root.winfo_screenwidth()), int(self.root.winfo_screenheight()))
        if os.name == "nt":
            try:
                class MonitorInfo(ctypes.Structure):
                    _fields_ = [("cbSize", wintypes.DWORD), ("rcMonitor", wintypes.RECT),
                                ("rcWork", wintypes.RECT), ("dwFlags", wintypes.DWORD)]
                user32 = ctypes.windll.user32
                user32.MonitorFromPoint.argtypes = [wintypes.POINT, wintypes.DWORD]
                user32.MonitorFromPoint.restype = ctypes.c_void_p
                user32.GetMonitorInfoW.argtypes = [ctypes.c_void_p, ctypes.POINTER(MonitorInfo)]
                info = MonitorInfo()
                info.cbSize = ctypes.sizeof(info)
                monitor = user32.MonitorFromPoint(wintypes.POINT(
                    metrics["portrait_screen_x"] + metrics["portrait_width"] // 2,
                    metrics["portrait_screen_y"] + metrics["portrait_height"] // 2), 2)
                if user32.GetMonitorInfoW(monitor, ctypes.byref(info)):
                    rect = info.rcMonitor
                    screen = (rect.left, rect.top, rect.right, rect.bottom)
            except (AttributeError, OSError, TypeError, ValueError):
                pass
        return screen

    def _position_context_bar(self, bar, metrics):
        x, y = metrics["panel_x"], metrics["panel_y"]
        bar.geometry("{}x{}+{}+{}".format(
            metrics["switcher_width"], metrics["switcher_height"], max(0, x), max(0, y)))
        if os.name == "nt" and (x < 0 or y < 0):
            # Tk treats negative geometry offsets as distance from the far edge.
            try:
                bar.update_idletasks()
                user32 = ctypes.windll.user32
                user32.GetAncestor.argtypes = [ctypes.c_void_p, ctypes.c_uint]
                user32.GetAncestor.restype = ctypes.c_void_p
                user32.SetWindowPos.argtypes = [
                    ctypes.c_void_p, ctypes.c_void_p, ctypes.c_int, ctypes.c_int,
                    ctypes.c_int, ctypes.c_int, ctypes.c_uint]
                user32.SetWindowPos.restype = ctypes.c_int
                hwnd = user32.GetAncestor(ctypes.c_void_p(int(bar.winfo_id())), 2) or int(bar.winfo_id())
                user32.SetWindowPos(hwnd, None, x, y, 0, 0, 0x0001 | 0x0004 | 0x0010)
            except (AttributeError, OSError, TypeError, ValueError, tk.TclError):
                pass

    def _switch_runtime_portrait_outfit(self, outfit_id):
        import json

        character_config = copy.deepcopy(self.character_config)
        renderer_config = character_config.get("renderer", {})
        is_live2d = (
            isinstance(renderer_config, dict)
            and renderer_config.get("current") == "live2d"
        )
        outfits = self._portrait_outfits(character_config)
        selected = None
        if is_live2d:
            groups = self._live2d_runtime_outfit_groups(character_config)
            target_group = next(
                (group for group in groups if group["id"] == str(outfit_id)),
                None,
            )
            if target_group is None or not target_group["appearances"]:
                return False
            current_id = self._active_portrait_outfit_id(character_config)
            current = next(
                (item for item in outfits if item["id"] == current_id),
                None,
            )
            def pose_signature(appearance):
                parameters = appearance.get("parameters", {})
                if not isinstance(parameters, dict):
                    return ()
                # Match all discrete pose parameters so a clothing change keeps
                # the user's current pose whenever that pose exists.
                return tuple(sorted(
                    (str(key).casefold(), str(value))
                    for key, value in parameters.items()
                    if str(key).casefold().startswith("parampose")
                ))

            current_signature = pose_signature(current or {})
            selected = next(
                (
                    item for item in target_group["appearances"]
                    if current_signature and pose_signature(item) == current_signature
                ),
                target_group["appearances"][0],
            )
            if current_id == selected["id"]:
                return True
            outfit_id = selected["id"]
        elif not any(outfit["id"] == outfit_id for outfit in outfits):
            return False
        elif self._active_portrait_outfit_id(character_config) == outfit_id:
            return True
        portrait_rules = character_config.setdefault("portrait_rules", {})
        if not isinstance(portrait_rules, dict):
            portrait_rules = {}
            character_config["portrait_rules"] = portrait_rules
        if is_live2d:
            portrait_rules["active_appearance_id"] = outfit_id
        else:
            portrait_rules["active_outfit_id"] = outfit_id
        try:
            save_character_config(self.character_id, character_config)
        except (OSError, ValueError, json.JSONDecodeError) as error:
            messagebox.showerror(
                "切换服装失败",
                "无法保存当前服装：{}".format(error),
                parent=self.root,
            )
            return False
        self.character_config = character_config
        if is_live2d and isinstance(self.renderer, Live2DRenderer):
            if selected is not None:
                self.renderer.set_appearance(selected)
                self.renderer.viewport_settings = copy.deepcopy(
                    selected.get("local_viewport") or portrait_rules.get("local_viewport", {}))
                self._render_state()
                self._sync_control_snapshot_character(self.character_id)
                self._sync_live2d_settings_controls()
                return True
        self._clear_portrait_canvas()
        self._replace_portrait_renderer()
        self._render_state()
        self._sync_control_snapshot_character(self.character_id)
        return True

    def show_tray_menu(self):
        return self._show_tray_popup_menu()

    def _run_tray_action(self, action):
        self._close_tray_menu()
        self._close_context_actions()
        action()

    def _show_tray_popup_menu(self):
        if not self.root.winfo_exists():
            return
        current = getattr(self, "_tray_menu", None)
        if current is not None:
            try:
                if current.winfo_exists():
                    self._raise_tray_menu()
                    return
            except tk.TclError:
                pass

        self._close_context_actions()
        self._context_menu_navigation_source = "tray"
        actions = self._get_tray_menu_items()
        if not actions:
            return

        menu = tk.Toplevel(self.root)
        menu.withdraw()
        menu.overrideredirect(True)
        menu.transient(self.root)
        menu.configure(bg=self.theme["border"])
        self._tray_menu = menu
        self._tray_menu_opened_at = time.monotonic()

        border = tk.Frame(menu, bg=self.theme["border"], padx=1, pady=1)
        border.pack(fill="both", expand=True)
        columns = tk.Frame(border, bg=self.theme["border"])
        columns.pack(fill="both", expand=True)
        columns.grid_columnconfigure(0, weight=1)
        content = tk.Frame(columns, bg=self.theme["surface"])
        content.grid(row=0, column=0, sticky="nsew")
        rows = []
        submenu_state = {"frame": None, "command_id": None}

        try:
            pointer_x = int(self.root.winfo_pointerx())
            pointer_y = int(self.root.winfo_pointery())
            screen_x = int(self.root.winfo_vrootx())
            screen_y = int(self.root.winfo_vrooty())
            screen_width = int(self.root.winfo_vrootwidth())
            screen_height = int(self.root.winfo_vrootheight())
        except (AttributeError, TypeError, ValueError, tk.TclError):
            pointer_x = int(self.root.winfo_pointerx())
            pointer_y = int(self.root.winfo_pointery())
            screen_x = screen_y = 0
            screen_width = int(self.root.winfo_screenwidth())
            screen_height = int(self.root.winfo_screenheight())

        def position_menu():
            menu.update_idletasks()
            width = max(1, int(menu.winfo_reqwidth()))
            height = max(1, int(menu.winfo_reqheight()))
            x = max(screen_x, min(pointer_x, screen_x + screen_width - width))
            y = max(
                screen_y,
                min(pointer_y - height, screen_y + screen_height - height),
            )
            menu.geometry("{}x{}{:+d}{:+d}".format(width, height, x, y))

        def hide_submenu():
            frame = submenu_state["frame"]
            if frame is not None:
                try:
                    frame.destroy()
                except tk.TclError:
                    pass
            submenu_state["frame"] = None
            submenu_state["command_id"] = None
            position_menu()

        def show_submenu(command_id, children):
            if submenu_state["command_id"] == command_id:
                return
            hide_submenu()
            frame = tk.Frame(
                columns,
                bg=self.theme["surface"],
                highlightthickness=1,
                highlightbackground=self.theme["border"],
            )
            submenu_state["frame"] = frame
            submenu_state["command_id"] = command_id
            frame.grid(row=0, column=1, sticky="nsew")
            for child_id, child_label, child_callback, _grandchildren in children:
                add_row(
                    frame,
                    child_id,
                    child_label,
                    child_callback,
                    (),
                    True,
                )
            position_menu()

        def add_row(parent, command_id, label, callback, children, is_submenu):
            row = tk.Frame(parent, bg=self.theme["surface"], cursor="hand2")
            row.pack(fill="x")
            icon = tk.Canvas(
                row,
                width=18,
                height=18,
                bg=self.theme["surface"],
                highlightthickness=0,
                bd=0,
            )
            icon.pack(side="left", padx=(11, 9), pady=6)
            self._draw_tray_menu_icon(icon, label, self.theme["text"])
            text = tk.Label(
                row,
                text=label,
                anchor="w",
                bg=self.theme["surface"],
                fg=self.theme["text"],
                font=("Microsoft YaHei UI", 10),
                padx=0,
                pady=6,
                takefocus=False,
            )
            text.pack(side="left", fill="x", expand=True, padx=(0, 4))
            arrow = None
            widgets = [row, icon, text]
            if children:
                arrow = tk.Label(
                    row,
                    text="›",
                    bg=self.theme["surface"],
                    fg=self.theme["text"],
                    font=("Microsoft YaHei UI", 12),
                    padx=10,
                    pady=3,
                    takefocus=False,
                )
                arrow.pack(side="right")
                widgets.append(arrow)

            def set_hovered(hovered, row=row, icon=icon, text=text, arrow=arrow, label=label):
                background = (
                    self.theme["accent"] if hovered else self.theme["surface"]
                )
                foreground = (
                    self.theme["accent_text"] if hovered else self.theme["text"]
                )
                for widget in (row, icon, text, arrow):
                    if widget is None:
                        continue
                    widget.configure(bg=background)
                text.configure(fg=foreground)
                if arrow is not None:
                    arrow.configure(fg=foreground)
                self._draw_tray_menu_icon(icon, label, foreground)

            def on_enter(_event=None):
                set_hovered(True)
                if children:
                    show_submenu(command_id, children)
                elif not is_submenu:
                    hide_submenu()

            def on_click(_event=None):
                if children:
                    show_submenu(command_id, children)
                elif callback is not None:
                    self._run_tray_action(callback)
                return "break"

            for widget in tuple(widgets):
                widget.bind(
                    "<Enter>",
                    on_enter,
                )
                widget.bind(
                    "<Leave>",
                    lambda _event: set_hovered(False),
                )
                widget.bind("<Button-1>", on_click)
            rows.append(row)

        for command_id, label, callback, children in actions:
            add_row(content, command_id, label, callback, children, False)
        self._tray_menu_rows = rows
        self._tray_menu_submenu = submenu_state
        menu.bind("<Escape>", lambda _event: self._close_tray_menu())
        menu.bind(
            "<FocusOut>",
            lambda _event, current_menu=menu: self._schedule_tray_menu_focus_close(
                current_menu
            ),
        )

        position_menu()
        menu.deiconify()
        menu.focus_force()
        self._raise_tray_menu()
        self._tray_menu_focus_after_id = self.root.after(
            30, self._poll_tray_menu_focus
        )

    @staticmethod
    def _draw_tray_menu_icon(canvas, label, color):
        canvas.delete("all")
        if label in ("局部模式", "全身模式"):
            canvas.create_rectangle(2, 3, 16, 14, outline=color, width=1.5)
            canvas.create_line(6, 16, 12, 16, fill=color, width=1.5)
            canvas.create_line(9, 14, 9, 16, fill=color, width=1.5)
        elif label == "切换服装":
            canvas.create_line(6, 4, 9, 6, 12, 4, fill=color, width=1.5)
            canvas.create_line(9, 6, 9, 8, fill=color, width=1.5)
            canvas.create_line(9, 8, 4, 14, 14, 14, 9, 8, fill=color, width=1.5)
        elif label in ("置顶", "取消置顶"):
            canvas.create_oval(6, 2, 12, 8, outline=color, width=1.5)
            canvas.create_line(9, 8, 9, 15, fill=color, width=1.5)
            canvas.create_line(5, 12, 13, 12, fill=color, width=1.5)
            canvas.create_line(9, 15, 6, 17, fill=color, width=1.5)
        elif label == "输入":
            canvas.create_line(3, 4, 2, 4, 2, 15, 14, 15, 14, 11, fill=color, width=1.5)
            canvas.create_polygon(6, 9, 12, 3, 15, 6, 9, 12, 5, 13,
                                  fill="", outline=color, width=1.5)
            canvas.create_line(11, 4, 14, 7, fill=color, width=1.5)
        elif label in ("角色", "切换角色"):
            canvas.create_oval(6, 2, 12, 8, outline=color, width=1.5)
            canvas.create_arc(3, 10, 15, 20, start=0, extent=180, style="arc", outline=color, width=1.5)
        elif label == "任务提醒":
            canvas.create_arc(4, 3, 14, 13, start=0, extent=180, style="arc", outline=color, width=1.5)
            canvas.create_line(4, 8, 4, 11, 2, 13, 16, 13, 14, 11, 14, 8, fill=color, width=1.5)
            canvas.create_line(9, 1, 9, 3, fill=color, width=1.5)
            canvas.create_arc(7, 13, 11, 17, start=180, extent=180, style="arc", outline=color, width=1.5)
        elif label in ("历史记录", "历史对话"):
            canvas.create_arc(2, 2, 16, 16, start=140, extent=-300, style="arc", outline=color, width=1.5)
            canvas.create_line(2, 2, 2, 6, 6, 6, fill=color, width=1.5)
            canvas.create_line(9, 5, 9, 9, 12, 11, fill=color, width=1.5)
        elif label in ("开启鼠标穿透", "关闭鼠标穿透"):
            canvas.create_polygon(4, 2, 4, 13, 7, 10, 10, 16, 12, 15, 9, 9, 14, 9,
                                  fill="", outline=color, width=1.5)
            if label == "开启鼠标穿透":
                canvas.create_line(12, 3, 16, 3, 14, 1, fill=color, width=1.5)
                canvas.create_line(16, 3, 14, 5, fill=color, width=1.5)
            else:
                canvas.create_line(12, 2, 16, 6, fill=color, width=1.5)
                canvas.create_line(16, 2, 12, 6, fill=color, width=1.5)
        elif label == "调节":
            for x, y in ((3, 6), (9, 12), (15, 8)):
                canvas.create_line(x, 2, x, 16, fill=color, width=1.5)
                canvas.create_line(x - 2, y, x + 2, y, fill=color, width=2)
        elif label == "设置":
            canvas.create_oval(4, 4, 14, 14, outline=color, width=1.5)
            canvas.create_oval(7, 7, 11, 11, outline=color, width=1.2)
            for start, end in (
                ((9, 1), (9, 4)),
                ((9, 14), (9, 17)),
                ((1, 9), (4, 9)),
                ((14, 9), (17, 9)),
                ((3, 3), (5, 5)),
                ((13, 13), (15, 15)),
                ((13, 5), (15, 3)),
                ((3, 15), (5, 13)),
            ):
                canvas.create_line(*start, *end, fill=color, width=1.5)
        elif label == "退出桌宠":
            canvas.create_arc(2, 2, 16, 16, start=130, extent=280, style="arc", outline=color, width=1.5)
            canvas.create_line(9, 1, 9, 9, fill=color, width=1.8)

    def _close_tray_menu(self):
        menu = getattr(self, "_tray_menu", None)
        after_id = getattr(self, "_tray_menu_focus_after_id", None)
        focus_leave_after_id = getattr(
            self,
            "_tray_menu_focus_leave_after_id",
            None,
        )
        if menu is not None and after_id is not None:
            try:
                self.root.after_cancel(after_id)
            except tk.TclError:
                pass
        if focus_leave_after_id is not None:
            try:
                self.root.after_cancel(focus_leave_after_id)
            except tk.TclError:
                pass
        self._tray_menu_focus_after_id = None
        self._tray_menu_focus_leave_after_id = None
        self._tray_menu_opened_at = 0.0
        self._tray_menu_rows = []
        self._tray_menu_submenu = None
        if menu is not None:
            try:
                if menu.winfo_exists():
                    menu.destroy()
            except tk.TclError:
                pass
        self._tray_menu = None

    def _raise_tray_menu(self):
        menu = getattr(self, "_tray_menu", None)
        if menu is None or not menu.winfo_exists():
            return
        try:
            menu.wm_attributes("-topmost", True)
            menu.lift()
            menu.after_idle(
                lambda: self._raise_tray_menu_if_current(menu)
            )
        except tk.TclError:
            pass

    def _raise_tray_menu_if_current(self, menu):
        if getattr(self, "_tray_menu", None) is not menu:
            return
        try:
            if menu.winfo_exists():
                menu.wm_attributes("-topmost", True)
                menu.lift()
        except tk.TclError:
            pass

    def _tray_menu_contains_focus(self):
        menu = getattr(self, "_tray_menu", None)
        if menu is None or not menu.winfo_exists():
            return False
        focused = self.root.focus_get()
        if focused is None:
            return False
        focused_path = str(focused)
        menu_path = str(menu)
        return focused_path == menu_path or focused_path.startswith(menu_path + ".")

    def _close_tray_menu_if_focus_left(self, expected_menu=None):
        if (
            expected_menu is not None
            and getattr(self, "_tray_menu", None) is not expected_menu
        ):
            return
        if not self._tray_menu_contains_focus():
            self._close_tray_menu()

    def _schedule_tray_menu_focus_close(self, expected_menu):
        previous_after_id = getattr(
            self,
            "_tray_menu_focus_leave_after_id",
            None,
        )
        if previous_after_id is not None:
            try:
                self.root.after_cancel(previous_after_id)
            except tk.TclError:
                pass
        holder = {}
        after_id = self.root.after(
            35,
            lambda: self._run_tray_menu_focus_check(
                expected_menu,
                holder.get("after_id"),
            ),
        )
        holder["after_id"] = after_id
        self._tray_menu_focus_leave_after_id = after_id

    def _run_tray_menu_focus_check(self, expected_menu, after_id):
        if getattr(self, "_tray_menu_focus_leave_after_id", None) != after_id:
            return
        self._tray_menu_focus_leave_after_id = None
        self._close_tray_menu_if_focus_left(expected_menu)

    def _poll_tray_menu_focus(self):
        menu = getattr(self, "_tray_menu", None)
        if menu is None or not menu.winfo_exists():
            self._tray_menu_focus_after_id = None
            return
        if time.monotonic() - float(
            getattr(self, "_tray_menu_opened_at", 0.0)
        ) < 0.7:
            self._tray_menu_focus_after_id = self.root.after(
                100, self._poll_tray_menu_focus
            )
            return
        try:
            user32 = ctypes.windll.user32
            user32.GetCursorPos.argtypes = [ctypes.POINTER(wintypes.POINT)]
            user32.GetCursorPos.restype = ctypes.c_int
            user32.GetWindowRect.argtypes = [
                ctypes.c_void_p,
                ctypes.POINTER(wintypes.RECT),
            ]
            user32.GetWindowRect.restype = ctypes.c_int
            user32.GetAsyncKeyState.argtypes = [ctypes.c_int]
            user32.GetAsyncKeyState.restype = ctypes.c_short
            menu_hwnd = int(menu.winfo_id())
            point = wintypes.POINT()
            rect = wintypes.RECT()
            cursor_inside = False
            if user32.GetCursorPos(ctypes.byref(point)) and user32.GetWindowRect(
                menu_hwnd, ctypes.byref(rect)
            ):
                cursor_inside = (
                    rect.left <= point.x < rect.right
                    and rect.top <= point.y < rect.bottom
                )
            # 只读取当前按下状态。低位是“自上次查询以来曾按下”的
            # 历史标记，会把打开菜单前的右键误判成新的外部点击。
            mouse_down = bool(
                user32.GetAsyncKeyState(0x01) & 0x8000
                or user32.GetAsyncKeyState(0x02) & 0x8000
            )
        except (AttributeError, OSError, tk.TclError, TypeError, ValueError):
            cursor_inside = True
            mouse_down = False
        if mouse_down and not cursor_inside:
            self._close_tray_menu()
            return
        self._tray_menu_focus_after_id = self.root.after(
            30, self._poll_tray_menu_focus
        )

    def _schedule_task_poll(self):
        if self.root.winfo_exists():
            self._task_poll_after_id = self.root.after(1000, self._poll_tasks)

    def _poll_tasks(self):
        if not self.root.winfo_exists():
            return
        before_revision = self.task_store.revision
        due_tasks = self.task_store.due()
        for task in due_tasks:
            title = "任务提醒"
            text = str(task.get("title", "有一个任务到时间了"))
            if self.tray is not None:
                self.tray.notify(title, text)
            self._handle_task_event(task, phase="due")
        refresh_tasks = getattr(self, "_refresh_control_tasks_view", None)
        if callable(refresh_tasks) and (
            due_tasks or self.task_store.revision != before_revision
        ):
            refresh_tasks()
        self._schedule_task_poll()

    def _configure_companionship(self):
        after_id = getattr(self, "_companionship_after_id", None)
        if after_id is not None:
            try:
                self.root.after_cancel(after_id)
            except tk.TclError:
                pass
            self._companionship_after_id = None
        companionship = self.app_config.setdefault(
            "autonomous_conversation",
            {
                "enabled": False,
                "interval_minutes": 60,
                "vision_enabled": False,
            },
        )
        if not bool(companionship.get("enabled", False)):
            prepared = self._companionship_prepared
            self._companionship_prepared = None
            self._companionship_generating = False
            if isinstance(prepared, dict) and prepared.get("audio_path"):
                Path(prepared["audio_path"]).unlink(missing_ok=True)
            return
        vision_enabled = bool(companionship.get("vision_enabled", False))
        if vision_enabled:
            # 视觉模式在统一间隔到达时才截图，不提前生成普通文字或语音。
            prepared = self._companionship_prepared
            self._companionship_prepared = None
            if isinstance(prepared, dict) and prepared.get("audio_path"):
                Path(prepared["audio_path"]).unlink(missing_ok=True)
            if self._companionship_generating:
                self._companionship_after_id = self._safe_root_after(
                    1000,
                    self._poll_companionship,
                )
                return
        try:
            idle_minutes = max(
                1,
                min(1440, int(companionship.get("interval_minutes", 60))),
            )
        except (TypeError, ValueError):
            idle_minutes = 60
        companionship["interval_minutes"] = idle_minutes
        idle_seconds = idle_minutes * 60
        elapsed = max(
            0.0,
            time.monotonic() - self._companionship_last_activity,
        )
        remaining_seconds = max(1.0, idle_seconds - elapsed)
        # 提前准备完整的文字和语音，给服务启动和首次加载留出余量。
        prepare_window = min(120.0, max(30.0, idle_seconds * 0.25))
        delay_seconds = (
            remaining_seconds
            if vision_enabled
            else max(1.0, remaining_seconds - prepare_window)
        )
        self._companionship_after_id = self._safe_root_after(
            int(delay_seconds * 1000),
            self._poll_companionship,
        )

    def _mark_companionship_activity(self):
        activity_after_id = getattr(
            self,
            "_companionship_activity_after_id",
            None,
        )
        if activity_after_id is not None:
            try:
                self.root.after_cancel(activity_after_id)
            except tk.TclError:
                pass
            self._companionship_activity_after_id = None
        self._companionship_activity_pending = False
        self._companionship_last_activity = time.monotonic()
        self._companionship_prepare_generation += 1
        self._companionship_generating = False
        prepared = self._companionship_prepared
        self._companionship_prepared = None
        if isinstance(prepared, dict):
            path = prepared.get("audio_path")
            if path:
                Path(path).unlink(missing_ok=True)
        self._configure_companionship()

    def _record_non_drag_activity(self, event=None):
        """在用户操作事件处理完成后重置自主对话计时。"""
        if event is not None and self._is_portrait_widget(getattr(event, "widget", None)):
            if getattr(event, "num", None) == self._mouse_button_number(
                self._get_operation_mapping("drag", "鼠标左键")
            ):
                return None
        if getattr(event, "keysym", ""):
            self._user_typing_until = time.monotonic() + 1.5
        self._companionship_activity_pending = True
        after_id = getattr(self, "_companionship_activity_after_id", None)
        if after_id is not None:
            try:
                self.root.after_cancel(after_id)
            except tk.TclError:
                pass
        self._companionship_activity_after_id = self.root.after_idle(
            self._complete_companionship_activity
        )
        return None

    def _complete_companionship_activity(self):
        self._companionship_activity_after_id = None
        self._mark_companionship_activity()

    def _configure_companionship_activity_bindings(self):
        self.root.bind_all("<ButtonPress>", self._record_non_drag_activity, add="+")
        self.root.bind_all("<KeyPress>", self._record_non_drag_activity, add="+")
        self.root.bind_all("<MouseWheel>", self._record_non_drag_activity, add="+")

    def _companionship_can_interrupt(self):
        return (
            not getattr(self, "_conversation_in_progress", False)
            and not getattr(self, "_tts_playback_active", False)
            and not self.screenshot_in_progress
            and not getattr(self, "_task_event_active", False)
            and not getattr(self, "_control_draft_active", False)
            and not getattr(self, "_companionship_activity_pending", False)
        )

    def _poll_companionship(self):
        self._companionship_after_id = None
        companionship = self.app_config.setdefault(
            "autonomous_conversation",
            {
                "enabled": False,
                "interval_minutes": 60,
                "vision_enabled": False,
            },
        )
        if not bool(companionship.get("enabled", False)):
            return
        vision_enabled = bool(companionship.get("vision_enabled", False))
        try:
            idle_minutes = max(
                1,
                min(1440, int(companionship.get("interval_minutes", 60))),
            )
        except (TypeError, ValueError):
            idle_minutes = 60
        now = time.monotonic()
        idle_seconds = idle_minutes * 60
        elapsed = max(0.0, now - self._companionship_last_activity)
        can_interrupt = self._companionship_can_interrupt()
        prepared = self._companionship_prepared
        if (
            elapsed >= idle_seconds
            and can_interrupt
        ):
            if vision_enabled:
                if not self._companionship_generating:
                    self._companionship_generating = True
                    try:
                        started = self.take_screenshot(send_to_pet=True)
                        if not started:
                            self._companionship_generating = False
                    except Exception as error:
                        self._companionship_generating = False
                        self._runtime_errors.append(
                            "自主对话视觉模块：{}".format(error)
                        )
            else:
                self._companionship_prepared = None
                if isinstance(prepared, dict) and prepared.get(
                    "generation"
                ) == self._companionship_prepare_generation:
                    self._finish_companionship_greeting(
                        prepared.get("greeting", ""),
                        audio_path=prepared.get("audio_path"),
                    )
                elif not self._companionship_generating:
                    self._companionship_generating = True
                    threading.Thread(
                        target=self._generate_companionship_greeting,
                        daemon=True,
                    ).start()
        elif (
            not vision_enabled
            and
            elapsed >= max(0.0, idle_seconds - min(120.0, max(30.0, idle_seconds * 0.25)))
            and not self._companionship_generating
            and not isinstance(prepared, dict)
        ):
            self._companionship_generating = True
            generation = self._companionship_prepare_generation
            threading.Thread(
                target=self._prepare_companionship_greeting,
                args=(generation,),
                daemon=True,
            ).start()
        self._configure_companionship()

    def _generate_companionship_greeting(self):
        self._generate_companionship_greeting_result(
            self._companionship_prepare_generation,
            prepare_audio=False,
        )

    def _generate_companionship_greeting_result(self, generation, prepare_audio):
        if generation != self._companionship_prepare_generation:
            return
        character_id = self.character_id
        system_prompt = self._companionship_system_prompt()
        try:
            companionship = self.app_config.setdefault(
                "autonomous_conversation",
                {"enabled": False, "interval_minutes": 60},
            )
            recent = list(companionship.get("recent_greetings_by_character", {}).get(character_id, []))[-10:]
            prompt = (
                "请为用户开启一段自然的自主对话，使用简体中文。通常以约50个汉字以内的"
                "自然短句为长度倾向，但这不是硬性字数上限；需要承接上下文或表达完整意思时"
                "可以适当展开，不要截断。内容应完整、语义连贯，不要为了简短省略必要内容，"
                "也不要堆砌无关内容。"
                "要贴合当前角色的个性和说话方式，像角色本人自然地开口，"
                "不要提到模型、提示词、系统、定时器或你在等待。"
                "结合当前时间自然问候，但不要每次使用相同句式；情绪要体现在用词、语气词和句式里，"
                "不能只依赖情绪标记。"
                "请在句首添加一个情绪标记，格式必须是[emotion:状态]，"
                "状态只能使用角色已有的情绪名称；标记后直接输出回应，"
                "不要引号或解释。"
            )
            if recent:
                prompt += "\n以下是最近说过的话，请避免重复或只改几个字：\n" + "\n".join(recent)
            history_messages = []
            for record in self.store.get_current_messages(character_id=character_id)[-20:]:
                role = record.get("role")
                content = str(record.get("content", "")).strip()
                if role not in ("user", "assistant") or not content:
                    continue
                if role == "assistant":
                    content = self._visible_reply_text(content)
                if content:
                    history_messages.append({"role": role, "content": content})
            if history_messages:
                prompt += (
                    "\n当前启动期间的对话仅作为自然参考：如果与本次自主对话有关，可以顺势承接；"
                    "无关时不要硬提旧内容，也不要机械复述上文。"
                )
            client = ConversationClient(self.app_config.get("conversation_model", {}))
            greeting = client._complete_messages(
                [
                    {"role": "system", "content": system_prompt},
                    *history_messages,
                    {"role": "user", "content": prompt},
                ],
                temperature=0.9,
                max_tokens=client._integer("max_tokens", 1024),
            ).strip()
            if not greeting:
                raise ConversationError("自主对话内容无效")
            if not re.search(r"\[emotion:[^\]]+\]", greeting, re.IGNORECASE):
                greeting = "[emotion:{}] {}".format(
                    self._companionship_emotion_key(),
                    greeting,
                )
        except Exception as error:
            self._runtime_errors.append("自主对话：{}".format(error))
            greeting = self._companionship_fallback()
        if generation != self._companionship_prepare_generation or character_id != self.character_id:
            return
        if prepare_audio:
            audio_path = None
            try:
                audio_path = self._prepare_companionship_audio(greeting)
            except Exception as error:
                self._runtime_errors.append(
                    "自主对话语音：{}；文本：{}".format(
                        error,
                        self._tts_text(greeting)[:80],
                    )
                )
            self._safe_root_after(
                0,
                lambda greeting=greeting, audio_path=audio_path, generation=generation:
                self._finish_companionship_preparation(
                    greeting, audio_path, generation
                ),
            )
        else:
            self._safe_root_after(
                0,
                lambda greeting=greeting, generation=generation:
                self._finish_companionship_preparation(
                    greeting,
                    None,
                    generation,
                ),
            )

    def _prepare_companionship_greeting(self, generation):
        self._generate_companionship_greeting_result(generation, prepare_audio=True)

    def _finish_companionship_preparation(self, greeting, audio_path, generation):
        if generation != self._companionship_prepare_generation:
            if audio_path:
                Path(audio_path).unlink(missing_ok=True)
            return
        companionship = self.app_config.setdefault(
            "autonomous_conversation",
            {
                "enabled": False,
                "interval_minutes": 60,
                "vision_enabled": False,
            },
        )
        if bool(companionship.get("vision_enabled", False)):
            if audio_path:
                Path(audio_path).unlink(missing_ok=True)
            self._companionship_generating = False
            return
        self._companionship_generating = False
        if not self._has_tts_content(self._tts_text(greeting)):
            greeting = self._companionship_fallback()
        try:
            idle_minutes = max(
                1,
                min(1440, int(companionship.get("interval_minutes", 60))),
            )
        except (TypeError, ValueError):
            idle_minutes = 60
        now = time.monotonic()
        idle_seconds = idle_minutes * 60
        elapsed = max(0.0, now - self._companionship_last_activity)
        can_interrupt = self._companionship_can_interrupt()
        if (
            elapsed >= idle_seconds
            and can_interrupt
        ):
            # 预生成跨过了触发时间，直接展示本轮文字，避免错过轮询窗口。
            self._companionship_prepared = None
            self._finish_companionship_greeting(greeting, audio_path=audio_path)
            return
        self._companionship_prepared = {
            "generation": generation,
            "greeting": greeting,
            "audio_path": audio_path,
        }

    def _archive_tts_audio(self, source, character_name=None):
        """把完整生成的语音归档到用户配置目录，并保留历史文件。"""
        return archive_voice_file(
            source,
            self.app_config.get("voice_directory"),
            character_name=character_name or self._character_display_name(),
        )

    def _prepare_companionship_audio(self, greeting):
        if not self.store.settings.get("voice_output", True):
            return None
        language = self.output_language
        reference = self._resolve_tts_reference(language, self._tts_emotion_keys(greeting))
        if reference is None:
            raise RuntimeError("当前角色没有{}参考音频".format(
                OUTPUT_LANGUAGE_NAMES.get(language, "当前语言")))
        reference_audio, prompt_text, prompt_lang = reference
        text_lang = self._tts_model_language(language)
        self._warmup_tts_reference(
            reference_audio, prompt_text, text_lang, prompt_lang, language,
            generation_params=self._tts_generation_params(language),
        )
        source_text = self._tts_source_text(greeting, language)
        translator = ConversationClient(self.app_config.get("conversation_model", {})).translate_text
        audio_path, _verdict, _spoken_text = self._synthesize_reliable_tts_segment(
            source_text, None, reference_audio, prompt_text, text_lang, prompt_lang,
            language, translator=translator,
        )
        if audio_path is None:
            raise RuntimeError("自主对话语音未生成。")
        self._validate_complete_tts_audio(audio_path, source_text)
        return audio_path

    def _companionship_system_prompt(self):
        name = self._character_display_name()
        personality = str(self.character_config.get("personality", "")).strip()
        emotion_names = list(self._available_state_labels())
        return (
            "你是{}。你的角色个性是：{}。通常生成约50个汉字以内的自然、克制、贴合角色的"
            "中文陪伴短句，但这只是长度倾向；为了表达完整意思或承接上下文可以适当展开，"
            "不得截断。"
            "根据语气选择一个最符合内容的情绪标记，情绪状态键只能从[{}]中选择。"
            "如果提供了当前启动期间的对话历史，只在确实相关时自然承接，不要机械复述。"
        ).format(name, personality or "亲切自然", ", ".join(emotion_names)) + "\n" + DESKTOP_PET_BASE_BEHAVIOR + "\n" + user_address_prompt(self.character_config)

    def _companionship_emotion_key(self):
        keys = self._tts_emotion_keys("", self.state)
        return keys[0] if keys else "平静"

    def _companionship_fallback(self):
        hour = datetime.now().hour
        address = resolve_user_address(self.character_config, "zh")
        salutation = address + "，" if address else ""
        emotion = self._companionship_emotion_key()
        if 5 <= hour < 11:
            text = "{}早上好呀。先喝点水，再陪我聊一会儿吧？".format(salutation)
        elif 11 <= hour < 14:
            text = "{}午间别忘了休息一下哦，我陪你放松一会儿。".format(salutation)
        elif 14 <= hour < 19:
            text = "{}下午还顺利吗？累了就靠过来歇一会儿吧。".format(salutation)
        else:
            text = "{}今天辛苦了。别绷着啦，我陪你聊一会儿。".format(salutation)
        return "[emotion:{}] {}".format(emotion, text)

    def _finish_companionship_greeting(self, greeting, audio_path=None):
        self._restore_character_conversation(create_if_missing=True)
        self._companionship_generating = False
        visible_greeting = self._visible_reply_text(greeting)
        if (
            not self._has_tts_content(self._tts_text(greeting))
            or not visible_greeting
        ):
            greeting = self._companionship_fallback()
            visible_greeting = self._visible_reply_text(greeting)
        companionship = self.app_config.setdefault(
            "autonomous_conversation",
            {"enabled": False, "interval_minutes": 60},
        )
        recent_by_character = companionship.setdefault("recent_greetings_by_character", {})
        recent = list(recent_by_character.get(self.character_id, []))
        recent.append(greeting)
        recent_by_character[self.character_id] = recent[-10:]
        save_app_config(self.app_config)
        self.store.add_message(
            "assistant",
            visible_greeting,
            character_id=self.character_id,
            character_name=self._character_display_name(),
        )
        self._append_inline_chat("assistant", greeting)
        self._schedule_idle_restore()
        self._mark_companionship_activity()
        if bool(self.store.settings.get("voice_output", True)):
            if audio_path and Path(audio_path).is_file():
                self._start_tts_for_prepared_reply(greeting, audio_path)
            else:
                self._start_tts_for_reply(
                    greeting,
                    on_failure=lambda _message: self._schedule_inline_panels_auto_hide(),
                    on_playback_finished=self._schedule_inline_panels_auto_hide,
                )

    def _start_tts_for_prepared_reply(self, greeting, audio_path):
        self._safe_root_after(0, lambda: self._set_tts_error(False))
        self._safe_root_after(0, lambda: self._set_tts_status("语音播报中……"))
        self._tts_request_id += 1
        request_id = self._tts_request_id
        self._stop_tts_playback()

        def worker():
            archived_path = None
            try:
                if request_id != self._tts_request_id:
                    return
                self._validate_complete_tts_audio(audio_path, self._tts_text(greeting))
                archived_path = self._archive_tts_audio(audio_path)
                try:
                    self._validate_complete_tts_audio(
                        archived_path,
                        self._tts_text(greeting),
                    )
                except Exception:
                    Path(archived_path).unlink(missing_ok=True)
                    raise
                Path(audio_path).unlink(missing_ok=True)
                playback_ok = False
                for playback_attempt in range(3):
                    playback_ok = self._play_tts_file(archived_path, request_id)
                    if playback_ok or request_id != self._tts_request_id:
                        break
                    if playback_attempt < 2:
                        # MCI 打开/播放可能只是初始化尚未完成，给它下一次恢复机会。
                        time.sleep(0.15 * (playback_attempt + 1))
                if not playback_ok:
                    # 请求已被新语音取代或主动取消时，不应显示“生成错误”。
                    if request_id != self._tts_request_id:
                        return
                    raise RuntimeError("预生成问候语音播放失败")
                self._last_tts_path = archived_path
                self._safe_root_after(0, lambda: self._set_tts_status("语音输出完成"))
                self._safe_root_after(0, self._schedule_inline_panels_auto_hide)
            except Exception as error:
                if archived_path is None:
                    Path(audio_path).unlink(missing_ok=True)
                self._runtime_errors.append("陪伴问候语音播放：{}".format(error))
                if request_id == self._tts_request_id:
                    self._safe_root_after(
                        0,
                        lambda request_id=request_id: self._set_tts_error_for_request(
                            request_id,
                            True,
                        ),
                    )
                    self._safe_root_after(0, self._schedule_inline_panels_auto_hide)

        threading.Thread(target=worker, daemon=True).start()
    def _start_global_hotkeys(self):
        existing_manager = getattr(self, "hotkey_manager", None)
        if existing_manager is not None:
            existing_manager.stop()
        bindings = []
        callbacks = (
            ("toggle_topmost", self.toggle_topmost, None),
            ("screenshot", self.take_screenshot_and_send, None),
            ("quit", self.quit_app, None),
        )
        for key, callback, release_callback in callbacks:
            label = self.shortcuts.get(key, "")
            try:
                modifiers, virtual_key = parse_hotkey(label)
            except ValueError as error:
                self._safe_root_after(
                    0,
                    lambda error=error: self._show_runtime_notice(str(error)),
                )
                continue
            binding = (
                modifiers,
                virtual_key,
                lambda callback=callback: self._safe_root_after(0, callback),
                label,
            )
            if release_callback is not None:
                binding += (
                    lambda callback=release_callback: self._safe_root_after(0, callback),
                )
            bindings.append(binding)
        self.hotkey_manager = WindowsHotkeyManager(
            bindings,
            on_error=lambda text: self._safe_root_after(
                0, lambda: self._show_runtime_notice(text)
            ),
        )
        self.hotkey_manager.start()

    @staticmethod
    def _tk_shortcut(value):
        parts = [part.strip() for part in str(value or "").split("+") if part.strip()]
        if not parts:
            return "<Control-KeyPress-q>"
        key = parts[-1].lower()
        modifiers = []
        for part in parts[:-1]:
            normalized = part.lower()
            if normalized in ("ctrl", "control"):
                modifiers.append("Control")
            elif normalized == "shift":
                modifiers.append("Shift")
            elif normalized == "alt":
                modifiers.append("Alt")
        key_names = {
            # 配置文件使用 Windows/用户界面的名称，Tk 使用自己的 keysym 名称。
            "esc": "Escape",
            "escape": "Escape",
            "enter": "Return",
            "return": "Return",
            "space": "space",
            "backspace": "BackSpace",
        }
        key = key_names.get(key, key)
        prefix = "-".join(modifiers)
        return "<{}KeyPress-{}>".format(prefix + "-" if prefix else "", key)

