    def switch_character(self, character_id):
        try:
            from core.package_signature import authorize_character
            from core.environment import live2d_present
            manifest = authorize_character(get_character_dir(character_id))
            if manifest and not live2d_present():
                raise ValueError("未安装 Live2D 组件，请使用含 Live2D 组件的本体，或选择立绘角色。")
        except (OSError, ValueError) as error:
            messagebox.showerror("角色切换失败", str(error), parent=self.root)
            return False
        self._clear_character_theme_preview(apply=False)
        if character_id == self.character_id:
            self._apply_character_chat_theme()
            self._refresh_character_labels()
            self._sync_control_character_selection()
            return
        self._set_live2d_voice_activity(False)
        character_dir = get_character_dir(character_id)
        if not (character_dir / "character.json").exists():
            return
        self._invalidate_conversation_request()
        self._tts_request_id = getattr(self, "_tts_request_id", 0) + 1
        self._stop_tts_playback()
        self._mark_companionship_activity()
        self._hide_inline_reply()
        self._clear_portrait_canvas()
        self.character_id = character_id
        self.character_dir = character_dir
        self.character_config = load_character_config(character_id)
        self.voice_config = load_voice_config(character_id)
        self._restore_character_conversation()
        self._restore_history(replace=True)
        self.output_language = self._default_output_language()
        self._replace_portrait_renderer(character_dir)
        self.portrait_scale = self._load_portrait_scale()
        self.state = "idle"
        self.store.save_settings({"character_id": character_id})
        self._sync_control_character_selection()
        self._refresh_character_labels()
        self._refresh_state_buttons()
        self._update_language_buttons()
        self._apply_character_chat_theme()
        self._render_state()
        self._refresh_live2d_settings_section()
        self._safe_root_after(0, self._warmup_tts_service)
        refresh_memory = getattr(self, "_refresh_control_memory_view", None)
        if callable(refresh_memory):
            refresh_memory()

    def _sync_control_character_selection(self):
        """A runtime switch must not be undone by an older settings draft."""
        self._pending_character_id = self.character_id
        snapshot = getattr(self, "_control_snapshot", None)
        if isinstance(snapshot, dict):
            for key in ("character_id", "character_config", "voice_config", "character_dir", "portrait_scale"):
                snapshot[key] = copy.deepcopy(getattr(self, key))
            saved_settings = snapshot.setdefault("settings", {})
            for key in ("character_id", "active_conversation_ids", "current_conversation_id"):
                if key in self.store.settings:
                    saved_settings[key] = copy.deepcopy(self.store.settings[key])
        self._sync_control_character_cards()
        for attr, text in (("_control_role_badge", "当前角色：{}".format(self._character_display_name())),
                           ("_control_header_subtitle", "DESKTOP PET  /  {}".format(self._character_display_name().upper()))):
            widget = getattr(self, attr, None)
            if widget is not None:
                try:
                    widget.configure(text=text)
                except tk.TclError:
                    pass

    def _restore_character_conversation(self, create_if_missing=False):
        """恢复当前角色自己的会话；从未聊过的角色在首次发言时创建。"""
        if create_if_missing and not self.store.current_conversation_id:
            self.store.ensure_character_conversation(self.character_id, self._character_display_name())
            return
        owner_id, _ = self.store.get_conversation_character(self.store.current_conversation_id)
        if self.store.current_conversation_id and owner_id == self.character_id:
            return
        restored = self.store.restore_current_conversation(
            character_id=self.character_id, allow_recent_fallback=True,
        )
        if restored is None and create_if_missing:
            self.store.ensure_character_conversation(self.character_id, self._character_display_name())

    def _clear_portrait_canvas(self):
        canvas = getattr(self, "portrait_canvas", None)
        if canvas is None:
            return
        try:
            canvas.delete("all")
        except tk.TclError:
            pass

    def _character_display_name(self):
        return self.character_config.get("display_name", self.character_id) or self.character_id

    @staticmethod
    def _normalize_portrait_state_key(value):
        value = str(value or "").strip().lower()
        return value if re.fullmatch(r"[a-z0-9_]+", value) else ""

    @staticmethod
    def _split_state_keywords(value):
        if isinstance(value, (list, tuple, set)):
            values = value
        else:
            values = re.split(r"[,，、;\n]+", str(value or ""))
        return [
            str(item).strip()
            for item in values
            if str(item).strip()
        ]

    @staticmethod
    def _single_portrait_asset_map(assets):
        if not isinstance(assets, dict):
            return {}
        source = assets.get("full")
        return {"full": copy.deepcopy(source)} if source else {}

    @staticmethod
    def _normalize_portrait_action_id(value):
        raw = str(value or "").strip().lower()
        if raw in ("", "default"):
            return ""
        normalized = re.sub(r"[^a-z0-9_]+", "_", raw).strip("_")
        return normalized

    @staticmethod
    def _normalize_portrait_action_assets(assets):
        if not isinstance(assets, dict):
            return {}
        return {
            str(state): DesktopPetApp._single_portrait_asset_map(state_assets)
            for state, state_assets in assets.items()
        }

    @staticmethod
    def _normalize_portrait_outfit_actions(raw_outfit):
        raw_actions = (
            raw_outfit.get("actions", [])
            if isinstance(raw_outfit, dict)
            else []
        )
        if not isinstance(raw_actions, list):
            return []
        actions = []
        seen_ids = set()
        for index, raw_action in enumerate(raw_actions):
            if not isinstance(raw_action, dict):
                continue
            action_id = DesktopPetApp._normalize_portrait_action_id(
                raw_action.get("id", "")
            )
            if not action_id or action_id in seen_ids:
                continue
            seen_ids.add(action_id)
            name = str(
                raw_action.get("name", "")
                or raw_action.get("folder_name", "")
            ).strip() or "动作 {}".format(index + 1)
            folder_name = str(
                raw_action.get("folder_name", "") or name
            ).strip() or name
            actions.append(
                {
                    **copy.deepcopy(raw_action),
                    "id": action_id,
                    "name": name,
                    "folder_name": folder_name,
                    "portrait_assets": DesktopPetApp._normalize_portrait_action_assets(
                        raw_action.get("portrait_assets", {})
                    ),
                }
            )
        return actions

    @staticmethod
    def _portrait_outfits(character_config):
        config = character_config if isinstance(character_config, dict) else {}
        renderer = config.get("renderer", {})
        if (
            isinstance(renderer, dict)
            and renderer.get("current") == "live2d"
        ):
            raw_appearances = renderer.get("appearance_options", [])
            appearances = []
            seen_ids = set()
            if isinstance(raw_appearances, list):
                for index, raw_appearance in enumerate(raw_appearances):
                    if not isinstance(raw_appearance, dict):
                        continue
                    appearance_id = re.sub(
                        r"[^a-z0-9_]+",
                        "_",
                        str(raw_appearance.get("id", "")).strip().lower(),
                    ).strip("_")
                    if not appearance_id or appearance_id in seen_ids:
                        continue
                    seen_ids.add(appearance_id)
                    name = str(
                        raw_appearance.get("name", "")
                        or raw_appearance.get("label", "")
                    ).strip() or (
                        "默认" if index == 0 else "外观 {}".format(index + 1)
                    )
                    parameters = raw_appearance.get("parameters", {})
                    if not isinstance(parameters, dict):
                        parameters = {}
                    appearances.append(
                        {
                            **copy.deepcopy(raw_appearance),
                            "id": appearance_id,
                            "name": name,
                            "folder_name": name,
                            "parameters": copy.deepcopy(parameters),
                            "portrait_assets": {},
                            "local_viewport": copy.deepcopy(
                                raw_appearance.get("local_viewport", {})
                            ),
                            "_live2d_appearance": True,
                        }
                    )
            if appearances:
                return appearances
            return [
                {
                    "id": "default",
                    "name": "默认",
                    "folder_name": "默认",
                    "parameters": {},
                    "portrait_assets": {},
                    "local_viewport": {},
                    "_live2d_appearance": True,
                }
            ]
        raw_outfits = config.get("portrait_outfits")
        outfits = []
        seen_ids = set()
        if isinstance(raw_outfits, list):
            for index, raw_outfit in enumerate(raw_outfits):
                if not isinstance(raw_outfit, dict):
                    continue
                outfit_id = re.sub(
                    r"[^a-z0-9_]+",
                    "_",
                    str(raw_outfit.get("id", "")).strip().lower(),
                    ).strip("_")
                if not outfit_id or outfit_id in seen_ids:
                    continue
                seen_ids.add(outfit_id)
                outfit_name = str(
                    raw_outfit.get("name", "")
                    or raw_outfit.get("folder_name", "")
                ).strip() or (
                    "默认" if index == 0 else "服装 {}".format(index + 1)
                )
                # 服装导航名称就是磁盘目录名。旧配置中的 folder_name
                # 仅作为缺少 name 时的读取后备，保存时会迁移到新目录。
                folder_name = outfit_name
                raw_assets = raw_outfit.get("portrait_assets", {})
                assets = (
                    {
                        str(state): DesktopPetApp._single_portrait_asset_map(
                            state_assets
                        )
                        for state, state_assets in raw_assets.items()
                    }
                    if isinstance(raw_assets, dict)
                    else {}
                )
                outfits.append(
                    {
                        **copy.deepcopy(raw_outfit),
                        "id": outfit_id,
                        "name": outfit_name,
                        "folder_name": folder_name,
                        "portrait_assets": (
                            copy.deepcopy(assets)
                            if isinstance(assets, dict)
                            else {}
                        ),
                        "local_viewport": (
                            copy.deepcopy(raw_outfit.get("local_viewport", {}))
                            if isinstance(raw_outfit.get("local_viewport"), dict)
                            else {}
                        ),
                        "actions": (
                            actions := DesktopPetApp._normalize_portrait_outfit_actions(
                                raw_outfit,
                            )
                        ),
                        "active_action_id": (
                            action_id
                            if (
                                action_id := DesktopPetApp._normalize_portrait_action_id(
                                    raw_outfit.get("active_action_id", "")
                                )
                            )
                            in {action["id"] for action in actions}
                            else (actions[0]["id"] if actions and not any(assets.values()) else "")
                        ),
                    }
                )
        if any(outfit["id"] == "default" for outfit in outfits):
            return outfits

        rules = config.get("portrait_rules", {})
        rules = rules if isinstance(rules, dict) else {}
        legacy_assets = {}
        states = config.get("states", {})
        if isinstance(states, dict):
            for state, definition in states.items():
                if not isinstance(definition, dict):
                    continue
                assets = DesktopPetApp._single_portrait_asset_map(
                    definition.get("portrait_assets", {})
                )
                if assets:
                    legacy_assets[str(state)] = assets
        viewport = rules.get("local_viewport", {})
        outfits.insert(
            0,
            {
                "id": "default",
                "name": "默认",
                "folder_name": "默认",
                "portrait_assets": legacy_assets,
                "actions": [],
                "active_action_id": "",
                "local_viewport": (
                    copy.deepcopy(viewport) if isinstance(viewport, dict) else {}
                ),
            },
        )
        return outfits

    @classmethod
    def _live2d_runtime_outfit_groups(cls, character_config):
        """Return clothing groups for the runtime switcher, not pose entries."""
        groups = {}
        for appearance in cls._portrait_outfits(character_config):
            outfit_id = str(appearance.get("outfit_id") or "default").strip()
            if not outfit_id:
                outfit_id = "default"
            group = groups.setdefault(
                outfit_id,
                {
                    "id": outfit_id,
                    "name": str(
                        appearance.get("outfit_name") or "默认服装"
                    ).strip() or "默认服装",
                    "appearances": [],
                    "_live2d_outfit_group": True,
                },
            )
            group["appearances"].append(appearance)
        return list(groups.values())

    @classmethod
    def _active_runtime_portrait_outfit_id(cls, character_config):
        if not cls._is_live2d_character_config(character_config):
            return cls._active_portrait_outfit_id(character_config)
        active_appearance_id = cls._active_portrait_outfit_id(character_config)
        appearances = cls._portrait_outfits(character_config)
        current = next(
            (item for item in appearances if item["id"] == active_appearance_id),
            None,
        )
        active_group = str(current.get("outfit_id") or "default") if current else "default"
        groups = cls._live2d_runtime_outfit_groups(character_config)
        return active_group if any(group["id"] == active_group for group in groups) else (
            groups[0]["id"] if groups else "default"
        )

    @staticmethod
    def _is_live2d_character_config(character_config):
        config = character_config if isinstance(character_config, dict) else {}
        renderer = config.get("renderer", {})
        return (
            isinstance(renderer, dict)
            and renderer.get("current") == "live2d"
        )

    @staticmethod
    def _live2d_appearance_id(name, existing_ids=()):
        base = re.sub(
            r"[^a-z0-9_]+",
            "_",
            str(name or "").strip().lower(),
        ).strip("_") or "appearance"
        existing = {str(value).strip() for value in existing_ids}
        candidate = base
        index = 2
        while candidate in existing:
            candidate = "{}_{}".format(base, index)
            index += 1
        return candidate

    @staticmethod
    def _live2d_variable_value(value, default=""):
        if isinstance(value, tk.Text):
            try:
                return value.get("1.0", "end").strip()
            except tk.TclError:
                return default
        if hasattr(value, "get") and callable(value.get):
            try:
                return value.get()
            except (AttributeError, tk.TclError):
                return default
        return default if value is None else value

    @classmethod
    def _parse_live2d_parameters(cls, value):
        """解析外观编辑器中的 ParamId=数值，也接受 JSON 对象。"""
        text = (
            json.dumps(value, ensure_ascii=False)
            if isinstance(value, dict)
            else str(cls._live2d_variable_value(value, "") or "").strip()
        )
        if not text:
            return {}
        if text.startswith("{"):
            try:
                raw = json.loads(text)
            except (TypeError, ValueError) as error:
                raise ValueError("参数 JSON 无法解析：{}".format(error))
            if not isinstance(raw, dict):
                raise ValueError("参数 JSON 必须是对象。")
            entries = raw.items()
        else:
            entries = []
            for line_number, line in enumerate(text.splitlines(), start=1):
                line = line.strip()
                if not line or line.startswith("#"):
                    continue
                separator = "=" if "=" in line else ":"
                if separator not in line:
                    raise ValueError(
                        "第 {} 行参数应使用 ParamId=数值 格式。".format(
                            line_number
                        )
                    )
                parameter_id, raw_value = line.split(separator, 1)
                entries.append((parameter_id.strip(), raw_value.strip()))
        parameters = {}
        for parameter_id, raw_value in entries:
            parameter_id = str(parameter_id).strip()
            if not parameter_id:
                raise ValueError("模型参数名称不能为空。")
            try:
                parameters[parameter_id] = float(raw_value)
            except (TypeError, ValueError):
                raise ValueError(
                    "模型参数“{}”的值不是数字。".format(parameter_id)
                )
        return parameters

    @staticmethod
    def _live2d_parameters_text(parameters):
        if not isinstance(parameters, dict):
            return ""
        return "\n".join(
            "{}={}".format(parameter_id, value)
            for parameter_id, value in parameters.items()
        )

    def _collect_live2d_appearances(self, context):
        """将编辑器草稿转换为 renderer.appearance_options 配置。"""
        drafts = context.get("live2d_appearance_drafts", [])
        if not drafts:
            drafts = [
                {
                    "appearance": copy.deepcopy(item)
                }
                for item in context.get("portrait_outfits", [])
            ]
        appearances = []
        seen_ids = set()
        seen_names = {}
        for index, draft in enumerate(drafts):
            appearance = draft.get("appearance", {}) if isinstance(draft, dict) else {}
            appearance = appearance if isinstance(appearance, dict) else {}
            appearance_id = re.sub(
                r"[^a-z0-9_]+",
                "_",
                str(appearance.get("id", "")).strip().lower(),
            ).strip("_")
            if not appearance_id or appearance_id in seen_ids:
                raise ValueError("Live2D 外观 ID 重复或为空。")
            name = str(
                self._live2d_variable_value(
                    draft.get("name_var"),
                    appearance.get("name", ""),
                )
                or ""
            ).strip()
            if not name:
                raise ValueError("Live2D 外观名称不能为空。")
            name_key = (str(appearance.get("outfit_id") or "default"), name.casefold())
            if name_key in seen_names:
                raise ValueError(
                    "Live2D 外观名称重复：“{}”与“{}”。".format(
                        seen_names[name_key],
                        name,
                    )
                )
            seen_names[name_key] = name
            parameters = self._parse_live2d_parameters(
                draft.get("parameters_text", appearance.get("parameters", {}))
            )
            expression = str(
                self._live2d_variable_value(
                    draft.get("expression_var"),
                    appearance.get("expression", ""),
                )
                or ""
            ).strip()
            motion_group = str(
                self._live2d_variable_value(
                    draft.get("motion_group_var"),
                    (appearance.get("motion") or ["", ""])[0]
                    if isinstance(appearance.get("motion"), (list, tuple))
                    else "",
                )
                or ""
            ).strip()
            motion_index_text = str(
                self._live2d_variable_value(
                    draft.get("motion_index_var"),
                    (appearance.get("motion") or ["", ""])[1]
                    if isinstance(appearance.get("motion"), (list, tuple))
                    and len(appearance.get("motion")) > 1
                    else "",
                )
                or ""
            ).strip()
            result = {
                "id": appearance_id,
                "name": name,
                "parameters": parameters,
            }
            if appearance.get("outfit_id"):
                result["outfit_id"] = str(appearance["outfit_id"])
                result["outfit_name"] = str(appearance.get("outfit_name") or "默认服装")
            if isinstance(appearance.get("local_viewport"), dict):
                result["local_viewport"] = copy.deepcopy(appearance["local_viewport"])
            if expression:
                result["expression"] = expression
            if motion_group or motion_index_text:
                if not motion_group:
                    raise ValueError("设置动作序号时必须填写动作组。")
                try:
                    motion_index = int(motion_index_text)
                except (TypeError, ValueError):
                    raise ValueError("动作序号必须是整数。")
                if motion_index < 0:
                    raise ValueError("动作序号不能小于 0。")
                result["motion"] = [motion_group, motion_index]
            appearances.append(result)
            seen_ids.add(appearance_id)
        if not appearances:
            raise ValueError("至少需要保留一个 Live2D 外观预设。")
        return appearances

    @staticmethod
    def _validate_portrait_outfit_folder_name(name):
        folder_name = str(name or "").strip()
        if not folder_name:
            raise ValueError("服装名称不能为空。")
        if folder_name in {".", ".."}:
            raise ValueError("服装名称不能使用“.”或“..”。")
        if re.search(r'[<>:"/\\|?*\x00-\x1f]', folder_name):
            raise ValueError("服装名称包含 Windows 文件夹不支持的字符。")
        if folder_name.endswith((" ", ".")):
            raise ValueError("服装名称不能以空格或句点结尾。")
        if folder_name.split(".", 1)[0].upper() in {
            "CON",
            "PRN",
            "AUX",
            "NUL",
            *("COM{}".format(index) for index in range(1, 10)),
            *("LPT{}".format(index) for index in range(1, 10)),
        }:
            raise ValueError("服装名称不能使用 Windows 保留名称。")
        return folder_name

    @classmethod
    def _active_portrait_outfit_id(cls, character_config):
        config = character_config if isinstance(character_config, dict) else {}
        outfits = cls._portrait_outfits(config)
        rules = config.get("portrait_rules", {})
        renderer = config.get("renderer", {})
        selected_key = (
            "active_appearance_id"
            if isinstance(renderer, dict) and renderer.get("current") == "live2d"
            else "active_outfit_id"
        )
        selected = str(rules.get(selected_key, "")).strip() if isinstance(rules, dict) else ""
        if any(outfit["id"] == selected for outfit in outfits):
            return selected
        return outfits[0]["id"]

    @classmethod
    def _active_portrait_outfit(cls, character_config, outfit_id=None):
        outfits = cls._portrait_outfits(character_config)
        selected = str(
            outfit_id or cls._active_portrait_outfit_id(character_config)
        )
        return next(
            (outfit for outfit in outfits if outfit["id"] == selected),
            outfits[0],
        )

    @classmethod
    def _active_portrait_action_id(
        cls,
        character_config,
        outfit_id=None,
        outfit=None,
    ):
        outfit = (
            outfit
            if isinstance(outfit, dict)
            else cls._active_portrait_outfit(character_config, outfit_id)
        )
        selected = cls._normalize_portrait_action_id(
            outfit.get("active_action_id", "")
        )
        if any(
            action.get("id") == selected
            for action in outfit.get("actions", [])
        ):
            return selected
        return ""

    @classmethod
    def _portrait_action(
        cls,
        outfit,
        action_id=None,
    ):
        outfit = outfit if isinstance(outfit, dict) else {}
        selected = cls._normalize_portrait_action_id(action_id)
        default_action = {
            "id": "",
            "name": str(outfit.get("default_action_name", "")).strip() or "默认动作",
            "folder_name": "",
            "portrait_assets": copy.deepcopy(
                outfit.get("portrait_assets", {})
                if isinstance(outfit.get("portrait_assets"), dict)
                else {}
            ),
            "_default_action": True,
        }
        if not selected:
            return default_action
        action = next(
            (
                item
                for item in outfit.get("actions", [])
                if isinstance(item, dict) and item.get("id") == selected
            ),
            None,
        )
        return action if action is not None else default_action

    @classmethod
    def _portrait_action_choices(cls, outfit, default_rows=None):
        """Only offer a default action when it has assets (or is the sole draft)."""
        actions = list(outfit.get("actions", []))
        has_default = any(outfit.get("portrait_assets", {}).values())
        if default_rows is not None:
            has_default = has_default or any(
                any(row.get("assets", {}).values()) or any(row.get("pending", {}).values())
                for row in default_rows
            )
        return ([cls._portrait_action(outfit, "")] if has_default or not actions else []) + actions

    def _configured_state_definitions(
        self,
        character_config=None,
        outfit_id=None,
        outfits=None,
        action_id=None,
    ):
        config = (
            getattr(self, "character_config", {})
            if character_config is None
            else character_config
        )
        raw_states = config.get("states", {}) if isinstance(config, dict) else {}
        if self._is_live2d_character_config(config):
            definitions = {}
            for key, value in raw_states.items():
                if key in LEGACY_EMOTIONS or key.startswith(("expression_", "expression:")):
                    continue
                if not isinstance(value, dict) or not value.get("enabled", True):
                    continue
                definitions[key] = copy.deepcopy(value)
                if key in PRESET_EMOTIONS:
                    definitions[key].update(
                        label=PRESET_EMOTIONS[key]["label"],
                        keywords=list(PRESET_EMOTIONS[key]["keywords"]), category="preset")
            definitions.setdefault("idle", {"label": "待机", "enabled": True,
                                            "keywords": [], "category": "special"})
            return definitions
        removed_states = self._portrait_removed_state_keys(config)
        available_outfits = (
            outfits if isinstance(outfits, list) and outfits else
            self._portrait_outfits(config)
        )
        selected_id = str(
            outfit_id or self._active_portrait_outfit_id(config)
        )
        outfit = next(
            (
                item
                for item in available_outfits
                if item.get("id") == selected_id
            ),
            available_outfits[0],
        )
        default_assets = (
            outfit.get("portrait_assets", {})
            if isinstance(outfit.get("portrait_assets"), dict)
            else {}
        )
        selected_action_id = (
            self._normalize_portrait_action_id(action_id)
            if action_id is not None
            else self._active_portrait_action_id(
                config,
                outfit_id=outfit.get("id"),
                outfit=outfit,
            )
        )
        selected_action = self._portrait_action(
            outfit,
            selected_action_id,
        )
        action_assets = (
            selected_action.get("portrait_assets", {})
            if isinstance(selected_action, dict)
            and isinstance(selected_action.get("portrait_assets"), dict)
            else {}
        )
        if selected_action_id:
            removed_states = removed_states.difference(
                key for key, assets in action_assets.items()
                if self._single_portrait_asset_map(assets).get("full")
            )
        renderer = config.get("renderer", {})
        is_live2d = (
            isinstance(renderer, dict)
            and renderer.get("current") == "live2d"
        )
        isolated_outfit = outfit["id"] != "default" and not is_live2d

        def portrait_assets_for_state(key, legacy_assets=None):
            candidates = []
            if selected_action_id:
                candidates.extend(
                    (
                        action_assets.get(key, {}),
                        action_assets.get("idle", {}),
                    )
                )
            candidates.extend(
                (
                    default_assets.get(key, {}),
                    default_assets.get("idle", {}) if selected_action_id else {},
                )
            )
            if key == "idle":
                candidates.extend(
                    action.get("portrait_assets", {}).get("idle", {})
                    for action in outfit.get("actions", [])
                )
            if isinstance(legacy_assets, dict):
                if not isolated_outfit:
                    candidates.append(legacy_assets)
            for assets in candidates:
                normalized = self._single_portrait_asset_map(assets)
                if normalized.get("full"):
                    return normalized
            return {}

        definitions = {}
        if isinstance(raw_states, dict):
            for raw_key, raw_value in raw_states.items():
                key = self._normalize_portrait_state_key(raw_key)
                if not key or key in removed_states:
                    continue
                if isinstance(raw_value, dict):
                    label = str(raw_value.get("label", "")).strip() or key
                    keywords = self._split_state_keywords(
                        raw_value.get("keywords", STATE_KEYWORDS.get(key, ()))
                    )
                    legacy_assets = self._single_portrait_asset_map(
                        raw_value.get("portrait_assets", {})
                    )
                else:
                    label = str(raw_value or "").strip() or STATE_LABELS.get(key, key)
                    keywords = list(STATE_KEYWORDS.get(key, ()))
                    legacy_assets = {}
                portrait_assets = portrait_assets_for_state(
                    key,
                    legacy_assets=legacy_assets,
                )
                if isolated_outfit and not portrait_assets.get("full"):
                    continue
                preset_key = self._preset_emotion_key(key, label)
                if preset_key:
                    preset = PRESET_EMOTIONS[preset_key]
                    label = preset["label"]
                    keywords = list(preset["keywords"])
                definitions[key] = {
                    "label": label,
                    "keywords": keywords,
                    "usage_scenario": (str(raw_value.get("usage_scenario", "")).strip()
                                       if isinstance(raw_value, dict) else ""),
                    "enabled": True,
                    "portrait_assets": portrait_assets,
                    "category": (
                        "special"
                        if key == "idle"
                        else ("preset" if preset_key or (
                            isinstance(raw_value, dict)
                            and raw_value.get("category") == "preset"
                        ) else "custom")
                    ),
                }
        for key in {
            *action_assets.keys(),
            *default_assets.keys(),
        }:
            normalized_key = self._normalize_portrait_state_key(key)
            if (
                not normalized_key
                or normalized_key in removed_states
                or normalized_key in definitions
                or normalized_key in PRESET_EMOTIONS
                or normalized_key == "idle"
            ):
                continue
            portrait_assets = portrait_assets_for_state(normalized_key)
            if isolated_outfit and not portrait_assets.get("full"):
                continue
            definitions[normalized_key] = {
                "label": STATE_LABELS.get(normalized_key, normalized_key),
                "keywords": list(STATE_KEYWORDS.get(normalized_key, ())),
                "enabled": True,
                "portrait_assets": portrait_assets,
                "category": "custom",
            }
        existing_preset_labels = {
            self._portrait_emotion_name_key(definition["label"])
            for definition in definitions.values()
            if definition.get("category") == "preset"
        }
        for key, preset in PRESET_EMOTIONS.items():
            label_key = self._portrait_emotion_name_key(preset["label"])
            if (
                key in removed_states
                or key in definitions
                or label_key in existing_preset_labels
            ):
                continue
            portrait_assets = portrait_assets_for_state(key)
            if isolated_outfit and not portrait_assets.get("full"):
                continue
            definitions[key] = {
                "label": preset["label"],
                "keywords": list(preset["keywords"]),
                "enabled": True,
                "portrait_assets": portrait_assets,
                "category": "preset",
            }
        if "idle" not in definitions:
            definitions["idle"] = {
                "label": STATE_LABELS["idle"],
                "keywords": [],
                "enabled": True,
                "portrait_assets": portrait_assets_for_state("idle"),
                "category": "special",
            }
        return definitions

    def _portrait_removed_state_keys(self, character_config):
        rules = (
            character_config.get("portrait_rules", {})
            if isinstance(character_config, dict)
            else {}
        )
        if not isinstance(rules, dict):
            return set()
        removed = rules.get("removed_states", ())
        if isinstance(removed, str):
            removed = (removed,)
        if not isinstance(removed, (list, tuple, set)):
            return set()
        return {
            normalized
            for normalized in (
                self._normalize_portrait_state_key(state)
                for state in removed
            )
            if normalized
        }

    @staticmethod
    def _restore_portrait_state(context, state):
        normalized = DesktopPetApp._normalize_portrait_state_key(state)
        if normalized:
            if context.get("active_action_id"):
                context.setdefault("portrait_action_removed_states", {}).setdefault(
                    (context["active_outfit_id"], context["active_action_id"]), set()
                ).discard(normalized)
            else:
                context.setdefault("removed_portrait_states", set()).discard(
                    normalized
                )

    @classmethod
    def _preset_emotion_key(cls, state, label=""):
        if state in PRESET_EMOTIONS:
            return state
        aliases = {
            "开心": "happy",
            "快乐": "happy",
            "愉快": "happy",
            "忧虑": "worried",
            "担心": "worried",
            "担忧": "worried",
            "困惑": "confused",
            "疑问": "confused",
            "思考": "thinking",
            "发光": "sparkling_eyes",
        }
        normalized_label = cls._portrait_emotion_name_key(label)
        for key, preset in PRESET_EMOTIONS.items():
            if normalized_label == cls._portrait_emotion_name_key(preset["label"]):
                return key
        return aliases.get(normalized_label)

    @staticmethod
    def _character_render_config(config):
        return copy.deepcopy({key: config.get(key) for key in (
            "renderer", "states", "portrait_rules", "portrait_outfits")})

    def _new_portrait_renderer(
        self,
        character_dir=None,
        character_config=None,
        outfit_id=None,
        force_static=False,
        background=False,
    ):
        character_dir = Path(character_dir or self.character_dir)
        config = (
            getattr(self, "character_config", {})
            if character_config is None
            else character_config
        )
        selected_outfit_id = outfit_id or self._active_portrait_outfit_id(config)
        outfit = self._active_portrait_outfit(config, selected_outfit_id)
        rules = config.get("portrait_rules", {}) if isinstance(config, dict) else {}
        renderer_config = config.get("renderer", {}) if isinstance(config, dict) else {}
        if (
            not force_static
            and
            isinstance(renderer_config, dict)
            and renderer_config.get("current") == "live2d"
            and renderer_config.get("model")
        ):
            try:
                appearance = self._active_portrait_outfit(
                    config,
                    selected_outfit_id,
                )
                renderer_class = BackgroundLive2DRenderer if background else Live2DRenderer
                renderer = renderer_class(
                    character_dir,
                    renderer_config["model"],
                    state_definitions=self._configured_state_definitions(
                        config,
                        outfit_id=selected_outfit_id,
                    ),
                    appearance=appearance,
                    viewport_settings=(
                        outfit.get("local_viewport")
                        or rules.get("local_viewport", {})
                    ),
                )
                self._apply_live2d_preferences(renderer, character_dir.name)
                renderer._character_render_config = self._character_render_config(config)
                return renderer
            except (OSError, ValueError, TypeError) as error:
                _portrait_log(
                    "live2d_renderer_config_failed character={} error={}".format(
                        character_dir,
                        error,
                    )
                )
        return StaticPortraitRenderer(
            character_dir,
            state_definitions=self._configured_state_definitions(
                config,
                outfit_id=selected_outfit_id,
            ),
            viewport_settings=(
                outfit.get("local_viewport")
                or (
                    rules.get("local_viewport", {})
                    if isinstance(rules, dict)
                    else {}
                )
            ),
            outfit_id=selected_outfit_id,
            outfit_folder_name=outfit.get("folder_name") or outfit.get("name"),
            root_assets=(
                isinstance(renderer_config, dict) and renderer_config.get("current") == "live2d"
            ),
        )

    def _replace_portrait_renderer(self, character_dir=None):
        self._cancel_live2d_tick()
        replacement = self._new_portrait_renderer(character_dir)
        current = getattr(self, "renderer", None)
        close = getattr(current, "close", None)
        if callable(close):
            close()
        else:
            hide = getattr(current, "hide", None)
            if callable(hide):
                hide()
        self.renderer = replacement
        self._sync_pet_topmost(force=True)
        self._refresh_live2d_settings_section()
        return replacement

    @staticmethod
    def _portrait_mode_asset_path(
        state,
        mode,
        character_dir,
        definition=None,
        outfit_id="default",
    ):
        definition = definition if isinstance(definition, dict) else {}
        portrait_assets = definition.get("portrait_assets", {})
        if isinstance(portrait_assets, dict):
            relative_path = portrait_assets.get("full")
            if relative_path:
                portraits = Path(character_dir) / "portraits"
                try:
                    candidate = (portraits / str(relative_path)).resolve()
                    candidate.relative_to(portraits.resolve())
                except (OSError, ValueError):
                    candidate = None
                if candidate is not None and candidate.is_file():
                    return candidate
        if outfit_id != "default":
            return None
        portraits = Path(character_dir) / "portraits"
        directories = (portraits / "outfits" / "默认",)
        state_label = str(definition.get("label", "")).strip()
        for directory in directories:
            aliases = tuple(label for label, key in EMOTION_LABEL_ALIASES.items()
                            if key == state)
            for stem in (state_label, state, *aliases):
                for extension in IMAGE_EXTENSIONS:
                    candidate = directory / (stem + extension)
                    if candidate.is_file():
                        return candidate
        return None

    def _portrait_state_asset_exists(self, state, character_dir=None, mode=None):
        character_dir = character_dir or self.character_dir
        mode = mode or getattr(self, "display_mode", "full")
        definition = self._configured_state_definitions().get(state, {})
        if self._portrait_mode_asset_path(
            state,
            mode,
            character_dir,
            definition=definition,
        ):
            return True
        portraits = Path(character_dir) / "portraits"
        definition = self._configured_state_definitions().get(state, {})
        for directory in (portraits / "outfits" / "默认",):
            for stem in (str(definition.get("label", "")).strip(), state):
                if not stem:
                    continue
                for extension in IMAGE_EXTENSIONS:
                    if (directory / (stem + extension)).is_file():
                        return True
        return False

    def _portrait_state_has_any_asset(self, state, character_dir=None):
        """情绪只要在任一显示模式有资源，就可以参与情绪选择。"""
        character_dir = character_dir or self.character_dir
        return any(
            self._portrait_state_asset_exists(
                state,
                character_dir=character_dir,
                mode=mode,
            )
            for mode in ("full", "small")
        )

    def _available_state_labels(self):
        definitions = self._configured_state_definitions()
        available = {
            state: definition["label"]
            for state, definition in definitions.items()
            if definition["enabled"]
        }
        if not available:
            available["idle"] = STATE_LABELS["idle"]
        return available

    def _available_state_keywords(self):
        definitions = self._configured_state_definitions()
        keywords = {}
        for state, definition in definitions.items():
            if state not in self._available_state_labels():
                continue
            keywords[state] = definition["keywords"]
        return keywords

    def _state_from_reply(self, reply, fallback_text=""):
        available = {
            key: definition["label"] for key, definition in PRESET_EMOTIONS.items()
        }
        available.update(self._available_state_labels())
        keywords = self._available_state_keywords()
        config = getattr(self, "character_config", {})
        if (self._portrait_auto_actions_enabled(config)
                and not self._is_live2d_character_config(config)):
            outfit = self._active_portrait_outfit(config)
            for action in outfit.get("actions", []):
                for key, definition in self._configured_state_definitions(
                        action_id=action["id"]).items():
                    if definition["enabled"]:
                        available[key] = definition["label"]
                        keywords[key] = definition["keywords"]
        model_state = state_from_model_result(reply, available)
        if model_state:
            return model_state
        return select_state(
            fallback_text or reply,
            available,
            state_keywords=keywords,
        )

    def _apply_reply_behavior(self, reply, fallback_text=""):
        state = self._state_from_reply(reply, fallback_text)
        self.last_reply_emotion = state
        if isinstance(getattr(self, "renderer", None), Live2DRenderer):
            self.set_state(state, behavior_intent=intent_from_reply(reply))
        else:
            if self._portrait_auto_actions_enabled(getattr(self, "character_config", {})):
                action_id = self._choose_reply_portrait_action(state)
                self._switch_runtime_portrait_action(action_id, persist=False, render=False)
            self.set_state(self._reply_portrait_display_state(state))

    def _normalize_character_theme(self, value=None):
        value = value if isinstance(value, dict) else {}
        fallback_input = self.theme.get("surface", "#493043")
        input_background = self._normalize_hex_color(
            value.get("input_background"),
            fallback_input,
        )
        outfit_bubble_color = self._normalize_hex_color(
            value.get("outfit_bubble_color"),
            "#22B8E8",
        )
        reply_background = self._normalize_hex_color(
            value.get("reply_background"),
            "#090b10",
        )
        if "reply_opaque" in value:
            reply_opaque = bool(value.get("reply_opaque"))
            try:
                reply_transparency = int(round(float(value.get("reply_transparency", 0))))
            except (TypeError, ValueError):
                reply_transparency = 0
        else:
            try:
                legacy_opacity = int(round(float(value.get("reply_opacity", 100))))
            except (TypeError, ValueError):
                legacy_opacity = 100
            legacy_opacity = max(0, min(100, legacy_opacity))
            reply_opaque = legacy_opacity >= 100
            reply_transparency = 0 if reply_opaque else 100 - legacy_opacity
        return {
            "input_background": input_background,
            "outfit_bubble_color": outfit_bubble_color,
            "reply_background": reply_background,
            "reply_opaque": reply_opaque,
            "reply_transparency": max(0, min(100, reply_transparency)),
        }

    @staticmethod
    def _normalize_hex_color(value, fallback):
        text = str(value or "").strip().upper()
        if re.fullmatch(r"#[0-9A-F]{6}", text):
            return text
        fallback_text = str(fallback or "").strip().upper()
        return fallback_text if re.fullmatch(r"#[0-9A-F]{6}", fallback_text) else "#000000"

    @classmethod
    def _blend_hex(cls, foreground, background, opacity):
        foreground = cls._normalize_hex_color(foreground, "#000000")
        background = cls._normalize_hex_color(background, "#000000")
        ratio = max(0.0, min(1.0, float(opacity) / 100.0))
        front = tuple(int(foreground[index:index + 2], 16) for index in (1, 3, 5))
        back = tuple(int(background[index:index + 2], 16) for index in (1, 3, 5))
        mixed = tuple(
            int(round(back[index] + (front[index] - back[index]) * ratio))
            for index in range(3)
        )
        return "#{:02X}{:02X}{:02X}".format(*mixed)

    def _character_chat_theme(self):
        source = self.character_config.get("theme", {})
        preview = getattr(self, "_character_theme_preview", None)
        sample_active = bool(
            getattr(self, "_character_theme_sample_state", None)
            and self._character_theme_sample_state.get("active")
        )
        if preview and (
            preview.get("character_id") == self.character_id or sample_active
        ):
            source = preview.get("theme", source)
        normalized = self._normalize_character_theme(source)
        input_background = normalized["input_background"]
        if normalized["reply_opaque"]:
            reply_alpha = 1.0
        else:
            reply_alpha = max(
                0.0,
                1.0 - (normalized["reply_transparency"] / 100.0),
            )
        return {
            "input_background": input_background,
            "reply_background": normalized["reply_background"],
            "reply_opaque": normalized["reply_opaque"],
            "reply_transparency": normalized["reply_transparency"],
            "reply_opacity": int(round(reply_alpha * 100)),
            "reply_alpha": reply_alpha,
        }

    def _apply_character_chat_theme(self):
        if not hasattr(self, "inline_input_frame"):
            return
        colors = self._character_chat_theme()
        input_background = colors["input_background"]
        reply_background = colors["reply_background"]
        reply_alpha = colors["reply_alpha"]
        style = ttk.Style(self.root)
        try:
            style.configure(
                "CharacterReply.Vertical.TScrollbar",
                background=BRAND_COLORS["panel_soft"],
                troughcolor=BRAND_COLORS["bg_soft"],
                bordercolor=BRAND_COLORS["line"],
                lightcolor=BRAND_COLORS["panel_soft"],
                darkcolor=BRAND_COLORS["line"],
                arrowcolor=BRAND_COLORS["white"],
                borderwidth=0,
            )
        except tk.TclError:
            pass
        self.inline_reply_background_frame.configure(bg=reply_background)
        self.inline_reply_frame.configure(bg=reply_background)
        self.inline_reply_header.configure(bg=reply_background)
        self.inline_reply_name.configure(
            bg=reply_background,
            fg=INLINE_REPLY_HEADER_COLOR,
            font=INLINE_REPLY_FONT,
        )
        self.inline_reply_tts_error.configure(
            bg=reply_background,
            fg=INLINE_REPLY_HEADER_COLOR,
            font=INLINE_REPLY_FONT,
        )
        self.inline_reply_pause_button.configure(bg=reply_background)
        self.inline_reply_close_button.configure(
            bg=reply_background,
            fg=INLINE_REPLY_HEADER_COLOR,
            font=INLINE_REPLY_FONT,
        )
        self._draw_inline_reply_close_button(
            hovered=bool(
                getattr(self.inline_reply_close_button, "_close_hovered", False)
            )
        )
        self.inline_reply_body.configure(bg=reply_background)
        self.inline_reply_text.configure(
            bg=reply_background,
            fg="#FFFFFF",
            insertbackground="#FFFFFF",
            font=INLINE_CHAT_FONT,
        )
        self.inline_reply_scrollbar.configure(
            bg=BRAND_COLORS["bg_soft"],
            thumb_color=BRAND_COLORS["panel_soft"],
            troughcolor=BRAND_COLORS["bg_soft"],
            arrowcolor=BRAND_COLORS["white"],
        )
        self.inline_input_frame.configure(bg=input_background)
        self.inline_input_notice.configure(
            bg=input_background if self.inline_input_notice.cget("text").strip() else self.transparent_color,
            fg="#FFFFFF",
            font=("Microsoft YaHei UI", 9),
        )
        self.inline_input_entry.configure(
            bg=input_background,
            fg=self.theme["text"],
            insertbackground=self.theme["text"],
            selectbackground=self.theme["accent"],
            selectforeground=self.theme["accent_text"],
            font=INLINE_CHAT_FONT,
        )
        self._sync_inline_input_placeholder()
        if hasattr(self, "inline_input_preedit"):
            self.inline_input_preedit.configure(
                bg=input_background,
                fg=self.theme["text"],
                font=INLINE_CHAT_FONT,
            )
        self.inline_cancel_button.configure(
            bg=input_background,
            fg="#FFFFFF",
            activebackground=self.theme["accent"],
            activeforeground="#FFFFFF",
        )
        self._style_language_button(
            self.inline_language_button,
            hovered=bool(getattr(self.inline_language_button, "_language_hovered", False)),
        )
        self._sync_inline_action_button()
        self._draw_tts_pause_button()
        self.inline_resize_grip.configure(bg=input_background)
        for line in self.inline_resize_grip._grip_lines:
            self.inline_resize_grip.itemconfigure(line, fill="#FFFFFF")
        self._set_inline_reply_surface(reply_alpha)
        self._sync_inline_reply_window()

    def _preview_character_theme(self, character_id, theme):
        sample_active = bool(
            getattr(self, "_character_theme_sample_state", None)
            and self._character_theme_sample_state.get("active")
        )
        if character_id != self.character_id and not sample_active:
            return
        self._character_theme_preview = {
            "character_id": character_id,
            "theme": self._normalize_character_theme(theme),
        }
        self._apply_character_chat_theme()

    def _preview_character_theme_alpha(self, character_id, theme):
        """透明度拖动只更新 alpha，避免重复布局和窗口提升。"""
        sample_active = bool(
            getattr(self, "_character_theme_sample_state", None)
            and self._character_theme_sample_state.get("active")
        )
        if character_id != self.character_id and not sample_active:
            return
        normalized = self._normalize_character_theme(theme)
        self._character_theme_preview = {
            "character_id": character_id,
            "theme": normalized,
        }
        if normalized["reply_opaque"]:
            alpha = 1.0
        else:
            alpha = max(
                0.0,
                1.0 - (normalized["reply_transparency"] / 100.0),
            )
        self._schedule_inline_reply_window_alpha(alpha)

    def _show_character_theme_sample(self, character_id, theme, display_name=""):
        if not hasattr(self, "inline_reply_text"):
            return
        existing = getattr(self, "_character_theme_sample_state", None)
        if existing and existing.get("active"):
            self._preview_character_theme(character_id, theme)
            return
        previous_content = ""
        previous_name = self.inline_reply_name.cget("text")
        try:
            previous_content = self.inline_reply_text.get("1.0", "end-1c")
        except tk.TclError:
            pass
        self._character_theme_sample_state = {
            "active": True,
            "character_id": character_id,
            "previous_visible": bool(self.inline_reply_visible),
            "previous_content": previous_content,
            "previous_name": previous_name,
            "live_content": previous_content,
            "live_name": previous_name,
        }
        self._character_theme_preview = {
            "character_id": character_id,
            "theme": self._normalize_character_theme(theme),
        }
        display_name = display_name or self.character_config.get(
            "display_name",
            character_id,
        )
        self.inline_reply_name.configure(text="{} · 示例".format(display_name))
        self._replace_inline_reply_text(
            "这是一条回复框示例。",
            clean=False,
        )
        self.inline_reply_visible = True
        self._repack_inline_panels()
        self.root.update_idletasks()
        self._fit_inline_reply_height()
        self._reset_inline_reply_scroll()
        self._resize_pet_window()
        self._apply_character_chat_theme()

    def _character_theme_sample_context_active(
        self,
        notebook,
        tab,
        character_id,
    ):
        if getattr(self, "_control_closing_dialog", None) is not None:
            return False
        if getattr(self, "_control_current_page", "") != "character_edit":
            return False
        context = getattr(self, "_control_edit_context", None)
        if not isinstance(context, dict):
            return False
        return (
            context.get("character_id") == character_id
            and context.get("theme_notebook") is notebook
            and context.get("theme_tab") is tab
            and context.get("editor_generation")
            == getattr(self, "_character_theme_editor_generation", 0)
        )

    def _sync_character_theme_sample_for_tab(
        self,
        notebook,
        tab,
        character_id,
        theme,
        display_name,
        sample_enabled=None,
    ):
        if not self._character_theme_sample_context_active(
            notebook,
            tab,
            character_id,
        ):
            self._clear_character_theme_preview(apply=True)
            return
        try:
            selected = notebook.select()
            selected_text = notebook.tab(selected, "text")
        except tk.TclError:
            self._clear_character_theme_preview(apply=True)
            return
        enabled = sample_enabled is not None and bool(sample_enabled.get())
        if selected_text == "基础资料" and enabled:
            self._show_character_theme_sample(
                character_id,
                theme,
                display_name=display_name,
            )
            return
        if selected_text != "基础资料" and sample_enabled is not None:
            sample_enabled.set(False)
        self._clear_character_theme_preview(apply=True)

    def _cancel_character_theme_sample_sync(self):
        after_id = getattr(self, "_theme_sample_sync_after_id", None)
        if after_id is not None:
            try:
                self.root.after_cancel(after_id)
            except tk.TclError:
                pass
        self._theme_sample_sync_after_id = None
        self._theme_sample_sync_generation = (
            getattr(self, "_theme_sample_sync_generation", 0) + 1
        )

    def _schedule_character_theme_sample_sync(
        self,
        notebook,
        tab,
        character_id,
        theme,
        display_name,
        sample_enabled=None,
    ):
        """在标签切换完成后同步示例框，避免鼠标事件早于 Notebook 状态更新。"""
        self._cancel_character_theme_sample_sync()
        if not self._character_theme_sample_context_active(
            notebook,
            tab,
            character_id,
        ):
            self._clear_character_theme_preview(apply=True)
            return
        try:
            selected = notebook.select()
            selected_text = notebook.tab(selected, "text")
        except tk.TclError:
            self._clear_character_theme_preview(apply=True)
            return
        if selected_text != "基础资料" or sample_enabled is None or not sample_enabled.get():
            if selected_text != "基础资料" and sample_enabled is not None:
                sample_enabled.set(False)
            # 离开“基础资料”时同步隐藏，不等待 after_idle。
            self._clear_character_theme_preview(apply=True)
            return
        generation = self._theme_sample_sync_generation

        def run():
            self._theme_sample_sync_after_id = None
            if generation != self._theme_sample_sync_generation:
                return
            self._sync_character_theme_sample_for_tab(
                notebook,
                tab,
                character_id,
                theme,
                display_name,
                sample_enabled,
            )

        try:
            self._theme_sample_sync_after_id = notebook.after_idle(run)
        except tk.TclError:
            self._theme_sample_sync_after_id = None
            self._clear_character_theme_preview(apply=True)

    def _hide_character_theme_sample(self, restore=True):
        state = getattr(self, "_character_theme_sample_state", None)
        if not state or not state.get("active"):
            return
        self._character_theme_sample_state = None
        if not restore:
            return
        live_content = str(state.get("live_content", ""))
        live_name = str(state.get("live_name", "")).strip()
        # 文本内容可能是上一次回复或上一次示例的残留，不能据此判断
        # 回复框原本是否可见；否则第二次打开示例后关闭会再次保留窗口。
        should_show = bool(state.get("previous_visible"))
        content = live_content or str(state.get("previous_content", ""))
        name = live_name or str(state.get("previous_name", "")).strip()
        if should_show:
            if name:
                self.inline_reply_name.configure(text=name)
            self._replace_inline_reply_text(content, clean=False)
            self._fit_inline_reply_height()
            self._reset_inline_reply_scroll()
        self.inline_reply_visible = should_show
        self._repack_inline_panels()
        self._resize_pet_window()

    def _clear_character_theme_preview(self, apply=True):
        self._cancel_character_theme_sample_sync()
        had_preview = getattr(self, "_character_theme_preview", None) is not None
        self._hide_character_theme_sample(restore=True)
        self._character_theme_preview = None
        if had_preview and apply:
            self._apply_character_chat_theme()

    def _refresh_character_labels(self):
        """角色切换后同步所有当前窗口中会显示角色名的位置。"""
        display_name = self._character_display_name()
        self.root.title("{} - {}".format(APP_NAME, display_name))
        if hasattr(self, "title_label"):
            self.title_label.configure(text="  {} · {}".format(display_name, APP_NAME))
        if hasattr(self, "inline_reply_name"):
            self.inline_reply_name.configure(text=display_name)
        if hasattr(self, "status_label") and self.status_label.winfo_exists():
            self.status_label.configure(text="当前角色：{}".format(display_name))

    def _apply_theme(self):
        if self.pet_only:
            self.root.configure(bg=self.transparent_color)
            self.root_frame.configure(bg=self.transparent_color)
            self.portrait_canvas.configure(bg=self.transparent_color)
            if hasattr(self, "inline_input_frame"):
                self.inline_input_frame.configure(bg=self.theme["surface"])
                self.inline_input_entry.configure(
                    bg=self.theme["surface"],
                    fg=self.theme["text"],
                    insertbackground=self.theme["text"],
                    selectbackground=self.theme["accent"],
                    selectforeground=self.theme["accent_text"],
                )
                if hasattr(self, "inline_input_preedit"):
                    self.inline_input_preedit.configure(
                        bg=self.theme["surface"],
                        fg=self.theme["text"],
                        font=INLINE_CHAT_FONT,
                    )
                for button in (
                    self.inline_language_button,
                    self.inline_cancel_button,
                ):
                    if getattr(button, "_language_button", False):
                        self._style_language_button(button, hovered=False)
                        continue
                    if isinstance(button, tk.Canvas):
                        continue
                    button.configure(
                        bg=self.theme["surface"],
                        fg=self.theme["text"],
                        activebackground=self.theme["accent"],
                        activeforeground=self.theme["accent_text"],
                    )
                self._style_language_button(
                    self.inline_language_button,
                    hovered=False,
                )
                self.inline_reply_text.configure(
                    bg="#090b10",
                    fg="#ffffff",
                    insertbackground="#ffffff",
                )
                self._sync_inline_action_button()
                self._draw_tts_pause_button()
                self.inline_resize_grip.configure(bg=self.theme["surface"])
                for line in self.inline_resize_grip._grip_lines:
                    self.inline_resize_grip.itemconfigure(line, fill=self.theme["muted"])
                self._apply_character_chat_theme()
            return
        colors = self.theme
        self.root.configure(bg=colors["window"])
        self.root_frame.configure(bg=colors["window"])
        self.title_bar.configure(bg=colors["surface"])
        self.title_label.configure(bg=colors["surface"], fg=colors["text"])
        for button in (
            self.full_mode_button,
            self.small_mode_button,
            self.minimize_button,
            self.maximize_button,
            self.pin_button,
            self.close_button,
            self.config_button,
            self.language_button,
            self.send_button,
        ):
            if getattr(button, "_language_button", False):
                self._style_language_button(button, hovered=False)
                continue
            if isinstance(button, tk.Canvas):
                if getattr(button, "_reply_close_button", False):
                    self._draw_inline_reply_close_button(
                        hovered=bool(getattr(button, "_close_hovered", False))
                    )
                    continue
                self._style_send_button(button, hovered=False)
                continue
            button.configure(
                bg=colors["surface"],
                fg=colors["text"],
                activebackground=colors["accent"],
                activeforeground=colors["accent_text"],
                relief="flat",
                bd=0,
            )
        self._style_send_button(self.send_button, hovered=False)
        for frame in (self.body, self.left, self.right, self.state_frame):
            frame.configure(bg=colors["window"])
        for widget in self.widgets:
            if isinstance(widget, tk.Frame):
                widget.configure(bg=colors["window"])
            elif isinstance(widget, tk.Label):
                widget.configure(bg=colors["window"], fg=colors["text"])
            elif isinstance(widget, tk.Checkbutton):
                widget.configure(
                    bg=colors["window"],
                    fg=colors["text"],
                    activebackground=colors["window"],
                    activeforeground=colors["text"],
                    selectcolor=colors["surface"],
                )
            elif isinstance(widget, ttk.Checkbutton):
                style_name = self._brand_switch_style(
                    colors["window"],
                    colors["text"],
                )
                if style_name:
                    widget.configure(style=style_name)
            elif isinstance(widget, tk.Button):
                widget.configure(
                    bg=colors["surface"],
                    fg=colors["text"],
                    activebackground=colors["accent"],
                    activeforeground=colors["accent_text"],
                )
        self.title_label.configure(bg=colors["surface"])
        self.state_label.configure(bg=colors["window"], fg=colors["muted"])
        self.state_value.configure(bg=colors["window"], fg=colors["accent"])
        self.status_label.configure(bg=colors["window"], fg=colors["muted"])
        self.theme_menu.configure(style="Brand.TCombobox")
        self.input_entry.configure(
            bg=colors["surface"], fg=colors["text"], insertbackground=colors["text"], relief="flat"
        )
        self.voice_volume_scale.configure(
            bg=colors["accent"],
            troughcolor=colors["surface"],
            activebackground=colors["text"],
            sliderrelief=tk.RAISED,
            sliderlength=30,
            width=16,
        )
        self.chat_text.configure(
            bg=colors["panel"], fg=colors["text"], insertbackground=colors["text"], relief="flat"
        )
        self.portrait_canvas.configure(bg=colors["window"])
        self._update_mode_buttons()

    def show_config(self):
        self._show_control_center("settings")
        return

    def show_control_page(self, page):
        self._show_control_center(page)
        return

    def _capture_control_snapshot(self):
        return {
            "settings": copy.deepcopy(self.store.settings),
            "app_config": copy.deepcopy(self.app_config),
            "character_id": self.character_id,
            "character_config": copy.deepcopy(self.character_config),
            "voice_config": copy.deepcopy(self.voice_config),
            "character_dir": self.character_dir,
            "display_mode": self.display_mode,
            "portrait_scale": self.portrait_scale,
            "theme_name": self.theme_name,
            "theme": self.theme,
            "topmost": bool(self.root.attributes("-topmost")),
        }

    def _control_center_initial_geometry(self):
        """Return the saved settings geometry or a screen-sized first-use size."""
        control_center = self.app_config.get("control_center")
        screen_width = max(960, int(self.root.winfo_screenwidth()))
        screen_height = max(680, int(self.root.winfo_screenheight()))
        if isinstance(control_center, dict):
            saved = str(control_center.get("geometry") or "").strip()
            match = re.fullmatch(
                r"(\d+)x(\d+)([+-]\d+)([+-]\d+)?",
                saved,
            )
            if match:
                width = min(screen_width, max(960, int(match.group(1))))
                height = min(screen_height, max(680, int(match.group(2))))
                x = max(0, min(int(match.group(3)), screen_width - width))
                y = max(
                    0,
                    min(
                        int(match.group(4) or 0),
                        screen_height - height,
                    ),
                )
                return "{}x{}+{}+{}".format(width, height, x, y)
        width = min(1120, max(960, int(screen_width * 0.66)))
        height = min(760, max(680, int(screen_height * 0.7)))
        x = max(0, (screen_width - width) // 2)
        y = max(0, (screen_height - height) // 2)
        return "{}x{}+{}+{}".format(width, height, x, y)

    def _store_control_center_geometry(self, dialog):
        """Keep the current user size in both live config and draft snapshot."""
        if dialog is None:
            return None
        try:
            geometry = str(dialog.winfo_geometry()).strip()
        except (AttributeError, tk.TclError):
            return None
        if not geometry:
            return None
        control_center = self.app_config.setdefault("control_center", {})
        if not isinstance(control_center, dict):
            control_center = {}
            self.app_config["control_center"] = control_center
        control_center["geometry"] = geometry
        snapshot = getattr(self, "_control_snapshot", None)
        if isinstance(snapshot, dict):
            snapshot_config = snapshot.setdefault("app_config", {})
            snapshot_center = snapshot_config.setdefault("control_center", {})
            if not isinstance(snapshot_center, dict):
                snapshot_center = {}
                snapshot_config["control_center"] = snapshot_center
            snapshot_center["geometry"] = geometry
        return geometry

    def _show_control_center(
        self,
        page="characters",
        initial_editor_character_id=None,
    ):
        valid_pages = {
            "characters",
            "conversation",
            "tasks",
            "models",
            "settings",
            "character_edit",
        }
        page = page if page in valid_pages else "characters"
        existing = getattr(self, "_control_dialog", None)
        if existing is not None and existing.winfo_exists():
            existing.attributes("-topmost", False)
            try:
                existing.deiconify()
                existing.lift()
            except tk.TclError:
                pass
            if page == "character_edit":
                self._show_control_character_editor(
                    initial_editor_character_id or self.character_id,
                    build_shell_sync=False,
                )
            else:
                self._show_control_page(page)
            self._reveal_control_dialog()
            if page == "character_edit":
                self._queue_control_editor_entry_preloads(
                    initial_editor_character_id or self.character_id
                )
            else:
                self._queue_default_control_editor_preloads()
            return
        dialog = tk.Toplevel(self.root)
        try:
            # Prevent Windows from exposing the native white client area
            # before Tk has finished laying out the settings content.
            dialog.attributes("-alpha", 0.0)
        except tk.TclError:
            pass
        dialog.withdraw()
        self._control_dialog = dialog
        self._control_dialogs.append(dialog)
        self._control_draft_active = True
        self._control_snapshot = self._capture_control_snapshot()
        self._brand_window(
            dialog,
            "桌宠设置",
            self._control_center_initial_geometry(),
        )
        dialog.resizable(True, True)
        dialog.minsize(960, 680)
        dialog.wm_attributes("-topmost", False)
        dialog.attributes("-topmost", False)
        dialog.configure(bg=BRAND_COLORS["bg"])
        self._pending_character_id = self.character_id
        self._control_page_frames = {}
        self._control_page_built = set()
        self._control_page_building = set()
        self._control_page_build_after = {}
        self._control_page_parent = None
        self._control_nav = {}
        self._control_main_nav_widgets = []
        self._control_editor_nav_widgets = []
        self._control_character_edit_buttons = {}
        self._control_outfit_nav_parent = None
        self._control_outfit_nav_parents = []
        self._control_sidebar_editing = False
        self._control_images = []
        self._control_model_vars = {}
        self._control_operation_vars = {}
        self._control_theme_var = None
        self._control_voice_output_var = None
        self._control_voice_volume_var = None
        self._control_language_button = None
        self._control_current_page = "characters"
        self._control_editor_preload_schedule_after = None
        self._control_editor_preload_build_after = None
        self._control_editor_preload_character_id = None
        self._control_editor_preload_queue = []
        self._control_pending_editor_open = False
        self._control_pending_editor_tab = None
        self._control_editor_cache_store = {}
        self._control_editor_cache_active_id = None
        self._control_dialog_revealed = False
        self._control_initializing_dialog = True

        self._build_control_header(dialog)

        body = tk.Frame(dialog, bg=BRAND_COLORS["bg"])
        body.pack(fill="both", expand=True, padx=18, pady=16)
        sidebar = tk.Frame(
            body,
            width=174,
            bg=BRAND_COLORS["bg"],
            highlightbackground=BRAND_COLORS["line"],
            highlightthickness=1,
        )
        sidebar.pack(side="left", fill="y", padx=(0, 14))
        sidebar.pack_propagate(False)
        self._control_sidebar_heading = tk.Label(
            sidebar,
            text="角色编辑",
            bg=BRAND_COLORS["bg"],
            fg=BRAND_COLORS["cyan_soft"],
            anchor="w",
            font=("Microsoft YaHei UI", 9, "bold"),
        )
        sidebar_scroll = tk.Frame(sidebar, bg=BRAND_COLORS["bg"])
        sidebar_scroll.pack(fill="both", expand=True, pady=(12, 0))
        sidebar_canvas = tk.Canvas(
            sidebar_scroll,
            bg=BRAND_COLORS["bg"],
            bd=0,
            highlightthickness=0,
        )
        sidebar_scrollbar = _BrandScrollbar(
            sidebar_scroll,
            orient="vertical",
            command=sidebar_canvas.yview,
            style="Brand.Vertical.TScrollbar",
        )
        sidebar_nav = tk.Frame(sidebar_canvas, bg=BRAND_COLORS["bg"])
        sidebar_window_id = sidebar_canvas.create_window(
            (0, 0),
            window=sidebar_nav,
            anchor="nw",
        )
        sidebar_canvas.configure(yscrollcommand=sidebar_scrollbar.set)
        sidebar_canvas.grid(row=0, column=0, sticky="nsew")
        sidebar_scrollbar.grid(row=0, column=1, sticky="ns")
        sidebar_scroll.grid_rowconfigure(0, weight=1)
        sidebar_scroll.grid_columnconfigure(0, weight=1)
        self._setup_brand_canvas_scroll(
            sidebar_canvas,
            sidebar_nav,
            sidebar_scrollbar,
            window_id=sidebar_window_id,
        )
        self._control_sidebar_scroll = sidebar_canvas
        self._control_sidebar_nav_content = sidebar_nav
        self._control_sidebar_scrollbar = sidebar_scrollbar
        for label, page_name in (
            ("角色", "characters"),
            ("历史对话", "conversation"),
            ("任务提醒", "tasks"),
            ("模型配置", "models"),
            ("设置", "settings"),
        ):
            button = tk.Button(
                sidebar_nav,
                text=label,
                anchor="w",
                command=lambda selected=page_name: self._show_control_page(selected),
                bg=BRAND_COLORS["bg_soft"],
                fg=BRAND_COLORS["white"],
                activebackground=BRAND_COLORS["cyan"],
                activeforeground=BRAND_COLORS["dark"],
                relief="flat",
                bd=0,
                padx=18,
                font=("Microsoft YaHei UI", 10, "bold"),
                cursor="hand2",
            )
            button.pack(fill="x", padx=10, pady=3, ipady=8)
            self._control_nav[page_name] = button
            self._control_main_nav_widgets.append(button)
        self._control_sidebar = sidebar

        self._control_content = tk.Frame(
            body,
            bg=BRAND_COLORS["bg_soft"],
            bd=0,
            highlightthickness=0,
        )
        self._control_content.pack(side="left", fill="both", expand=True)
        footer = tk.Frame(dialog, bg=BRAND_COLORS["bg"], height=42)
        footer.pack(fill="x")
        footer.pack_propagate(False)
        self._control_status = tk.StringVar(value=self._control_operation_hint())
        footer_status = tk.Label(
            footer,
            textvariable=self._control_status,
            bg=BRAND_COLORS["bg"],
            fg=BRAND_COLORS["muted"],
            font=("Microsoft YaHei UI", 9),
            anchor="w", justify="left", width=1,
        )
        footer_status.pack(side="left", fill="both", expand=True, padx=22)
        footer_status.bind("<Configure>", lambda event: footer_status.configure(wraplength=max(1, event.width)))
        self._brand_button(
            footer,
            "关闭",
            lambda: self._close_control_center(dialog),
        ).pack(side="right", padx=(0, 10), pady=5)
        self._brand_button(
            footer,
            "保存",
            lambda: self._save_control_center(dialog),
            accent=True,
        ).pack(side="right", pady=5)
        dialog.protocol("WM_DELETE_WINDOW", lambda: self._close_control_center(dialog))

        try:
            if page == "character_edit":
                # Keep the complete character list visible while the cached
                # editor is prepared; never expose an empty editor page.
                self._show_control_page_immediately("characters", build=True)
                self._show_control_character_editor(
                    initial_editor_character_id or self.character_id,
                    build_shell_sync=False,
                )
            else:
                self._show_control_page_immediately(page, build=True)
            dialog.update_idletasks()
        finally:
            self._control_initializing_dialog = False
        # The target page is fully laid out while the window is still hidden,
        # so its first mapped frame never contains a partial form.
        self._reveal_control_dialog()
        if page == "character_edit":
            self._queue_control_editor_entry_preloads(
                initial_editor_character_id or self.character_id
            )
        else:
            self._queue_default_control_editor_preloads(delay=80)

    def _reveal_control_dialog(self, page=None):
        """Show the settings shell as soon as its static layout exists."""
        if getattr(self, "_control_initializing_dialog", False):
            return False
        if getattr(self, "_control_dialog_revealed", False):
            return True
        dialog = getattr(self, "_control_dialog", None)
        if (
            dialog is None
            or not dialog.winfo_exists()
            or getattr(self, "_control_closing_dialog", None) is not None
        ):
            return False
        try:
            # Show the already-built shell immediately. Deferred scroll
            # refreshes below must never hold up the first mapped frame.
            dialog.attributes("-alpha", 1.0)
            dialog.deiconify()
            dialog.update_idletasks()
            dialog.lift()
            canvases = {}

            def collect_scroll_canvases(widget):
                update = getattr(widget, "_brand_scroll_update", None)
                if callable(update):
                    canvases[str(widget)] = update
                for child in widget.winfo_children():
                    collect_scroll_canvases(child)

            collect_scroll_canvases(dialog)

            def refresh_scroll_regions():
                if (
                    getattr(self, "_control_dialog_revealed_after", None)
                    is None
                ):
                    return
                self._control_dialog_revealed_after = None
                if (
                    getattr(self, "_control_dialog", None) is not dialog
                    or not dialog.winfo_exists()
                ):
                    return
                for update in canvases.values():
                    try:
                        update()
                    except tk.TclError:
                        continue

            self._control_dialog_revealed_after = self._safe_root_after(
                0,
                refresh_scroll_regions,
            )
        except tk.TclError:
            return False
        self._control_dialog_revealed = True
        return True

    def _preferred_control_editor_preload_character_id(self):
        """选择设置窗口打开后应预加载的角色编辑器。"""
        current_config = load_character_config(self.character_id)
        if self._is_live2d_character_config(current_config):
            return self.character_id
        for character in list_characters():
            character_id = str(character.get("id") or "").strip()
            if (
                character_id
                and self._is_live2d_character_config(character)
            ):
                return character_id
        return self.character_id

    def _queue_default_control_editor_preloads(self, delay=1):
        """Warm both the current editor and the first Live2D editor."""
        preferred = self._preferred_control_editor_preload_character_id()
        if not preferred:
            return
        self._schedule_control_editor_preload(preferred, delay=delay)
        if self.character_id and self.character_id != preferred:
            self._enqueue_control_editor_preload(self.character_id, delay=delay)

    def _queue_control_editor_entry_preloads(self, character_id):
        """Open the requested editor promptly, then warm the Live2D editor."""
        if not character_id:
            return
        preferred = self._preferred_control_editor_preload_character_id()
        active = getattr(self, "_control_editor_preload_character_id", None)
        if (
            active
            and active != character_id
            and self._control_editor_preload_is_in_flight(active)
        ):
            self._enqueue_control_editor_preload(character_id, delay=1)
        else:
            self._schedule_control_editor_preload(character_id, delay=1)
        if preferred and preferred != character_id:
            self._enqueue_control_editor_preload(preferred, delay=1)

    def _close_control_center(self, dialog):
        if dialog is None:
            return
        if getattr(self, "_control_closing_dialog", None) is not None:
            return
        self._control_closing_dialog = dialog
        self._store_control_center_geometry(dialog)
        self._cancel_control_editor_preload_schedule()
        self._end_live2d_preview()
        self._dispose_all_cached_control_editors()
        self._dispose_live2d_editor()
        self._refresh_control_tasks_view = None
        self._refresh_control_memory_view = None
        self._control_memory_panel = None
        self._cancel_character_theme_callbacks()
        self._control_dialog = None
        self._config_dialog = None
        try:
            self._destroy_control_outfit_nav(
                getattr(self, "_control_sidebar_editor_context", None),
                getattr(self, "_control_edit_context", None),
            )
            # 同一进程中可能残留旧版角色编辑窗口；关闭设置时统一销毁所有相关顶层窗口。
            self._destroy_control_dialogs()
        except tk.TclError:
            pass
        try:
            if getattr(self, "_control_draft_active", False):
                self._restore_control_snapshot()
            else:
                self._clear_character_theme_preview()
        except Exception:
            pass
        finally:
            self._control_page_frames = {}
            self._control_page_built = set()
            self._control_page_building = set()
            self._control_page_build_after = {}
            self._control_page_parent = None
            self._control_edit_context = None
            self._control_dialogs = []
            self._pending_character_id = self.character_id
            self._control_draft_active = False
            self._control_snapshot = None
            self._control_closing_dialog = None
            self._control_pending_editor_open = False
            self._control_pending_editor_tab = None
            self._control_editor_cache_store = {}
            self._control_editor_cache_active_id = None
            self._control_dialog_revealed = False
        try:
            save_app_config(self.app_config)
        except (OSError, RuntimeError, TypeError, ValueError):
            pass

    def _cancel_control_editor_preload_schedule(self, character_id=None):
        """Cancel delayed editor preparation and invalidate in-flight callbacks."""
        current_id = getattr(self, "_control_editor_preload_character_id", None)
        if character_id is None or character_id == current_id:
            self._control_editor_preload_generation = int(
                getattr(self, "_control_editor_preload_generation", 0)
            ) + 1
            self._control_editor_preload_character_id = None
            after_id = getattr(
                self,
                "_control_editor_preload_schedule_after",
                None,
            )
            self._control_editor_preload_schedule_after = None
            if after_id is not None:
                try:
                    self.root.after_cancel(after_id)
                except (AttributeError, tk.TclError):
                    pass
            build_after = getattr(
                self,
                "_control_editor_preload_build_after",
                None,
            )
            self._control_editor_preload_build_after = None
            if build_after is not None:
                try:
                    self.root.after_cancel(build_after)
                except (AttributeError, tk.TclError):
                    pass
        contexts = [getattr(self, "_control_edit_context", None)]
        for entry in getattr(self, "_control_editor_cache_store", {}).values():
            if isinstance(entry, dict):
                contexts.append(entry.get("context"))
        for context in {
            id(context): context
            for context in contexts
            if isinstance(context, dict)
        }.values():
            if character_id is not None and context.get("character_id") != character_id:
                continue
            preload_after = context.pop("live2d_preload_after", None)
            if preload_after is not None:
                try:
                    self.root.after_cancel(preload_after)
                except (AttributeError, tk.TclError):
                    pass
            context["live2d_preload_pages"] = set()

    def _control_editor_preload_is_in_flight(self, character_id):
        """Return whether preparation for this character is still pending."""
        if not character_id:
            return False
        entry = getattr(self, "_control_editor_cache_store", {}).get(character_id)
        cached_context = entry.get("context") if isinstance(entry, dict) else None
        cached_preload = (
            cached_context.get("live2d_editor_preload")
            if isinstance(cached_context, dict)
            else None
        )
        if (
            isinstance(cached_preload, dict)
            and cached_preload.get("status") == "building"
            and self._control_editor_context_is_alive(cached_context)
        ):
            return True
        if character_id != getattr(self, "_control_editor_preload_character_id", None):
            return False
        if getattr(self, "_control_editor_preload_schedule_after", None) is not None:
            return True
        if getattr(self, "_control_editor_preload_build_after", None) is not None:
            return True
        context = getattr(self, "_control_edit_context", None)
        if not isinstance(context, dict) or context.get("character_id") != character_id:
            return False
        preload = context.get("live2d_editor_preload")
        return bool(isinstance(preload, dict) and preload.get("status") == "building")

    def _enqueue_control_editor_preload(self, character_id, delay=1):
        """Queue a background editor preparation after the current one."""
        if not character_id:
            return
        if getattr(self, "_control_closing_dialog", None) is not None:
            return
        dialog = getattr(self, "_control_dialog", None)
        if dialog is None or not dialog.winfo_exists():
            return
        entry = getattr(self, "_control_editor_cache_store", {}).get(character_id)
        context = entry.get("context") if isinstance(entry, dict) else None
        preload = (
            context.get("live2d_editor_preload")
            if isinstance(context, dict)
            else None
        )
        if (
            isinstance(preload, dict)
            and preload.get("status") == "ready"
            and self._control_editor_context_is_alive(context)
        ):
            return
        queue = getattr(self, "_control_editor_preload_queue", None)
        if queue is None:
            queue = []
            self._control_editor_preload_queue = queue
        current = getattr(self, "_control_editor_preload_character_id", None)
        if current != character_id and character_id not in queue:
            queue.append(character_id)
        self._advance_control_editor_preload_queue(delay)

    def _advance_control_editor_preload_queue(self, delay=1):
        """Start the next queued editor once the active preparation settles."""
        queue = getattr(self, "_control_editor_preload_queue", None)
        if not queue:
            return
        current = getattr(self, "_control_editor_preload_character_id", None)
        if current is not None and self._control_editor_preload_is_in_flight(current):
            return
        while queue:
            character_id = queue.pop(0)
            entry = getattr(self, "_control_editor_cache_store", {}).get(
                character_id
            )
            context = entry.get("context") if isinstance(entry, dict) else None
            preload = (
                context.get("live2d_editor_preload")
                if isinstance(context, dict)
                else None
            )
            if (
                isinstance(preload, dict)
                and preload.get("status") == "ready"
                and self._control_editor_context_is_alive(context)
            ):
                continue
            self._schedule_control_editor_preload(character_id, delay=delay)
            return

    def _schedule_control_editor_preload(self, character_id, delay=1):
        """Prepare Live2D editor pages while the current settings page stays visible."""
        if getattr(self, "_control_closing_dialog", None) is not None:
            return
        dialog = getattr(self, "_control_dialog", None)
        if dialog is None or not dialog.winfo_exists():
            return
        entry = getattr(self, "_control_editor_cache_store", {}).get(character_id)
        context = entry.get("context") if isinstance(entry, dict) else None
        if not (isinstance(context, dict) and context.get("character_id") == character_id):
            context = getattr(self, "_control_edit_context", None)
            if not (
                isinstance(context, dict)
                and context.get("character_id") == character_id
            ):
                context = None
        preload = (
            context.get("live2d_editor_preload")
            if isinstance(context, dict)
            else None
        )
        if self._control_editor_preload_is_in_flight(character_id):
            return
        if (
            isinstance(preload, dict)
            and preload.get("status") == "ready"
            and self._control_editor_context_is_alive(context)
        ):
            return
        self._cancel_control_editor_preload_schedule(character_id)
        self._control_editor_preload_character_id = character_id
        generation = int(getattr(self, "_control_editor_preload_generation", 0))

        def start():
            self._control_editor_preload_schedule_after = None
            queue = getattr(self, "_control_editor_preload_queue", None)
            if queue and character_id in queue:
                queue.remove(character_id)
            if (
                generation != getattr(self, "_control_editor_preload_generation", 0)
                or getattr(self, "_control_closing_dialog", None) is not None
            ):
                return
            try:
                self._start_control_editor_preload(character_id, generation)
            except (OSError, RuntimeError, TypeError, ValueError, tk.TclError) as error:
                context = getattr(self, "_control_edit_context", None)
                if isinstance(context, dict):
                    self._fail_live2d_editor_preload(context, error)

        try:
            self._control_editor_preload_schedule_after = self.root.after(
                max(1, int(delay)),
                start,
            )
        except (AttributeError, tk.TclError):
            self._control_editor_preload_schedule_after = None

    def _ensure_control_editor_cache_frame(self, character_id):
        """Return the hidden cache frame used to build an editor off-screen."""
        store = getattr(self, "_control_editor_cache_store", None)
        if store is None:
            store = {}
            self._control_editor_cache_store = store
        entry = store.get(character_id)
        if not isinstance(entry, dict):
            entry = {}
            store[character_id] = entry
        frame = entry.get("frame")
        if frame is None or not frame.winfo_exists():
            frame = tk.Frame(
                self._control_content,
                bg=BRAND_COLORS["bg_soft"],
            )
            # Keep the hidden editor at the real page size so canvases and
            # scroll regions measured during the preload match the visible page.
            frame.place(relx=0, rely=0, relwidth=1, relheight=1)
            try:
                frame.lower()
            except tk.TclError:
                pass
            entry.update(
                {
                    "frame": frame,
                    "context": None,
                    "built": False,
                }
            )
        return entry, frame

    def _build_control_editor_shell_sync(self, character_id):
        """Build only the editor shell synchronously, leaving heavy pages lazy."""
        if not (get_character_dir(character_id) / "character.json").exists():
            return None
        self._cancel_control_editor_preload_schedule()
        generation = int(
            getattr(self, "_control_editor_preload_generation", 0)
        ) + 1
        self._control_editor_preload_generation = generation
        self._control_editor_preload_character_id = character_id
        self._ensure_control_editor_cache_frame(character_id)
        self._build_control_editor_preload(character_id, generation)
        entry = getattr(self, "_control_editor_cache_store", {}).get(
            character_id
        )
        context = entry.get("context") if isinstance(entry, dict) else None
        if not self._control_editor_context_is_alive(context):
            return None
        return self._restore_cached_control_editor(character_id)

    def _start_control_editor_preload(self, character_id, generation):
        if not (get_character_dir(character_id) / "character.json").exists():
            return
        if character_id != getattr(
            self,
            "_control_editor_preload_character_id",
            None,
        ):
            return
        entry, _frame = self._ensure_control_editor_cache_frame(character_id)

        context = entry.get("context")
        if not self._control_editor_context_is_alive(context):
            if entry.get("built"):
                entry.update({"context": None, "built": False})
            context = None
        preload = (
            context.get("live2d_editor_preload")
            if isinstance(context, dict)
            else None
        )
        if (
            isinstance(preload, dict)
            and preload.get("status") in ("building", "ready")
        ):
            if preload.get("status") == "building":
                self._advance_live2d_editor_preload(
                    context,
                    preload.get("generation"),
                )
            self._open_pending_control_editor(
                context,
                allow_building=preload.get("status") == "building",
            )
            return

        if not entry.get("built") or not isinstance(context, dict):
            def build():
                self._control_editor_preload_build_after = None
                self._build_control_editor_preload(
                    character_id,
                    generation,
                )

            try:
                self._control_editor_preload_build_after = self.root.after(
                    16,
                    build,
                )
            except (AttributeError, tk.TclError) as error:
                self._control_editor_preload_build_after = None
                fallback = entry.get("context")
                if isinstance(fallback, dict):
                    self._fail_live2d_editor_preload(fallback, error)
            return
        context["live2d_editor_preload"] = {
            "generation": generation,
            "status": "building",
            "error": None,
        }
        context["live2d_preload_pages"] = {"portrait"}
        context["live2d_thumbnail_preload"] = True
        if not context.get("is_live2d"):
            context["live2d_editor_preload"]["status"] = "ready"
            context["live2d_preload_pages"] = set()
            self._open_pending_control_editor(context)
            self._advance_control_editor_preload_queue()
            return
        self._open_pending_control_editor(context, allow_building=True)
        self._advance_live2d_editor_preload(context, generation)

    def _build_control_editor_preload(self, character_id, generation):
        """Build an editor in a hidden frame without disturbing the visible page."""
        dialog = getattr(self, "_control_dialog", None)
        entry = getattr(self, "_control_editor_cache_store", {}).get(character_id)
        if not isinstance(entry, dict):
            return
        # A queued build can outlive an older cache frame. Resolve the frame
        # from the current cache entry so the build targets the live editor.
        frame = entry.get("frame")
        if (
            generation != getattr(self, "_control_editor_preload_generation", 0)
            or character_id
            != getattr(self, "_control_editor_preload_character_id", None)
            or getattr(self, "_control_closing_dialog", None) is not None
            or dialog is None
            or not dialog.winfo_exists()
            or frame is None
            or not frame.winfo_exists()
        ):
            return

        active_context = getattr(self, "_control_edit_context", None)
        active_frame = getattr(self, "_control_page_frames", {}).get(
            "character_edit"
        )
        active_character_id = getattr(
            self,
            "_control_edit_character_id",
            None,
        )
        active_live2d_host = getattr(self, "_control_live2d_host", None)
        active_live2d_context = getattr(self, "_control_live2d_context", None)
        previous_parent = self._control_page_parent
        previous = self._suspend_live2d_tick_for_control_build()
        build_error = None
        context = None
        try:
            # The visible page and its context must stay untouched while the
            # hidden editor builds its own renderer and tab widgets.
            self._control_page_frames["character_edit"] = frame
            self._control_page_parent = frame
            self._control_edit_character_id = character_id
            self._control_character_edit()
            context = self._control_edit_context
        except (OSError, RuntimeError, TypeError, ValueError, tk.TclError) as error:
            build_error = error
        finally:
            if active_frame is None:
                self._control_page_frames.pop("character_edit", None)
            else:
                self._control_page_frames["character_edit"] = active_frame
            self._control_page_parent = previous_parent
            self._control_edit_context = active_context
            self._control_edit_character_id = active_character_id
            self._control_live2d_host = active_live2d_host
            self._control_live2d_context = active_live2d_context
            self._resume_live2d_tick_after_control_build(previous)

        if build_error is not None:
            entry["context"] = None
            entry["built"] = False
            if hasattr(self, "_control_status"):
                self._control_status.set(
                    "Live2D 编辑页预加载失败：{}".format(build_error)
                )
            return
        if (
            not isinstance(context, dict)
            or context.get("character_id") != character_id
            or not frame.winfo_exists()
        ):
            return
        entry["context"] = context
        entry["built"] = True
        context["live2d_editor_preload"] = {
            "generation": generation,
            "status": "building",
            "error": None,
        }
        context["live2d_preload_pages"] = {"portrait"}
        context["live2d_thumbnail_preload"] = True
        if not context.get("is_live2d"):
            context["live2d_editor_preload"]["status"] = "ready"
            context["live2d_preload_pages"] = set()
            self._open_pending_control_editor(context)
            self._advance_control_editor_preload_queue()
            return
        self._open_pending_control_editor(context, allow_building=True)
        self._advance_live2d_editor_preload(context, generation)

    def _advance_live2d_editor_preload(self, context, generation=None, delay=1):
        if not isinstance(context, dict):
            return
        preload = context.get("live2d_editor_preload")
        if not isinstance(preload, dict) or preload.get("status") != "building":
            return
        if generation is not None and generation != preload.get("generation"):
            return
        if not self._control_editor_context_is_alive(context):
            return
        if context.get("live2d_preload_after") is not None:
            return

        def run():
            context["live2d_preload_after"] = None
            self._continue_live2d_editor_preload(
                context,
                preload.get("generation"),
            )

        try:
            context["live2d_preload_after"] = self.root.after(
                max(1, int(delay)),
                run,
            )
        except (AttributeError, tk.TclError):
            context["live2d_preload_after"] = None

    def _continue_live2d_editor_preload(self, context, generation):
        preload = context.get("live2d_editor_preload")
        if (
            not isinstance(preload, dict)
            or preload.get("status") != "building"
            or generation != preload.get("generation")
            or not self._control_editor_context_is_alive(context)
        ):
            return
        lazy = context.get("editor_lazy_tabs", {})
        portrait = lazy.get("portrait")
        settings = context.get("live2d_settings_status")
        if portrait is None:
            self._fail_live2d_editor_preload(context, "服装页不可用")
            return
        if portrait.get("status") == "failed" or settings == "failed":
            self._fail_live2d_editor_preload(
                context,
                portrait.get("error") or context.get("live2d_settings_error")
                or "Live2D 编辑页加载失败",
            )
            return

        preload_pages = context.setdefault("live2d_preload_pages", set())
        if not portrait.get("initialized"):
            preload_pages.update(("portrait", "settings"))
            try:
                self._ensure_control_editor_tab(context, "portrait")
            except (OSError, RuntimeError, TypeError, ValueError, tk.TclError) as error:
                portrait["status"] = "failed"
                portrait["error"] = str(error)
                self._fail_live2d_editor_preload(context, error)
                return
            self._schedule_live2d_settings_refresh(context, force=True)
            self._schedule_live2d_thumbnail_processing(context, 1)
            self._advance_live2d_editor_preload(context, generation, delay=20)
            return

        # Prepare both tabs concurrently without waiting for outfit thumbnails.
        preload_pages.add("settings")
        if settings in (None, "idle"):
            self._schedule_live2d_settings_refresh(context, force=True)

        portrait_pending = bool(
            self._live2d_thumbnail_jobs_for_page(context, "portrait")
            or context.get("live2d_appearance_scroll_after") is not None
            or context.get("live2d_viewport_after") is not None
            or context.get("live2d_viewport_pending")
            or portrait.get("building")
        )
        if not portrait_pending and not portrait.get("ready"):
            portrait["ready"] = True
            portrait["status"] = "ready"
        if not portrait_pending:
            preload_pages.discard("portrait")

        settings = context.get("live2d_settings_status")
        self._update_live2d_settings_ready(context)
        settings_pending = bool(
            settings != "ready"
            or not context.get("live2d_settings_ready")
            or context.get("live2d_settings_build_after") is not None
            or self._live2d_thumbnail_jobs_for_page(context, "settings")
            or context.get("live2d_settings_building")
            or context.get("live2d_settings_prepare_pending")
        )
        if settings_pending:
            if settings in (None, "idle"):
                self._schedule_live2d_settings_refresh(context, force=True)
            self._schedule_live2d_thumbnail_processing(context, 1)
            self._advance_live2d_editor_preload(context, generation, delay=20)
            return
        preload_pages.discard("settings")
        if portrait_pending or "portrait" in preload_pages:
            self._schedule_live2d_thumbnail_processing(context, 1)
            self._advance_live2d_editor_preload(context, generation, delay=20)
            return

        preload_pages.clear()
        context["live2d_thumbnail_preload"] = False
        preload["status"] = "ready"
        preload["error"] = None
        context["live2d_editor_preload_ready"] = True
        self._advance_control_editor_preload_queue()
        if self._open_pending_control_editor(context):
            return
        pending = getattr(self, "_control_pending_editor_tab", None)
        if (
            pending is not None
            and context is getattr(self, "_control_edit_context", None)
            and self._control_current_page == "character_edit"
        ):
            notebook = context.get("editor_notebook")
            if notebook is not None and notebook.winfo_exists():
                self._select_control_editor_tab(
                    notebook,
                    context,
                    pending,
                    context.get("theme_tab_index", 0),
                )

    def _open_pending_control_editor(self, context, allow_building=False):
        pending_open = getattr(self, "_control_pending_editor_open", None)
        if (
            not pending_open
            or not self._control_editor_context_is_alive(context)
            or context.get("character_id") != pending_open
        ):
            return False
        preload = context.get("live2d_editor_preload")
        if (
            not isinstance(preload, dict)
            or preload.get("status") not in (
                ("building", "ready") if allow_building else ("ready",)
            )
        ):
            return False
        # Keep the request pending until the scheduled callback runs. Opening
        # synchronously here can make a menu action wait for the page build.
        self._control_pending_editor_open = False
        if (
            hasattr(self, "_control_status")
            and self._control_status.get() in (
                "正在准备编辑器页面，请稍候",
                "正在准备角色编辑...",
            )
        ):
            self._refresh_control_operation_hint()
        try:
            self.root.after(
                0,
                lambda selected=pending_open: self._show_control_character_editor(
                    selected
                ),
            )
        except (AttributeError, tk.TclError):
            self._control_pending_editor_open = pending_open
            return False
        return True

    def _fail_live2d_editor_preload(self, context, error):
        if not isinstance(context, dict):
            return
        preload = context.setdefault("live2d_editor_preload", {})
        preload["status"] = "failed"
        preload["error"] = str(error)
        context["live2d_preload_pages"] = set()
        context["live2d_thumbnail_preload"] = False
        if hasattr(self, "_control_status"):
            self._control_status.set("Live2D 编辑页预加载失败：{}".format(error))
        self._advance_control_editor_preload_queue()
        pending_open = getattr(self, "_control_pending_editor_open", None)
        if pending_open:
            self._control_pending_editor_open = None
            fallback_page = getattr(self, "_control_current_page", None)
            if (
                fallback_page == "character_edit"
                or fallback_page not in getattr(
                    self,
                    "_control_page_built",
                    set(),
                )
            ):
                fallback_page = "characters"
            self._show_control_page_immediately(
                fallback_page,
                build=True,
            )

    @staticmethod
    def _live2d_thumbnail_jobs_for_page(context, page):
        return sum(
            1 for job in context.get("live2d_thumbnail_jobs", [])
            if len(job) > 6 and job[6] == page
        ) + sum(
            1 for job in context.get("live2d_thumbnail_pending", {}).values()
            if job[6] == page
        )

    def _cancel_character_theme_callbacks(self):
        self._cancel_character_theme_sample_sync()
        after_id = getattr(self, "_theme_sample_initial_after_id", None)
        self._theme_sample_initial_after_id = None
        if after_id is not None:
            try:
                self.root.after_cancel(after_id)
            except tk.TclError:
                pass

    def _destroy_control_dialogs(self):
        """销毁设置及旧版角色编辑顶层窗口，避免关闭后露出残留窗口。"""
        known = list(getattr(self, "_control_dialogs", []))
        current = getattr(self, "_control_dialog", None)
        if current is not None:
            known.append(current)
        excluded = {
            id(getattr(self, "inline_reply_frame", None)),
            id(getattr(self, "inline_reply_background_frame", None)),
        }
        candidates = []
        for widget in self.root.winfo_children():
            try:
                title = str(widget.title())
                if (
                    id(widget) not in excluded
                    and (
                        "桌宠设置" in title
                        or "角色编辑" in title
                    )
                ):
                    candidates.append(widget)
            except (AttributeError, tk.TclError):
                continue
        for widget in known + candidates:
            try:
                if widget.winfo_exists():
                    widget.destroy()
            except tk.TclError:
                pass

    def _restore_control_snapshot(self):
        snapshot = getattr(self, "_control_snapshot", None)
        if not snapshot:
            self._clear_character_theme_preview()
            return
        self._clear_character_theme_preview(apply=False)
        visual_changed = any(
            (
                self.character_id != snapshot["character_id"],
                self.display_mode != snapshot["display_mode"],
                self.theme_name != snapshot["theme_name"],
                bool(self.root.attributes("-topmost")) != snapshot["topmost"],
                self.character_config != snapshot["character_config"],
            )
        )
        conversation_settings = {
            key: copy.deepcopy(self.store.settings[key])
            for key in ("active_conversation_ids", "current_conversation_id")
            if key in self.store.settings
        }
        self.store.settings = copy.deepcopy(snapshot["settings"])
        self.store.settings.update(conversation_settings)
        self._refresh_tray_menu()
        self.output_language = self._default_output_language()
        self._update_language_buttons()
        if load_json(self.store.settings_path, {}) != self.store.settings:
            save_json(self.store.settings_path, self.store.settings)
        self.app_config = copy.deepcopy(snapshot["app_config"])
        if load_json(ROOT / "config" / "app_config.json", {}) != self.app_config:
            save_app_config(self.app_config)
        self.character_id = snapshot["character_id"]
        self.character_config = copy.deepcopy(snapshot["character_config"])
        self.voice_config = copy.deepcopy(snapshot["voice_config"])
        self.character_dir = snapshot["character_dir"]
        self.display_mode = snapshot["display_mode"]
        self.portrait_scale = snapshot["portrait_scale"]
        self.theme_name = snapshot["theme_name"]
        self.theme = snapshot["theme"]
        self.root.wm_attributes("-topmost", snapshot["topmost"])
        self._sync_pet_topmost(force=True)
        if visual_changed:
            self._clear_portrait_canvas()
            self._replace_portrait_renderer()
            self._apply_display_mode()
            self._apply_theme()
            self._update_topmost_labels()
            self._render_state()
        else:
            self._apply_character_chat_theme()
            self._apply_live2d_preferences(self.renderer)
        self._refresh_live2d_settings_section()

    def _save_control_center(self, dialog):
        try:
            self._end_live2d_preview()
            pending = getattr(self, "_pending_character_id", self.character_id)
            character_changed = pending != self.character_id
            reopen_page = getattr(self, "_control_current_page", "characters")
            editor_context = (
                getattr(self, "_control_edit_context", None)
                if reopen_page == "character_edit"
                else None
            )
            operation_vars = getattr(self, "_control_operation_vars", {})
            operation_values = self._control_mapping_values(operation_vars)
            self._validate_control_operation_values(operation_values)
            model_values = {}
            if self._control_model_vars:
                for (section, key), variable in self._control_model_vars.items():
                    value = variable.get()
                    if key in ("context_window_tokens", "reply_reserve_tokens"):
                        try:
                            value = int(value)
                        except (ValueError, TypeError):
                            raise ValueError("上下文容量和回复预留必须填写整数。") from None
                        if value < (1024 if key == "context_window_tokens" else 16):
                            raise ValueError("上下文容量至少1024 Token，回复预留至少16 Token。")
                    model_values[(section, key)] = value
                from core.context_budget import PromptBudget
                for section in {section for section, key in model_values}:
                    config = dict(self.app_config.get(section, {}))
                    config.update({key: value for (name, key), value in model_values.items() if name == section})
                    if PromptBudget(config).input_limit < 1024:
                        raise ValueError("上下文容量必须大于回复预留与安全余量，并至少留下1024 Token用于输入。")
            if pending != self.character_id:
                self.switch_character(pending)
            for (section, key), value in model_values.items():
                self.app_config.setdefault(section, {})[key] = value
            if not self._save_control_behavior_settings(
                dialog,
                persist=False,
            ):
                return
            self._save_control_operation_values(
                persist=False,
                values=operation_values,
            )
            voice_output = (
                bool(self._control_voice_output_var.get())
                if getattr(self, "_control_voice_output_var", None) is not None
                else bool(self.store.settings.get("voice_output", True))
            )
            voice_volume = max(
                0,
                min(
                    100,
                    int(self._control_voice_volume_var.get())
                    if getattr(self, "_control_voice_volume_var", None)
                    is not None
                    else int(self.store.settings.get("voice_volume", 50)),
                ),
            )
            selected_theme = None
            if getattr(self, "_control_theme_var", None) is not None:
                theme_names = {value["name"]: key for key, value in THEMES.items()}
                selected_theme = theme_names.get(
                    self._control_theme_var.get(),
                    self.theme_name,
                )
            if editor_context is not None and not self._save_control_character_editor(
                editor_context,
                return_to_characters=False,
            ):
                return
            selected_theme_changed = False
            if selected_theme is not None:
                selected_theme_changed = selected_theme != self.theme_name
                self.theme_name = selected_theme
                self.theme = THEMES[selected_theme]
            self.store.save_settings(
                {
                    "display_mode": self.display_mode,
                    "always_on_top": bool(self.root.attributes("-topmost")),
                    "voice_output": voice_output,
                    "voice_volume": voice_volume,
                    "theme": self.theme_name,
                }
            )
            save_app_config(self.app_config)
            if self.store.settings.get("voice_output", True):
                self._safe_root_after(0, self._warmup_tts_service)
            if selected_theme_changed:
                self._apply_theme()
                self._render_state()
            self._control_draft_active = False
            self._control_snapshot = None
            if character_changed:
                # 角色切换会改变角色页状态和部分角色专属控件。
                # 保存后重建设置窗口，避免旧页面继续持有原角色的控件和图片。
                if dialog is not None and dialog.winfo_exists():
                    self._store_control_center_geometry(dialog)
                    dialog.withdraw()
                    dialog.destroy()
                if getattr(self, "_control_dialog", None) is dialog:
                    self._control_dialog = None
                self._cancel_control_editor_preload_schedule()
                self._dispose_all_cached_control_editors()
                self._dispose_control_editor_context(
                    getattr(self, "_control_edit_context", None)
                )
                self._control_edit_context = None
                self._control_live2d_host = None
                self._control_live2d_context = None
                self._pending_character_id = self.character_id
                if reopen_page == "character_edit":
                    # Reopen on the light character list and show the editor
                    # shell immediately, so the rebuilt window never blocks.
                    self._show_control_center("characters")
                    self._show_control_character_editor(self.character_id)
                else:
                    self._show_control_center(reopen_page)
                return
            if editor_context is not None:
                # _save_control_character_editor 已将当前编辑器和运行时同步，
                # 此处保留现有控件，避免保存后再次重载 Live2D 和整页缩略图。
                self._refresh_control_operation_hint("角色与配置已保存")
            else:
                self._refresh_control_operation_hint("配置已保存")
        except (OSError, RuntimeError, ValueError, AttributeError, TypeError) as error:
            messagebox.showerror(
                "配置保存失败",
                "配置未能写入：{}".format(error),
                parent=dialog,
            )

    def _save_control_behavior_settings(self, dialog, persist=True):
        directory_var = getattr(self, "_control_screenshot_directory_var", None)
        if directory_var is not None:
            try:
                screenshot_directory = resolve_screenshot_directory(directory_var.get())
                screenshot_directory.mkdir(parents=True, exist_ok=True)
            except OSError as error:
                messagebox.showerror(
                    "截图目录无效",
                    "无法使用该截图存放地址：{}".format(error),
                    parent=dialog,
                )
                return False
            self.app_config["screenshot_directory"] = str(screenshot_directory)
            directory_var.set(str(screenshot_directory))

        voice_directory_var = getattr(self, "_control_voice_directory_var", None)
        if voice_directory_var is not None:
            try:
                voice_directory = ensure_voice_directory(voice_directory_var.get())
            except OSError as error:
                messagebox.showerror(
                    "语音目录无效",
                    "无法使用该语音存放地址：{}".format(error),
                    parent=dialog,
                )
                return False
            self.app_config["voice_directory"] = str(voice_directory)
            voice_directory_var.set(str(voice_directory))

        companionship_var = getattr(self, "_control_companionship_var", None)
        if companionship_var is not None:
            companionship = self.app_config.setdefault(
                "autonomous_conversation",
                {
                    "enabled": False,
                    "interval_minutes": 60,
                    "vision_enabled": False,
                },
            )
            companionship["enabled"] = bool(companionship_var.get())
            interval_var = getattr(
                self,
                "_control_companionship_interval_var",
                None,
            )
            if interval_var is not None:
                self._commit_companionship_interval(interval_var, persist=False)
            else:
                companionship.setdefault("interval_minutes", 60)
            vision_var = getattr(
                self,
                "_control_companionship_vision_var",
                None,
            )
            if vision_var is not None:
                companionship["vision_enabled"] = bool(vision_var.get())
            else:
                companionship.setdefault("vision_enabled", False)
        autostart_var = getattr(self, "_control_autostart_var", None)
        if autostart_var is not None:
            autostart = self.app_config.setdefault("autostart", {})
            current = bool(autostart.get("enabled", False))
            requested = bool(autostart_var.get())
            if requested != current:
                try:
                    self._set_autostart_enabled(requested)
                except (OSError, RuntimeError) as error:
                    messagebox.showerror(
                        "开机启动设置失败",
                        "无法修改开机启动项：{}".format(error),
                        parent=dialog,
                    )
                    autostart_var.set(current)
                    return False
            autostart["enabled"] = requested
        if getattr(self, "_control_companionship_var", None) is not None:
            self._configure_companionship()
        if persist:
            save_app_config(self.app_config)
        return True

    def _show_control_page(self, page):
        if getattr(self, "_control_closing_dialog", None) is not None:
            return
        if page == "character_edit":
            context = getattr(self, "_control_edit_context", None)
            frame = getattr(self, "_control_page_frames", {}).get(
                "character_edit"
            )
            has_active_editor = bool(
                isinstance(context, dict)
                and frame is not None
                and frame.winfo_exists()
            )
            if not has_active_editor:
                # Editor pages are always produced by the background preload,
                # so opening the page never builds heavy content inline.
                selected = (
                    getattr(self, "_control_pending_editor_open", None)
                    or getattr(self, "_control_edit_character_id", None)
                    or self.character_id
                )
                if selected:
                    self._show_control_character_editor(selected)
                    self._update_control_navigation(page)
                    return
        if page != "character_edit":
            self._control_pending_editor_open = False
        if page != "character_edit":
            self._end_live2d_preview()
        if page != "character_edit":
            context = getattr(self, "_control_edit_context", None)
            if context is not None:
                self._pause_portrait_manager_work(context)
        if page != "character_edit":
            self._clear_character_theme_preview()
        self._update_control_navigation(page)
        frame = self._control_page_frames.get(page)
        # A visible editor shell must exist before any deferred page build so
        # menu callbacks never wait for the heavy editor content.
        if (
            frame is None
            or not frame.winfo_exists()
            or (
                page == "character_edit"
                and getattr(self, "_control_pending_editor_open", None)
                and frame.winfo_manager() != "place"
            )
        ):
            frame = tk.Frame(self._control_content, bg=BRAND_COLORS["bg_soft"])
            frame.place(relx=0, rely=0, relwidth=1, relheight=1)
            self._control_page_frames[page] = frame
            self._control_page_built.discard(page)
        if page not in self._control_page_built:
            if page == "character_edit":
                pending = self._control_page_build_after.get(page)
                if pending is None:
                    self._control_page_build_after[page] = frame.after(
                        20,
                        lambda selected=page, target=frame:
                        self._build_control_page_after_transition(selected, target),
                    )
            else:
                self._build_control_page(page, frame)
        frame.tkraise()
        self._control_current_page = page
        if page != "character_edit" or page in self._control_page_built:
            self._set_control_sidebar_mode(page == "character_edit")
        if page in self._control_page_built:
            self._reveal_control_dialog(page)

    def _build_control_page(self, page, frame):
        building = getattr(self, "_control_page_building", None)
        if building is None:
            building = set()
            self._control_page_building = building
        if page == "character_edit" and not isinstance(
            getattr(self, "_control_edit_context", None),
            dict,
        ):
            # The editor must be created by the cached preload path so the UI
            # thread never blocks on model preparation.
            return
        if (
            frame is not self._control_page_frames.get(page)
            or not frame.winfo_exists()
            or page in self._control_page_built
            or page in building
        ):
            return
        builders = {
            "characters": self._control_characters,
            "character_edit": self._control_character_edit,
            "conversation": self._control_conversation,
            "tasks": self._control_tasks,
            "models": self._control_models,
            "settings": self._control_settings,
        }
        previous = self._control_page_parent
        building.add(page)
        self._control_page_parent = frame
        try:
            builders[page]()
            self._control_page_built.add(page)
            if page == getattr(self, "_control_current_page", None):
                self._reveal_control_dialog(page)
        finally:
            self._control_page_parent = previous
            building.discard(page)

    def _build_control_page_after_transition(self, page, frame):
        self._control_page_build_after.pop(page, None)
        if (
            page != self._control_current_page
            or not frame.winfo_exists()
            or frame is not self._control_page_frames.get(page)
        ):
            return
        suspend_render = page == "character_edit"
        if suspend_render:
            self._cancel_live2d_tick()
            self._live2d_tick_suspended_for_editor_build = True
        try:
            self._build_control_page(page, frame)
            self._set_control_sidebar_mode(
                page == "character_edit"
                and isinstance(
                    getattr(self, "_control_edit_context", None),
                    dict,
                )
            )
        finally:
            if suspend_render:
                self._live2d_tick_suspended_for_editor_build = False
                self._schedule_live2d_tick()

    def _set_control_sidebar_mode(self, editing):
        was_editing = self._control_sidebar_editing
        if not editing:
            previous_context = getattr(
                self,
                "_control_sidebar_editor_context",
                None,
            )
            self._destroy_control_outfit_nav(previous_context)
        if was_editing == editing:
            if editing:
                context = getattr(self, "_control_edit_context", None)
                expected_nav_count = (
                    len(context.get("editor_tab_titles", ())) + 1
                    if context is not None
                    else 0
                )
                nav_is_valid = (
                    context is getattr(
                        self,
                        "_control_sidebar_editor_context",
                        None,
                    )
                    and len(self._control_editor_nav_widgets)
                    == expected_nav_count
                    and all(
                        widget.winfo_exists()
                        for widget in self._control_editor_nav_widgets
                    )
                )
                if not nav_is_valid:
                    self._build_control_editor_nav(context)
            return
        self._control_sidebar_editing = editing
        for widget in self._control_editor_nav_widgets:
            try:
                widget.destroy()
            except tk.TclError:
                pass
        self._control_editor_nav_widgets = []

        if editing:
            if not was_editing:
                for widget in self._control_main_nav_widgets:
                    widget.pack_forget()
            self._control_sidebar_heading.configure(text="角色编辑")
            self._control_sidebar_heading.pack(
                fill="x", padx=18, pady=(20, 0),
                before=self._control_sidebar_scroll.master,
            )
            self._control_header_title.configure(
                text="编辑角色：{}".format(
                    self._control_edit_context["character_config"].get(
                        "display_name",
                        self._control_edit_context["character_id"],
                    )
                )
            )
            self._control_header_subtitle.configure(
                text="CHARACTER EDITOR",
            )
            self._control_role_badge.pack_forget()
            self._control_dialog.title(self._control_header_title.cget("text"))
            context = self._control_edit_context
            notebook = context.get("editor_notebook")
            if notebook is None or not notebook.winfo_exists():
                return
            self._build_control_editor_nav(context)
            self._refresh_control_editor_nav(notebook)
            self._on_control_editor_tab_changed(notebook, context)
            return

        if was_editing:
            for widget in self._control_main_nav_widgets:
                widget.pack(fill="x", padx=10, pady=3, ipady=8)
        self._control_sidebar_heading.pack_forget()
        self._control_header_title.configure(text="桌宠设置")
        self._control_header_subtitle.configure(
            text="DESKTOP PET  /  {}".format(
                self._character_display_name().upper()
            )
        )
        self._control_role_badge.pack(side="right", padx=22, pady=22)
        self._control_dialog.title("桌宠设置")
        self._control_sidebar_editor_context = None

    def _destroy_control_outfit_nav(self, *contexts):
        candidates = []
        for context in contexts:
            if isinstance(context, dict):
                parent = context.get("outfit_nav_parent")
                if parent is not None:
                    candidates.append(parent)
                context["outfit_nav_parent"] = None
                context["outfit_nav_buttons"] = {}

        tracked_parent = getattr(self, "_control_outfit_nav_parent", None)
        if tracked_parent is not None:
            candidates.append(tracked_parent)
        tracked_parents = getattr(self, "_control_outfit_nav_parents", None)
        if tracked_parents is not None:
            candidates.extend(tracked_parents)
            tracked_parents.clear()
        sidebar = getattr(self, "_control_sidebar_nav_content", None)
        if sidebar is None:
            sidebar = getattr(self, "_control_sidebar", None)
        if sidebar is not None:
            pending_widgets = [sidebar]
            while pending_widgets:
                parent = pending_widgets.pop()
                try:
                    children = parent.winfo_children()
                except (AttributeError, tk.TclError):
                    continue
                for child in children:
                    if getattr(child, "_portrait_outfit_nav", False) is True:
                        candidates.append(child)
                    else:
                        pending_widgets.append(child)

        destroyed = set()
        for parent in candidates:
            if parent is None or id(parent) in destroyed:
                continue
            destroyed.add(id(parent))
            try:
                parent.destroy()
            except tk.TclError:
                pass
        self._control_outfit_nav_parent = None

    def _build_control_editor_nav(self, context):
        previous_context = getattr(
            self,
            "_control_sidebar_editor_context",
            None,
        )
        if previous_context is context:
            notebook = context.get("editor_notebook")
            if notebook is not None and notebook.winfo_exists():
                self._refresh_control_editor_nav(notebook)
                return
        self._destroy_control_outfit_nav(previous_context, context)
        for widget in self._control_editor_nav_widgets:
            try:
                widget.destroy()
            except tk.TclError:
                pass
        self._control_editor_nav_widgets = []
        self._control_sidebar_editor_context = context
        if context is None:
            return
        context["outfit_nav_parent"] = None

        back_button = self._brand_button(
            self._control_sidebar_nav_content,
            "返回角色",
            self._return_control_characters,
        )
        back_button.pack(fill="x", padx=10, pady=(2, 10), ipady=4)
        self._control_editor_nav_widgets.append(back_button)
        notebook = context.get("editor_notebook")
        if notebook is None or not notebook.winfo_exists():
            return
        for index, title in enumerate(context["editor_tab_titles"]):
            button = tk.Button(
                self._control_sidebar_nav_content,
                text=title,
                anchor="w",
                command=lambda selected=index, selected_notebook=notebook,
                editor_context=context: self._select_control_editor_tab(
                    selected_notebook,
                    editor_context,
                    selected,
                    editor_context["theme_tab_index"],
                ),
                bg=BRAND_COLORS["bg_soft"],
                fg=BRAND_COLORS["white"],
                activebackground=BRAND_COLORS["cyan"],
                activeforeground=BRAND_COLORS["dark"],
                relief="flat",
                bd=0,
                padx=18,
                font=("Microsoft YaHei UI", 10, "bold"),
                cursor="hand2",
            )
            button.pack(fill="x", padx=10, pady=3, ipady=8)
            self._control_editor_nav_widgets.append(button)
            if index == context.get("portrait_tab_index"):
                outfit_nav = tk.Frame(
                    self._control_sidebar_nav_content,
                    bg=BRAND_COLORS["bg"],
                )
                outfit_nav._portrait_outfit_nav = True
                context["outfit_nav_parent"] = outfit_nav
                self._control_outfit_nav_parent = outfit_nav
                self._control_outfit_nav_parents = getattr(
                    self,
                    "_control_outfit_nav_parents",
                    [],
                )
                self._control_outfit_nav_parents.append(outfit_nav)
                self._refresh_portrait_outfit_nav(context)

    def _refresh_control_editor_nav(self, notebook):
        context = getattr(self, "_control_edit_context", None)
        sidebar_context = getattr(self, "_control_sidebar_editor_context", None)
        if (
            context is None
            or context.get("editor_notebook") is not notebook
            or (sidebar_context is not None and sidebar_context is not context)
        ):
            # Hidden preloaded editors have their own Notebook and default tab.
            # Their events must never repaint the visible editor's sidebar.
            return
        try:
            selected = notebook.index(notebook.select())
        except (tk.TclError, ValueError):
            selected = 0
        for index, button in enumerate(self._control_editor_nav_widgets[1:]):
            active = index == selected
            button.configure(
                bg=BRAND_COLORS["cyan"] if active else BRAND_COLORS["bg_soft"],
                fg=BRAND_COLORS["dark"] if active else BRAND_COLORS["white"],
            )
        context = getattr(self, "_control_edit_context", None)
        if context is not None:
            outfit_nav = context.get("outfit_nav_parent")
            if outfit_nav is not None:
                portrait_index = context.get("portrait_tab_index")
                if selected == portrait_index:
                    next_button_index = portrait_index + 2
                    pack_options = {
                        "fill": "x",
                        "padx": (22, 8),
                        "pady": (0, 7),
                    }
                    if next_button_index < len(self._control_editor_nav_widgets):
                        pack_options["before"] = self._control_editor_nav_widgets[
                            next_button_index
                        ]
                    outfit_nav.pack(**pack_options)
                else:
                    outfit_nav.pack_forget()
            self._refresh_portrait_outfit_nav(context)

    def _refresh_portrait_outfit_nav(self, context):
        parent = context.get("outfit_nav_parent")
        if parent is None:
            return
        try:
            if not parent.winfo_exists():
                return
            for child in parent.winfo_children():
                child.destroy()
        except tk.TclError:
            return
        context["outfit_nav_buttons"] = {}
        outfits = (
            self._live2d_outfit_groups(context)
            if context.get("is_live2d")
            else context.get("portrait_outfits", [])
        )
        for outfit in outfits:
            outfit_id = outfit["id"]
            active = (
                any(item["id"] == context.get("active_outfit_id")
                    for item in outfit["appearances"])
                if context.get("is_live2d")
                else outfit_id == context.get("active_outfit_id")
            )
            button = tk.Button(
                parent,
                text=outfit["name"],
                anchor="w",
                command=lambda selected=outfit_id:
                (
                    self._select_live2d_outfit_group(context, selected)
                    if context.get("is_live2d")
                    else self._select_portrait_outfit(context, selected)
                ),
                bg=BRAND_COLORS["cyan"] if active else BRAND_COLORS["bg_soft"],
                fg=BRAND_COLORS["dark"] if active else BRAND_COLORS["white"],
                activebackground=BRAND_COLORS["cyan"],
                activeforeground=BRAND_COLORS["dark"],
                relief="flat",
                bd=0,
                padx=12,
                font=("Microsoft YaHei UI", 9),
                cursor="hand2",
            )
            button.pack(fill="x", pady=2, ipady=4)
            button.bind(
                "<Double-Button-1>",
                lambda event, selected=outfit_id:
                self._begin_rename_portrait_outfit(
                    context,
                    selected,
                    event.widget,
                ),
                add="+",
            )
            button.bind(
                "<Button-3>",
                lambda event, selected=outfit_id:
                self._show_portrait_outfit_menu(
                    context,
                    selected,
                    event,
                ),
            )
            context["outfit_nav_buttons"][outfit_id] = button
        add_button = tk.Button(
            parent,
            text=(
                "＋ 新增服装分组"
                if context.get("is_live2d")
                else "＋ 新增服装差分"
            ),
            anchor="w",
            command=lambda: (
                self._add_live2d_outfit_group(context)
                if context.get("is_live2d")
                else self._add_portrait_outfit_from_folder(context)
            ),
            bg=BRAND_COLORS["bg"],
            fg=BRAND_COLORS["cyan_soft"],
            activebackground=BRAND_COLORS["bg_soft"],
            activeforeground=BRAND_COLORS["white"],
            relief="flat",
            bd=0,
            padx=12,
            font=("Microsoft YaHei UI", 9),
            cursor="hand2",
        )
        add_button.pack(fill="x", pady=(4, 2), ipady=4)
        context["outfit_nav_add_button"] = add_button

    @staticmethod
    def _live2d_outfit_groups(context):
        groups = {}
        for appearance in context.get("portrait_outfits", []):
            outfit_id = str(appearance.get("outfit_id") or "default")
            group = groups.setdefault(outfit_id, {
                "id": outfit_id,
                "name": str(appearance.get("outfit_name") or "默认服装"),
                "appearances": [],
            })
            group["appearances"].append(appearance)
        return list(groups.values())

    def _select_live2d_outfit_group(self, context, outfit_id):
        group = next((item for item in self._live2d_outfit_groups(context)
                      if item["id"] == outfit_id), None)
        if group:
            active = context.get("active_outfit_id")
            selected = next((item["id"] for item in group["appearances"]
                             if item["id"] == active), group["appearances"][0]["id"])
            self._select_portrait_outfit(context, selected, force=True)

    def _add_live2d_outfit_group(self, context):
        groups = self._live2d_outfit_groups(context)
        name = simpledialog.askstring(
            "新增服装分组", "分组名称", parent=getattr(self, "_control_dialog", None))
        if not name or not name.strip():
            return
        name = name.strip()
        if any(item["name"].casefold() == name.casefold() for item in groups):
            messagebox.showerror("服装名称重复", "请使用一个尚未使用的服装名称。",
                                 parent=getattr(self, "_control_dialog", None))
            return
        outfit_id = self._live2d_appearance_id(name, [item["id"] for item in groups])
        self._add_live2d_appearance(context, outfit_id=outfit_id, outfit_name=name)

    def _new_live2d_appearance_draft(self, context, appearance):
        appearance = copy.deepcopy(appearance)
        master = context.get("editor_notebook")
        motion = appearance.get("motion", [])
        if not isinstance(motion, (list, tuple)):
            motion = []
        return {
            "appearance": appearance,
            "name_var": tk.StringVar(
                master=master,
                value=str(
                    appearance.get("name", "")
                    or appearance.get("label", "")
                    or "默认"
                ),
            ),
            "parameters_text": tk.StringVar(
                master=master,
                value=self._live2d_parameters_text(
                    appearance.get("parameters", {})
                ),
            ),
            "expression_var": tk.StringVar(
                master=master,
                value=str(appearance.get("expression", "") or ""),
            ),
            "motion_group_var": tk.StringVar(
                master=master,
                value=str(motion[0] if motion else ""),
            ),
            "motion_index_var": tk.StringVar(
                master=master,
                value=str(motion[1] if len(motion) > 1 else ""),
            ),
        }

    def _queue_live2d_thumbnail(
        self,
        context,
        label,
        *,
        appearance=None,
        expression=None,
        face=False,
        page="portrait",
    ):
        cache = context.setdefault("live2d_thumbnail_cache", {})
        target_size = (100, 78) if face else (140, 176)
        cache_key = json.dumps(
            [appearance, expression, face, target_size],
            sort_keys=True,
            ensure_ascii=False,
        )
        if cache_key in cache:
            label.configure(image=cache[cache_key], text="")
            label.image = cache[cache_key]
            return
        jobs = context.setdefault("live2d_thumbnail_jobs", [])
        for job in list(jobs) + list(
            context.get("live2d_thumbnail_pending", {}).values()
        ):
            if job[1] == cache_key and job[6] == page:
                if label not in job[0]:
                    job[0].append(label)
                return
        jobs.append((
            [label],
            cache_key,
            copy.deepcopy(appearance),
            expression,
            face,
            target_size,
            page,
        ))
        self._schedule_live2d_thumbnail_processing(context, 24)

    def _live2d_thumbnail_visible_pages(self, context):
        notebook = context.get("editor_notebook")
        if notebook is None:
            return set()
        try:
            selected = notebook.index(notebook.select())
        except (AttributeError, tk.TclError, ValueError):
            return set()
        pages = set()
        for page, tab in (
            ("portrait", context.get("portrait_tab")),
            ("settings", context.get("live2d_tab")),
        ):
            if tab is None:
                continue
            try:
                if tab.winfo_exists() and notebook.index(tab) == selected:
                    pages.add(page)
            except (tk.TclError, ValueError):
                continue
        return pages

    def _live2d_thumbnail_active_pages(self, context):
        pages = self._live2d_thumbnail_visible_pages(context)
        preload_pages = context.get("live2d_preload_pages", ())
        if isinstance(preload_pages, (set, list, tuple)):
            pages.update(preload_pages)
        return pages

    def _schedule_live2d_thumbnail_processing(self, context, delay=1):
        if (
            not self._control_editor_context_is_alive(context)
            or context.get("live2d_thumbnail_after") is not None
            or not context.get("live2d_thumbnail_jobs")
            or not self._live2d_thumbnail_active_pages(context)
        ):
            return
        try:
            context["live2d_thumbnail_after"] = self.root.after(
                delay, lambda: self._process_live2d_thumbnail(context))
        except (AttributeError, tk.TclError):
            context["live2d_thumbnail_after"] = None

    def _pause_live2d_thumbnail_processing(self, context):
        after_id = context.get("live2d_thumbnail_after")
        if after_id is None:
            return
        context["live2d_thumbnail_after"] = None
        try:
            self.root.after_cancel(after_id)
        except (AttributeError, tk.TclError):
            pass

    def _process_live2d_thumbnail(self, context):
        context["live2d_thumbnail_after"] = None
        if not self._control_editor_context_is_alive(context):
            return
        if context.get("live2d_thumbnail_pending"):
            return
        jobs = context.get("live2d_thumbnail_jobs", [])
        active_pages = self._live2d_thumbnail_active_pages(context)
        job_index = next(
            (
                index for index, job in enumerate(jobs)
                if job[6] in active_pages
            ),
            None,
        )
        if job_index is None:
            return
        job = jobs.pop(job_index)
        labels, cache_key, appearance, expression, face, target_size, page = job
        pending = context.setdefault("live2d_thumbnail_pending", {})
        pending[(cache_key, page)] = job
        def work():
            try:
                with context.setdefault("live2d_media_lock", threading.RLock()):
                    if context.get("disposed"):
                        return None, None
                    image = self._live2d_preview_image(
                        context,
                        appearance=appearance,
                        expression=expression,
                        face=face,
                        target_size=target_size,
                    )
                return image, None
            except Exception as error:
                return None, str(error)

        def complete(future):
            image, error = future.result()

            def apply():
                pending.pop((cache_key, page), None)
                if not self._control_editor_context_is_alive(context):
                    return
                photo = None
                for label in labels:
                    try:
                        if not label.winfo_exists():
                            continue
                        if image is not None:
                            if photo is None:
                                photo = ImageTk.PhotoImage(image, master=label)
                                context.setdefault("live2d_thumbnail_cache", {})[cache_key] = photo
                            label.configure(image=photo, text="")
                            label.image = photo
                        else:
                            label.configure(text="预览不可用")
                    except (RuntimeError, ValueError, tk.TclError):
                        continue
                if error:
                    context.setdefault("live2d_thumbnail_errors", []).append(error)
                self._update_live2d_settings_ready(context)
                self._schedule_live2d_thumbnail_processing(context, 12)
                self._advance_live2d_editor_preload(context)

            self._safe_root_after(0, apply)

        self._control_media_pool().submit(work).add_done_callback(complete)
        if not jobs:
            self._advance_live2d_editor_preload(context)

    def _rebuild_live2d_appearance_editor(self, context):
        host = context.get("live2d_appearance_content")
        if host is None:
            return
        self._cancel_live2d_viewport_update(context)
        try:
            if not host.winfo_exists():
                return
            for child in host.winfo_children():
                child.destroy()
        except tk.TclError:
            return
        context["live2d_pose_name_labels"] = {}
        groups = self._live2d_outfit_groups(context)
        group = next((item for item in groups
                      if any(pose["id"] == context.get("active_outfit_id")
                             for pose in item["appearances"])), groups[0] if groups else None)
        if group is None:
            return
        tk.Label(host, text=group["name"], bg=BRAND_COLORS["bg_soft"],
                 fg=BRAND_COLORS["white"], font=("Microsoft YaHei UI", 13, "bold"),
                 anchor="w").pack(fill="x", pady=(8, 12))
        pose_host = tk.Frame(host, bg=BRAND_COLORS["bg_soft"])
        pose_host.pack(fill="x")
        pose_widgets = []
        drafts = [draft for draft in context.get("live2d_appearance_drafts", [])
                  if str(draft["appearance"].get("outfit_id") or "default") == group["id"]]
        for index, draft in enumerate(drafts):
            appearance = draft.get("appearance", {})
            card = tk.Frame(
                pose_host, bg="#f5fbfe", width=170, height=240,
                highlightbackground="#bedbe7",
                highlightthickness=1,
            )
            card.grid_propagate(False)
            card.grid_columnconfigure(0, weight=1)
            card.grid_rowconfigure(0, weight=1)
            pose_widgets.append(card)
            picture = tk.Label(card, bg="#f5fbfe", text="加载中", fg=BRAND_COLORS["muted"],
                               cursor="hand2")
            picture.grid(row=0, column=0, sticky="nsew", padx=8, pady=8)
            try:
                parameters_value = self._parse_live2d_parameters(draft["parameters_text"])
            except ValueError:
                parameters_value = appearance.get("parameters", {})
            pose = {**appearance, "parameters": parameters_value}
            self._queue_live2d_thumbnail(context, picture, appearance=pose)
            picture.bind("<Button-1>", lambda _, key=appearance["id"]:
                         self._select_portrait_outfit(context, key))
            name = tk.Label(card, textvariable=draft["name_var"], bg="#f5fbfe",
                            fg=BRAND_COLORS["white"], font=("Microsoft YaHei UI", 9),
                            wraplength=150, cursor="hand2")
            name.grid(row=1, column=0, sticky="ew", padx=8, pady=(0, 6))
            context["live2d_pose_name_labels"][appearance["id"]] = name
            name.bind("<Button-1>", lambda _, key=appearance["id"]:
                      self._select_portrait_outfit(context, key))
            name.bind(
                "<Double-Button-1>",
                lambda event, key=appearance["id"]:
                self._begin_rename_live2d_pose(context, key),
                add="+",
            )
            actions = tk.Frame(card, bg="#f5fbfe")
            actions.grid(row=2, column=0, sticky="ew", padx=8, pady=(0, 8))
            applied = appearance["id"] == self._active_portrait_outfit_id(context["character_config"])
            tk.Label(actions, text="已应用" if applied else "", bg="#f5fbfe",
                     fg=BRAND_COLORS["cyan"]).pack(side="left")
            preview_button = self._brand_button(
                actions, "✓", lambda key=appearance["id"]: self._apply_live2d_appearance(context, key), width=2)
            preview_button.pack(side="right")
            self._add_tooltip(preview_button, "应用姿势")
            delete_button = self._brand_button(
                actions, "×", lambda key=appearance["id"]: self._delete_live2d_pose(context, key),
                width=2)
            delete_button.pack(side="right", padx=4)
            self._add_tooltip(delete_button, "删除姿势预设")

        def layout_poses(event=None):
            width = event.width if event is not None else pose_host.winfo_width()
            columns = max(1, min(4, width // 180))
            if context.get("live2d_pose_columns") == columns:
                return
            context["live2d_pose_columns"] = columns
            for index, widget in enumerate(pose_widgets):
                widget.grid(row=index // columns, column=index % columns, sticky="nw",
                            padx=(0, 10), pady=(0, 10))

        context["live2d_pose_columns"] = None
        context["live2d_pose_cards"] = pose_widgets
        pose_host.bind("<Configure>", layout_poses)
        layout_poses()
        self._brand_button(
            host, "＋ 手动添加姿势",
            lambda: self._review_existing_live2d_poses(context),
        ).pack(anchor="w", pady=(4, 12))
        selected_draft = next((draft for draft in drafts
                               if draft["appearance"]["id"] == context.get("active_outfit_id")), None)
        if selected_draft:
            viewport_band = tk.Frame(host, bg=BRAND_COLORS["bg_soft"])
            viewport_band.pack(fill="x", pady=(4, 12))
            tk.Label(viewport_band, text="局部模式", bg=BRAND_COLORS["bg_soft"],
                     fg=BRAND_COLORS["white"]).pack(side="left", anchor="n", padx=(0, 14))
            viewport_preview = tk.Label(
                viewport_band,
                bg="#f5fbfe",
                text="准备预览",
                fg=BRAND_COLORS["muted"],
            )
            viewport_preview.pack(side="left")
            context["live2d_viewport_preview"] = viewport_preview
            viewport_button = self._brand_button(
                viewport_band, "调整局部取景",
                lambda: self._open_portrait_viewport_editor(context))
            viewport_button.pack(side="left", padx=14)
            context["live2d_viewport_button"] = viewport_button
            self._schedule_live2d_viewport_preview(context)

        self._schedule_live2d_appearance_scrollregion(context)

    def _schedule_live2d_appearance_scrollregion(self, context):
        after_id = context.pop("live2d_appearance_scroll_after", None)
        if after_id is not None:
            try:
                self.root.after_cancel(after_id)
            except tk.TclError:
                pass

        def update_scrollregion():
            context["live2d_appearance_scroll_after"] = None
            if not self._control_editor_context_is_alive(context):
                return
            canvas = context.get("live2d_appearance_canvas")
            try:
                if canvas is not None and canvas.winfo_exists():
                    canvas.configure(scrollregion=canvas.bbox("all"))
            except tk.TclError:
                pass

        try:
            context["live2d_appearance_scroll_after"] = self.root.after(
                1, update_scrollregion)
        except tk.TclError:
            context["live2d_appearance_scroll_after"] = None

    def _cancel_live2d_viewport_update(self, context):
        after_id = context.pop("live2d_viewport_after", None)
        if after_id is None:
            return
        try:
            self.root.after_cancel(after_id)
        except tk.TclError:
            pass

    def _schedule_live2d_viewport_preview(self, context, delay=20):
        self._cancel_live2d_viewport_update(context)

        def render_preview():
            if not self._control_editor_context_is_alive(context):
                return
            context["live2d_viewport_after"] = None
            self._update_live2d_viewport_preview(context)

        try:
            context["live2d_viewport_after"] = self.root.after(delay, render_preview)
        except tk.TclError:
            context["live2d_viewport_after"] = None

    def _live2d_preview_image(
        self,
        context,
        *,
        appearance=None,
        expression=None,
        face=False,
        target_size=None,
    ):
        signature = json.dumps(
            [appearance, expression, face, target_size],
            sort_keys=True,
            ensure_ascii=False,
        )
        cache = context.setdefault("live2d_preview_images", {})
        if signature in cache:
            return cache[signature]
        shared_renderer = context.get("live2d_settings_renderer")
        if isinstance(shared_renderer, BackgroundLive2DRenderer) and not shared_renderer._failed:
            try:
                image = shared_renderer.shared_thumbnail(
                    appearance=appearance,
                    expression=expression,
                    face=face,
                    target_size=target_size,
                )
            except (OSError, RuntimeError, ValueError):
                image = None
            if image is not None:
                if len(cache) >= 32:
                    cache.pop(next(iter(cache)))
                cache[signature] = image
                return image
        renderer = context.get("live2d_thumbnail_renderer")
        if (renderer is None or renderer is shared_renderer
                or getattr(renderer, "_failed", False)):
            renderer = self._new_portrait_renderer(
                context["character_dir"], character_config=context["character_config"],
                outfit_id=context["active_outfit_id"], background=True)
            context["live2d_thumbnail_renderer"] = renderer
        if not isinstance(renderer, Live2DRenderer):
            raise RuntimeError("Live2D 取景渲染器不可用")
        image = renderer.preview_thumbnail(
            appearance=appearance,
            expression=expression,
            face=face,
            target_size=target_size,
        )
        # Bound native preview memory during long editing sessions.
        if len(cache) >= 32:
            cache.pop(next(iter(cache)))
        cache[signature] = image
        return image

    def _live2d_viewport_source(self, context):
        appearance = next(item for item in self._collect_live2d_appearances(context)
                          if item["id"] == context["active_outfit_id"])
        return self._live2d_preview_image(context, appearance=appearance)

    def _update_live2d_viewport_preview(self, context):
        after_id = context.pop("live2d_viewport_after", None)
        if after_id is not None:
            try:
                self.root.after_cancel(after_id)
            except tk.TclError:
                pass
        label = context.get("live2d_viewport_preview")
        if context.get("disposed") or label is None or not label.winfo_exists():
            return
        if context.get("live2d_viewport_pending"):
            context["live2d_viewport_dirty"] = True
            return
        # Read Tk draft values here; workers must only see plain data.
        appearance = copy.deepcopy(next(
            item for item in self._collect_live2d_appearances(context)
            if item["id"] == context["active_outfit_id"]
        ))
        viewport = copy.deepcopy(context.get("portrait_viewport_settings", {}))
        context["live2d_viewport_pending"] = True
        context["live2d_viewport_dirty"] = False
        def work():
            with context.setdefault("live2d_media_lock", threading.RLock()):
                if context.get("disposed"):
                    return None
                source = self._live2d_preview_image(context, appearance=appearance)
                image = crop_viewport(source, resolve_viewport(viewport, "idle"))
                image = ImageOps.contain(image, (164, 164), method=Image.Resampling.LANCZOS)
                background = Image.new("RGBA", (164, 164), "#f5fbfe")
                background.alpha_composite(
                    image, ((164 - image.width) // 2, (164 - image.height) // 2))
                return background

        def complete(future):
            try:
                image, error = future.result(), None
            except Exception as exception:
                image, error = None, str(exception)

            def apply():
                context["live2d_viewport_pending"] = False
                if not self._control_editor_context_is_alive(context):
                    return
                if context.pop("live2d_viewport_dirty", False):
                    self._update_live2d_viewport_preview(context)
                    return
                try:
                    if not label.winfo_exists():
                        return
                    if image is not None:
                        photo = ImageTk.PhotoImage(image, master=label)
                        label.configure(image=photo, text="")
                        label.image = photo
                    elif error:
                        label.configure(image="", text="预览不可用")
                        context["live2d_viewport_error"] = error
                except (RuntimeError, ValueError, tk.TclError):
                    pass
                self._advance_live2d_editor_preload(context)

            self._safe_root_after(0, apply)

        self._control_media_pool().submit(work).add_done_callback(complete)

    def _control_avatar_resources(self):
        resources = getattr(self, "_control_avatar_workers", None)
        if resources is None:
            resources = {
                "pool": ThreadPoolExecutor(
                    max_workers=2, thread_name_prefix="desktop-pet-avatars"),
                "lock": threading.RLock(),
                "futures": {},
            }
            self._control_avatar_workers = resources
        return resources

    def _control_avatar_future(self, path, max_size=(96, 96)):
        resources = self._control_avatar_resources()
        source = Path(path).resolve() if path else None
        try:
            stat = source.stat() if source else None
            version = (stat.st_mtime_ns, stat.st_size) if stat else None
        except OSError:
            version = None
        key = (str(source), version, tuple(max_size))

        def work():
            if source is None or Image is None:
                return None
            with Image.open(str(source)) as opened:
                image = opened.convert("RGBA")
            image.thumbnail(max_size, Image.Resampling.LANCZOS)
            return image

        with resources["lock"]:
            cached = resources["futures"]
            future = cached.get(key)
            if future is None:
                for old_key in list(cached):
                    if len(cached) < 64:
                        break
                    if cached[old_key].done():
                        del cached[old_key]
                future = resources["pool"].submit(work)
                cached[key] = future
            return future

    def _warm_control_avatars(self):
        resources = self._control_avatar_resources()

        def work():
            for character in list_characters():
                if getattr(self, "_quitting", False):
                    return
                path = self._character_avatar_path(
                    get_character_dir(character["id"]), character)
                if path:
                    self._control_avatar_future(path)

        resources["pool"].submit(work)

    def _load_control_avatar(self, path, label, max_size=(96, 96)):
        """Show warmed bitmaps immediately; cold decodes never queue behind Live2D."""
        request = object()
        label._control_avatar_request = request
        future = self._control_avatar_future(path, max_size)

        def apply(image):
            try:
                if (not label.winfo_exists()
                        or label._control_avatar_request is not request):
                    return
                if image is None:
                    label.configure(image="", text="缺失头像")
                else:
                    photo = ImageTk.PhotoImage(image, master=label)
                    label.configure(image=photo, text="")
                    label.image = photo
            except (RuntimeError, tk.TclError):
                pass

        def complete(future):
            try:
                image = future.result()
            except (OSError, ValueError, CancelledError):
                image = None
            self._safe_root_after(0, lambda: apply(image))

        if future.done():
            # This method runs on Tk's thread. A warm cache needs no later tick.
            try:
                image = future.result()
            except (OSError, ValueError, CancelledError):
                image = None
            apply(image)
        else:
            future.add_done_callback(complete)

    @staticmethod
    def _save_live2d_outfit_viewport(context, settings):
        active = next(item for item in context["portrait_outfits"]
                      if item["id"] == context["active_outfit_id"])
        outfit_id = str(active.get("outfit_id") or "default")
        for appearance in context["portrait_outfits"]:
            if str(appearance.get("outfit_id") or "default") == outfit_id:
                appearance["local_viewport"] = copy.deepcopy(settings)
        for draft in context.get("live2d_appearance_drafts", []):
            appearance = draft["appearance"]
            if str(appearance.get("outfit_id") or "default") == outfit_id:
                appearance["local_viewport"] = copy.deepcopy(settings)
        context["portrait_viewport_settings"] = copy.deepcopy(settings)
        context["portrait_outfits_changed"] = True

    def _preview_live2d_appearance(self, context, pose):
        renderer = context.get("live2d_settings_renderer")
        if renderer is not None:
            renderer.preview_pose(pose)

    def _persist_live2d_appearances(self, context, appearances, *, active_id=None):
        """Save only these poses, leaving unrelated editor drafts untouched."""
        character_id = context["character_id"]
        config = load_character_config(character_id)
        if not config or not isinstance(config.get("renderer"), dict):
            raise ValueError("角色配置不可用，未保存姿势。")
        stored = copy.deepcopy(config["renderer"].get("appearance_options", []))
        changes = {item["id"]: copy.deepcopy(item) for item in appearances}
        merged = [changes.pop(item["id"], item) for item in stored]
        merged.extend(changes.values())
        names = set()
        for item in merged:
            key = (item.get("outfit_id") or "default", item["name"].casefold())
            if key in names:
                raise ValueError("同一服装中已存在名为“{}”的姿势。".format(item["name"]))
            names.add(key)
        config["renderer"]["appearance_options"] = merged
        if active_id is not None:
            config.setdefault("portrait_rules", {})["active_appearance_id"] = active_id
        save_character_config(character_id, config)

        # Update just the committed fields, including the outer cancel snapshot.
        targets = [context["character_config"]]
        if character_id == self.character_id:
            targets.append(self.character_config)
        snapshot = getattr(self, "_control_snapshot", None)
        if snapshot and snapshot.get("character_id") == character_id:
            targets.append(snapshot["character_config"])
        for target in targets:
            options = target.setdefault("renderer", {}).setdefault("appearance_options", [])
            updates = {item["id"]: copy.deepcopy(item) for item in appearances}
            target["renderer"]["appearance_options"] = [
                updates.pop(item["id"], item) for item in options]
            target["renderer"]["appearance_options"].extend(updates.values())
            if active_id is not None:
                target.setdefault("portrait_rules", {})["active_appearance_id"] = active_id
        renderers = [context.get("live2d_settings_renderer")]
        if character_id == self.character_id:
            renderers.append(getattr(self, "renderer", None))
        for renderer in renderers:
            if isinstance(renderer, Live2DRenderer):
                renderer._renderer_config["appearance_options"] = copy.deepcopy(merged)

    def _apply_live2d_appearance(self, context, pose_id):
        try:
            draft = next(item for item in context["live2d_appearance_drafts"]
                         if item["appearance"]["id"] == pose_id)
            pose = self._collect_live2d_appearances(
                {**context, "live2d_appearance_drafts": [draft]})[0]
            self._persist_live2d_appearances(context, [pose], active_id=pose_id)
            renderers = [context.get("live2d_settings_renderer")]
            if context["character_id"] == self.character_id:
                renderers.append(getattr(self, "renderer", None))
            seen = set()
            for renderer in renderers:
                if renderer is None or id(renderer) in seen:
                    continue
                seen.add(id(renderer))
                renderer.end_preview()
                renderer.set_appearance(pose)
                renderer.viewport_settings = copy.deepcopy(
                    pose.get("local_viewport") or
                    context["character_config"].get("portrait_rules", {}).get("local_viewport", {}))
            if context["character_id"] == self.character_id:
                self._render_state()
            self._rebuild_live2d_appearance_editor(context)
            self._control_status.set("已应用并保存姿势：{}".format(pose["name"]))
        except (OSError, ValueError, RuntimeError, tk.TclError) as error:
            messagebox.showerror("应用姿势失败", str(error),
                                 parent=getattr(self, "_control_dialog", None))

    def _set_live2d_pose_name(self, context, pose_id, name):
        """校验并保存姿势名称，供界面内编辑和测试共用。"""
        name = str(name or "").strip()
        if not name:
            messagebox.showerror(
                "名称不能为空",
                "请输入姿势名称。",
                parent=getattr(self, "_control_dialog", None),
            )
            return False
        draft = next(
            (
                item for item in context.get("live2d_appearance_drafts", [])
                if item.get("appearance", {}).get("id") == pose_id
            ),
            None,
        )
        if draft is None:
            return False
        appearance = draft["appearance"]
        outfit_id = str(appearance.get("outfit_id") or "default")
        duplicate = any(
            item.get("appearance", {}).get("id") != pose_id
            and str(item.get("appearance", {}).get("outfit_id") or "default") == outfit_id
            and str(item.get("name_var").get()).strip().casefold() == name.casefold()
            for item in context.get("live2d_appearance_drafts", [])
        )
        if duplicate:
            messagebox.showerror(
                "姿势名称重复",
                "同一服装下不能有同名姿势。",
                parent=getattr(self, "_control_dialog", None),
            )
            return False
        draft["name_var"].set(name)
        appearance["name"] = name
        for item in context.get("portrait_outfits", []):
            if item.get("id") == pose_id:
                item["name"] = name
        context["portrait_outfits_changed"] = True
        if hasattr(self, "_control_status"):
            self._control_status.set("已重命名姿势“{}”".format(name))
        return True

    def _begin_rename_live2d_pose(self, context, pose_id):
        draft = next(
            (
                item for item in context.get("live2d_appearance_drafts", [])
                if item.get("appearance", {}).get("id") == pose_id
            ),
            None,
        )
        if draft is None:
            return "break"
        label = context.get("live2d_pose_name_labels", {}).get(pose_id)
        if label is None:
            return "break"
        active_editor = context.get("live2d_pose_rename_editor")
        try:
            if active_editor is not None and active_editor.winfo_exists():
                active_editor.focus_set()
                return "break"
            if not label.winfo_exists():
                return "break"
        except tk.TclError:
            return "break"

        editor = tk.Entry(
            label.master,
            relief="flat",
            bd=0,
            bg="#f5fbfe",
            fg=BRAND_COLORS["dark"],
            insertbackground=BRAND_COLORS["dark"],
            font=("Microsoft YaHei UI", 9),
        )
        editor.insert(
            0,
            str(draft["name_var"].get() or draft["appearance"].get("name") or ""),
        )
        try:
            label.grid_remove()
            editor.grid(row=1, column=0, sticky="ew", padx=8, pady=(0, 6))
        except tk.TclError:
            editor.destroy()
            return "break"
        editor.focus_set()
        editor.selection_range(0, tk.END)
        context["live2d_pose_rename_editor"] = editor
        finished = {"value": False}

        def finish(commit):
            if finished["value"]:
                return
            if commit:
                if not self._set_live2d_pose_name(context, pose_id, editor.get()):
                    editor.focus_set()
                    return
            finished["value"] = True
            try:
                editor.destroy()
                label.grid()
            except tk.TclError:
                pass
            if context.get("live2d_pose_rename_editor") is editor:
                context.pop("live2d_pose_rename_editor", None)

        editor.bind("<Return>", lambda _event: finish(True))
        editor.bind("<Escape>", lambda _event: finish(False))
        editor.bind("<FocusOut>", lambda _event: finish(True), add="+")
        return "break"

    def _delete_live2d_pose(self, context, pose_id):
        outfits = context.get("portrait_outfits", [])
        if len(outfits) <= 1:
            return
        if not messagebox.askyesno("删除姿势", "删除此姿势预设？模型文件不会修改。",
                                   parent=getattr(self, "_control_dialog", None)):
            return
        outfits[:] = [item for item in outfits if item["id"] != pose_id]
        context["live2d_appearance_drafts"] = [
            draft for draft in context["live2d_appearance_drafts"]
            if draft["appearance"]["id"] != pose_id]
        if context.get("active_outfit_id") == pose_id:
            context["active_outfit_id"] = outfits[0]["id"]
            context["portrait_viewport_settings"] = copy.deepcopy(
                outfits[0].get("local_viewport") or context["character_config"].get(
                    "portrait_rules", {}).get("local_viewport", {}))
        context["portrait_outfits_changed"] = True
        self._end_live2d_preview()
        self._refresh_portrait_outfit_nav(context)
        self._rebuild_live2d_appearance_editor(context)

    def _add_live2d_appearance(self, context, outfit_id=None, outfit_name=None):
        drafts = context.setdefault("live2d_appearance_drafts", [])
        existing_ids = [
            draft.get("appearance", {}).get("id")
            for draft in drafts
        ]
        number = len(drafts) + 1
        name = "姿势 {}".format(number)
        names = {str(draft["name_var"].get()).casefold() for draft in drafts}
        while name.casefold() in names:
            number += 1
            name = "姿势 {}".format(number)
        group = next((group for group in self._live2d_outfit_groups(context)
                      if any(item["id"] == context.get("active_outfit_id")
                             for item in group["appearances"])), None)
        appearance_id = self._live2d_appearance_id(name, existing_ids)
        appearance = {
            "id": appearance_id,
            "name": name,
            "parameters": {},
            "outfit_id": outfit_id or (group["id"] if group else "default"),
            "outfit_name": outfit_name or (group["name"] if group else "默认服装"),
        }
        if group and appearance["outfit_id"] == group["id"]:
            viewport = group["appearances"][0].get("local_viewport")
            if isinstance(viewport, dict):
                appearance["local_viewport"] = copy.deepcopy(viewport)
        drafts.append(self._new_live2d_appearance_draft(context, appearance))
        context.setdefault("portrait_outfits", []).append(copy.deepcopy(appearance))
        context["portrait_outfits_changed"] = True
        self._refresh_portrait_outfit_nav(context)
        self._select_portrait_outfit(context, appearance_id, force=True)
        if hasattr(self, "_control_status"):
            self._control_status.set(
                "已新增当前模型姿势预设“{}”；如需真实新姿势，请先更新模型资源".format(name)
            )

    def _add_portrait_outfit_from_folder(self, context):
        lazy = context.get("portrait_manager_lazy", {})
        if not lazy.get("initialized"):
            notebook = context.get("editor_notebook")
            if notebook is not None:
                try:
                    notebook.select(context.get("portrait_tab_index", 1))
                    notebook.after(
                        80,
                        lambda: self._add_portrait_outfit_from_folder(context),
                    )
                except tk.TclError:
                    pass
            return
        parent = getattr(self, "_control_dialog", None) or self.root
        selected = filedialog.askdirectory(
            title="选择包含“待机.png”的服装立绘文件夹",
            parent=parent,
        )
        if not selected:
            return

        entries, _skipped = self._scan_portrait_outfit_folder(selected)
        full_entries = [
            entry
            for entry in entries
            if entry.get("assets", {}).get("full") is not None
        ]
        idle_entry = next(
            (
                entry
                for entry in full_entries
                if (
                    self._portrait_batch_supported_state_key(
                        entry.get("label", "")
                    )
                    == "idle"
                    or self._normalize_portrait_state_key(
                        entry.get("label", "")
                    )
                    == "idle"
                )
            ),
            None,
        )
        if idle_entry is None:
            messagebox.showerror(
                "缺少待机立绘",
                "所选文件夹中没有识别到待机立绘。请放入文件名为“待机”的图片，"
                "例如“待机.png”，然后重试。",
                parent=parent,
            )
            return

        outfits = context.get("portrait_outfits", [])
        previous_outfit_id = context.get("active_outfit_id", "default")
        existing_ids = {item["id"] for item in outfits}
        sequence = 2
        while "outfit_{}".format(sequence) in existing_ids:
            sequence += 1
        folder_name = Path(selected).name.strip() or "服装 {}".format(sequence)
        base_name = folder_name
        name_index = 2
        existing_names = {
            item["name"].casefold()
            for item in outfits
        }
        while folder_name.casefold() in existing_names:
            folder_name = "{} ({})".format(base_name, name_index)
            name_index += 1

        outfit = {
            "id": "outfit_{}".format(sequence),
            "name": folder_name,
            "folder_name": folder_name,
            "portrait_assets": {},
            "local_viewport": {
                "default": dict(DEFAULT_VIEWPORT),
                "states": {},
            },
            "source_folder": str(Path(selected).resolve()),
        }
        outfits.append(outfit)
        context["portrait_outfits_changed"] = True

        rows_by_label = {}
        rows_by_key = {}
        for row in context.get("portrait_state_rows", []):
            label_key = self._portrait_emotion_name_key(row["label"].get())
            state_key = self._normalize_portrait_state_key(row["key"].get())
            if label_key:
                rows_by_label[label_key] = row
            if state_key:
                rows_by_key[state_key] = row

        imported = []
        imported_rows = []
        for entry in full_entries:
            label = str(entry.get("label", "")).strip()
            source_row = rows_by_label.get(
                self._portrait_emotion_name_key(label)
            )
            if source_row is None:
                source_row = rows_by_key.get(
                    self._normalize_portrait_state_key(label)
                )
            if source_row is None:
                continue
            source = Path(entry["assets"]["full"])
            imported_rows.append(
                self._clone_portrait_state_row_for_outfit(
                    source_row,
                    source,
                )
            )
            imported.append(source.name)

        context["portrait_outfit_rows"][outfit["id"]] = imported_rows
        context["portrait_outfit_initial_assets"][outfit["id"]] = {}
        context["active_outfit_id"] = previous_outfit_id
        self._refresh_portrait_outfit_nav(context)
        if hasattr(self, "_control_status"):
            self._control_status.set(
                "已新增服装“{}”，载入 {} 张立绘；点击“保存”写入".format(
                    outfit["name"],
                    len(imported),
                )
            )

    def _clone_portrait_state_row_for_outfit(self, source_row, source):
        """为新服装建立独立草稿行，避免和当前服装共享 Tk 变量。"""
        values = {
            "key": source_row["key"].get(),
            "label": source_row["label"].get(),
            "keywords": source_row["keywords"].get(),
        }

        def make_variable(value, template):
            try:
                variable_root = getattr(template, "_root", None)
                if variable_root is not None:
                    return tk.StringVar(
                        master=variable_root,
                        value=value,
                    )
                return tk.StringVar(value=value)
            except (RuntimeError, tk.TclError):
                value_box = {"value": str(value)}
                return SimpleNamespace(
                    get=lambda: value_box["value"],
                    set=lambda updated: value_box.__setitem__(
                        "value",
                        str(updated),
                    ),
                )

        return {
            "key": make_variable(values["key"], source_row["key"]),
            "label": make_variable(values["label"], source_row["label"]),
            "keywords": make_variable(
                values["keywords"],
                source_row["keywords"],
            ),
            "category": source_row.get("category", "custom"),
            "usage_scenario": source_row.get("usage_scenario", ""),
            "initial_key": None,
            "initial_assets": {},
            "assets": {"full": source, "small": None},
            "portrait_assets": {},
            "pending": {"full": source, "small": None},
            "manager_hidden": False,
            "frame": None,
        }

    def _show_portrait_outfit_menu(self, context, outfit_id, event):
        menu = tk.Menu(self._control_sidebar, tearoff=False)

        def rename_outfit():
            button = context.get("outfit_nav_buttons", {}).get(outfit_id)
            try:
                menu.unpost()
            except tk.TclError:
                pass
            parent = context.get("outfit_nav_parent")
            if parent is None:
                return

            def begin_rename():
                try:
                    if not parent.winfo_exists():
                        return
                    current_button = context.get(
                        "outfit_nav_buttons", {}
                    ).get(outfit_id)
                    if current_button is None or not current_button.winfo_exists():
                        return
                except tk.TclError:
                    return
                self._begin_rename_portrait_outfit(
                    context,
                    outfit_id,
                    current_button or button,
                )

            try:
                parent.after(30, begin_rename)
            except tk.TclError:
                pass

        menu.add_command(
            label="重命名",
            command=rename_outfit,
        )
        menu.add_command(
            label="删除服装",
            command=lambda: self._delete_portrait_outfit(context, outfit_id),
            state=(
                tk.NORMAL
                if (
                    (
                        True
                        if context.get("is_live2d")
                        else outfit_id != "default"
                    )
                    and len(
                        self._live2d_outfit_groups(context) if context.get("is_live2d")
                        else context.get("portrait_outfits", [])
                    ) > 1
                )
                else tk.DISABLED
            ),
        )
        menu.tk_popup(event.x_root, event.y_root)

    def _begin_rename_portrait_outfit(self, context, outfit_id, button=None):
        outfit = next(
            (
                item
                for item in (
                    self._live2d_outfit_groups(context) if context.get("is_live2d")
                    else context.get("portrait_outfits", [])
                )
                if item["id"] == outfit_id
            ),
            None,
        )
        parent = context.get("outfit_nav_parent")
        if outfit is None or parent is None:
            return
        active_editor = context.get("outfit_rename_editor")
        try:
            if active_editor is not None and active_editor.winfo_exists():
                active_editor.focus_set()
                return
            if not parent.winfo_exists():
                return
        except tk.TclError:
            return
        if button is None:
            button = context.get("outfit_nav_buttons", {}).get(outfit_id)
        try:
            if button is None or not button.winfo_exists():
                return
            siblings = list(parent.pack_slaves())
            button_index = siblings.index(button)
            next_sibling = next(
                (
                    sibling
                    for sibling in siblings[button_index + 1 :]
                    if sibling is not button
                ),
                None,
            )
        except (ValueError, tk.TclError):
            return
        editor = tk.Entry(
            parent,
            relief="flat",
            bd=0,
            bg=BRAND_COLORS["panel"],
            fg=BRAND_COLORS["white"],
            insertbackground=BRAND_COLORS["white"],
            font=("Microsoft YaHei UI", 9),
        )
        editor.insert(0, outfit["name"])
        try:
            editor.pack(
                fill="x",
                pady=2,
                ipady=4,
                before=button,
            )
            button.pack_forget()
        except tk.TclError:
            editor.destroy()
            return
        editor.focus_set()
        editor.selection_range(0, tk.END)
        context["outfit_rename_editor"] = editor
        finished = {"value": False}

        def finish(commit):
            if finished["value"]:
                return
            finished["value"] = True
            new_name = editor.get().strip()
            if commit and new_name:
                duplicate = any(
                    item["id"] != outfit_id
                    and item["name"].casefold() == new_name.casefold()
                    for item in (
                        self._live2d_outfit_groups(context) if context.get("is_live2d")
                        else context.get("portrait_outfits", [])
                    )
                )
                if duplicate:
                    messagebox.showerror(
                        "服装名称重复",
                        "请使用一个尚未使用的服装名称。",
                        parent=getattr(self, "_control_dialog", None),
                    )
                    finished["value"] = False
                    editor.focus_set()
                    return
                if not context.get("is_live2d"):
                    try:
                        new_name = self._validate_portrait_outfit_folder_name(
                            new_name
                        )
                    except ValueError as error:
                        messagebox.showerror(
                            "服装名称无效",
                            str(error),
                            parent=getattr(self, "_control_dialog", None),
                        )
                        finished["value"] = False
                        editor.focus_set()
                        return
                outfit["name"] = new_name
                outfit["folder_name"] = new_name
                if context.get("is_live2d"):
                    for appearance in context.get("portrait_outfits", []):
                        if str(appearance.get("outfit_id") or "default") == outfit_id:
                            appearance.update(outfit_id=outfit_id, outfit_name=new_name)
                    for draft in context.get("live2d_appearance_drafts", []):
                        if str(draft["appearance"].get("outfit_id") or "default") == outfit_id:
                            draft["appearance"].update(outfit_id=outfit_id, outfit_name=new_name)
                context["portrait_outfits_changed"] = True
            try:
                editor.destroy()
            except tk.TclError:
                pass
            if commit and context.get("is_live2d"):
                self._rebuild_live2d_appearance_editor(context)
            if context.get("outfit_rename_editor") is editor:
                context.pop("outfit_rename_editor", None)
            try:
                if button.winfo_exists():
                    button.configure(text=outfit["name"])
                    pack_options = {
                        "fill": "x",
                        "pady": 2,
                        "ipady": 4,
                    }
                    if next_sibling is not None and next_sibling.winfo_exists():
                        pack_options["before"] = next_sibling
                    button.pack(**pack_options)
            except tk.TclError:
                pass

        editor.bind("<Return>", lambda _event: finish(True))
        editor.bind("<Escape>", lambda _event: finish(False))

    def _delete_portrait_outfit(self, context, outfit_id):
        if context.get("is_live2d"):
            groups = self._live2d_outfit_groups(context)
            group = next((item for item in groups if item["id"] == outfit_id), None)
            if len(groups) <= 1 or group is None:
                return
            if not messagebox.askyesno(
                "删除服装", "删除“{}”及其姿势预设？模型文件不会修改。".format(group["name"]),
                parent=getattr(self, "_control_dialog", None),
            ):
                return
            removed = {item["id"] for item in group["appearances"]}
            context["portrait_outfits"][:] = [
                item for item in context["portrait_outfits"] if item["id"] not in removed]
            context["live2d_appearance_drafts"] = [
                draft for draft in context["live2d_appearance_drafts"]
                if draft["appearance"]["id"] not in removed]
            if context["active_outfit_id"] in removed:
                context["active_outfit_id"] = context["portrait_outfits"][0]["id"]
            context["portrait_outfits_changed"] = True
            self._end_live2d_preview()
            self._refresh_portrait_outfit_nav(context)
            self._rebuild_live2d_appearance_editor(context)
            return
        outfits = context.get("portrait_outfits", [])
        if (
            len(outfits) <= 1
            or (outfit_id == "default" and not context.get("is_live2d"))
        ):
            return
        outfit = next(
            (item for item in outfits if item["id"] == outfit_id),
            None,
        )
        if outfit is None:
            return
        if not messagebox.askyesno(
            "删除服装",
            "删除“{}”的服装记录？角色目录中已保存的图片文件会保留。".format(
                outfit["name"]
            ),
            parent=getattr(self, "_control_dialog", None),
        ):
            return
        if context.get("active_outfit_id") == outfit_id:
            replacement = next(
                item["id"] for item in outfits if item["id"] != outfit_id
            )
            self._select_portrait_outfit(
                context,
                replacement,
                force=True,
            )
        outfits[:] = [item for item in outfits if item["id"] != outfit_id]
        if context.get("is_live2d"):
            context["live2d_appearance_drafts"] = [
                draft
                for draft in context.get("live2d_appearance_drafts", [])
                if draft.get("appearance", {}).get("id") != outfit_id
            ]
            self._rebuild_live2d_appearance_editor(context)
        context["portrait_outfits_changed"] = True
        rows_by_outfit = context.get("portrait_outfit_rows", {})
        rows_by_outfit.pop(outfit_id, None)
        initial_by_outfit = context.get("portrait_outfit_initial_assets", {})
        initial_by_outfit.pop(outfit_id, None)
        self._refresh_portrait_outfit_nav(context)

    def _select_portrait_outfit(self, context, outfit_id, force=False):
        if context.get("is_live2d"):
            if (
                outfit_id == context.get("active_outfit_id")
                and not force
            ):
                return
            if not any(
                item.get("id") == outfit_id
                for item in context.get("portrait_outfits", [])
            ):
                return
            context["active_outfit_id"] = outfit_id
            selected = next(item for item in context["portrait_outfits"]
                            if item["id"] == outfit_id)
            context["portrait_viewport_settings"] = copy.deepcopy(
                selected.get("local_viewport") or context["character_config"].get(
                    "portrait_rules", {}).get("local_viewport", {}))
            context["portrait_outfits_changed"] = True
            self._end_live2d_preview()
            self._refresh_portrait_outfit_nav(context)
            self._rebuild_live2d_appearance_editor(context)
            return
        lazy = context.get("portrait_manager_lazy", {})
        if not lazy.get("initialized"):
            notebook = context.get("editor_notebook")
            if notebook is not None:
                try:
                    notebook.select(context.get("portrait_tab_index", 1))
                    notebook.after(
                        80,
                        lambda: self._select_portrait_outfit(
                            context,
                            outfit_id,
                            force=force,
                        ),
                    )
                except tk.TclError:
                    pass
            return
        if (
            outfit_id == context.get("active_outfit_id")
            and not force
        ):
            return
        outfits = context.get("portrait_outfits", [])
        selected = next(
            (item for item in outfits if item["id"] == outfit_id),
            None,
        )
        if selected is None:
            return
        current_id = context.get("active_outfit_id")
        current = next((item for item in outfits if item["id"] == current_id), None)
        if current is not None:
            current["local_viewport"] = copy.deepcopy(
                context.get("portrait_viewport_settings", {})
            )
        self._stash_portrait_action_rows(context)
        manager = context.get("portrait_manager", {})
        cards = manager.get("cards")
        for callback_key in ("preview_after_id", "render_after_id"):
            callback_id = manager.get(callback_key)
            if cards is not None and callback_id is not None:
                try:
                    cards.after_cancel(callback_id)
                except tk.TclError:
                    pass
            manager[callback_key] = None
        if cards is not None:
            for child in cards.winfo_children():
                child.destroy()
        for row in manager.get("rendered_rows", []):
            row["frame"] = None
            row["manager_widgets"] = {}
        manager["rendered_rows"] = []
        manager["render_queue"] = []
        for item in manager.get("preview_queue", []):
            item[4].cancel()
        manager["preview_queue"] = []
        manager["image_cache"] = {}
        manager["render_generation"] = manager.get("render_generation", 0) + 1
        context["active_outfit_id"] = outfit_id
        choices = self._portrait_action_choices(
            selected, context.get("portrait_outfit_rows", {}).get(outfit_id))
        active_action_id = selected.get("active_action_id", "")
        if not any(item["id"] == active_action_id for item in choices):
            active_action_id = choices[0]["id"]
        selected["active_action_id"] = context["active_action_id"] = active_action_id
        self._load_portrait_action_rows(context, selected)
        self._reconcile_portrait_outfit_rows(context, selected)
        context["portrait_viewport_settings"] = copy.deepcopy(
            selected.get("local_viewport")
            or {
                "default": DEFAULT_VIEWPORT,
                "states": {},
            }
        )
        self._refresh_portrait_outfit_nav(context)
        self._refresh_portrait_manager(context)
        self._refresh_portrait_action_controls(context)
        self._refresh_control_editor_nav(
            context.get("editor_notebook")
        ) if context.get("editor_notebook") is not None else None

    def _reconcile_portrait_outfit_rows(self, context, outfit):
        definitions = self._configured_state_definitions(
            context["character_config"],
            outfit_id=outfit["id"],
            outfits=context.get("portrait_outfits"),
            action_id=context.get("active_action_id", ""),
        )
        action = self._portrait_action(outfit, context.get("active_action_id", ""))
        if context.get("active_action_id") or outfit.get("actions") or outfit.get("portrait_assets"):
            for state, definition in definitions.items():
                definition["portrait_assets"] = copy.deepcopy(
                    action.get("portrait_assets", {}).get(state, {}))
        removed_states = context.get("removed_portrait_states", set())
        if context.get("active_action_id"):
            removed_states = context.get("portrait_action_removed_states", {}).get(
                (outfit["id"], context["active_action_id"]), set())
            definitions = {key: value for key, value in definitions.items()
                           if key not in removed_states}
        rows = context.setdefault("portrait_state_rows", [])
        for draft_row in rows:
            state = self._normalize_portrait_state_key(
                draft_row["key"].get()
            )
            if (
                not state
                or state in definitions
                or state in removed_states
                or draft_row.get("initial_key") is not None
            ):
                continue
            definitions[state] = {
                "label": str(draft_row["label"].get()).strip() or state,
                "keywords": self._split_state_keywords(
                    draft_row["keywords"].get()
                ),
                "enabled": True,
                "portrait_assets": {},
                "category": draft_row.get("category", "custom"),
                "usage_scenario": draft_row.get("usage_scenario", ""),
            }
        valid_keys = set(definitions)
        rows[:] = [
            row
            for row in rows
            if (
                self._normalize_portrait_state_key(row["key"].get())
                in valid_keys
            )
        ]
        current_keys = {
            self._normalize_portrait_state_key(row["key"].get())
            for row in rows
        }
        character_dir = Path(context["character_dir"])
        initial_assets = {}
        initial_assets.clear()
        for state, definition in definitions.items():
            assets = {
                mode: self._portrait_mode_asset_path(
                    state,
                    mode,
                    character_dir,
                    definition=definition,
                    outfit_id=("__action__" if context.get("active_action_id") else outfit["id"]),
                )
                for mode in ("full", "small")
            }
            if state not in current_keys:
                row = self._append_portrait_manager_state(
                    context,
                    state,
                    definition,
                    initial_assets=assets,
                )
                row["manager_hidden"] = self._portrait_manager_should_hide_state(
                    definition,
                    assets,
                )
                current_keys.add(state)
            initial_assets[state] = assets
        for row in rows:
            state = self._normalize_portrait_state_key(row["key"].get())
            definition = definitions.get(state, {})
            row.setdefault("initial_key", state)
            row.setdefault("initial_assets", initial_assets.get(state, {}))
            row.setdefault("assets", dict(initial_assets.get(state, {})))
            row.setdefault("portrait_assets", copy.deepcopy(
                definition.get("portrait_assets", {})
            ))
            row.setdefault("pending", {"full": None, "small": None})
        rows.sort(key=self._portrait_state_row_sort_key)
        context["portrait_initial_assets"] = initial_assets
        self._stash_portrait_action_rows(context)
        context["portrait_initial_state_keys"] = set(definitions)

    def _stash_portrait_action_rows(self, context):
        outfit_id = context.get("active_outfit_id", "default")
        action_id = context.get("active_action_id", "")
        if action_id:
            context.setdefault("portrait_action_rows", {})[(outfit_id, action_id)] = context.get(
                "portrait_state_rows", [])
            context.setdefault("portrait_action_initial_assets", {})[
                (outfit_id, action_id)] = context.get("portrait_initial_assets", {})
        else:
            context.setdefault("portrait_outfit_rows", {})[outfit_id] = context.get(
                "portrait_state_rows", [])
            context.setdefault("portrait_outfit_initial_assets", {})[outfit_id] = context.get(
                "portrait_initial_assets", {})

    def _load_portrait_action_rows(self, context, outfit):
        action_id = context.get("active_action_id", "")
        context["portrait_state_rows"] = (
            context.setdefault("portrait_action_rows", {}).get((outfit["id"], action_id), [])
            if action_id else context.setdefault("portrait_outfit_rows", {}).get(outfit["id"], [])
        )

    def _select_portrait_action(self, context, action_id):
        self._stash_portrait_action_rows(context)
        outfit = next(item for item in context["portrait_outfits"]
                      if item["id"] == context["active_outfit_id"])
        outfit["active_action_id"] = action_id
        self._select_portrait_outfit(context, outfit["id"], force=True)
        context["portrait_outfits_changed"] = True

    def _refresh_portrait_action_controls(self, context):
        combo = context.get("portrait_action_combo")
        if combo is None:
            return
        outfit = next(item for item in context["portrait_outfits"]
                      if item["id"] == context["active_outfit_id"])
        default_rows = context.get("portrait_outfit_rows", {}).get(outfit["id"])
        if not context.get("active_action_id"):
            default_rows = context.get("portrait_state_rows", default_rows)
        choices = self._portrait_action_choices(outfit, default_rows)
        if not any(item["id"] == context.get("active_action_id", "") for item in choices):
            self._select_portrait_action(context, choices[0]["id"])
            return
        context["portrait_action_choices"] = choices
        combo.configure(values=[item["name"] for item in choices])
        combo.current(next((index for index, item in enumerate(choices)
                            if item["id"] == context.get("active_action_id", "")), 0))
        more_menu = context.get("portrait_manager", {}).get("more_menu")
        if more_menu is not None:
            more_menu.entryconfigure(
                "删除当前动作",
                state=tk.NORMAL if context.get("active_action_id") else tk.DISABLED,
            )

    def _prompt_portrait_action_name(self, title, initialvalue=""):
        parent = getattr(self, "_control_dialog", None) or self.root
        dialog = tk.Toplevel(parent)
        dialog.withdraw()
        self._brand_window(dialog, title)
        dialog.transient(parent)
        dialog.resizable(False, False)
        body = tk.Frame(dialog, bg=BRAND_COLORS["bg"])
        body.pack(fill="both", expand=True, padx=20, pady=16)
        tk.Label(
            body, text="动作名称", bg=BRAND_COLORS["bg"],
            fg=BRAND_COLORS["white"], font=("Microsoft YaHei UI", 10),
        ).pack(anchor="w", pady=(0, 8))
        name_var = tk.StringVar(master=dialog, value=initialvalue)
        entry = ttk.Entry(body, textvariable=name_var, style="Brand.TEntry", width=28)
        entry.pack(fill="x")
        error_label = tk.Label(
            body, text="", bg=BRAND_COLORS["bg"], fg=BRAND_COLORS["muted"],
            font=("Microsoft YaHei UI", 9), anchor="w",
        )
        error_label.pack(fill="x", pady=(4, 8))
        result = {"name": None}

        def accept(_event=None):
            name = name_var.get().strip()
            try:
                name = self._validate_portrait_outfit_folder_name(name)
            except ValueError as error:
                error_label.configure(
                    text=str(error).replace("服装名称", "动作名称"), wraplength=280,
                )
                return
            result["name"] = name
            dialog.destroy()

        buttons = tk.Frame(body, bg=BRAND_COLORS["bg"])
        buttons.pack(fill="x")
        self._brand_button(buttons, "确定", accept, accent=True).pack(side="right")
        self._brand_button(buttons, "取消", dialog.destroy).pack(side="right", padx=(0, 8))
        dialog.bind("<Return>", accept)
        dialog.bind("<Escape>", lambda _event: dialog.destroy())
        self._center_toplevel(dialog, parent)
        dialog.deiconify()
        entry.focus_set()
        entry.selection_range(0, "end")
        dialog.grab_set()
        dialog.wait_window()
        return result["name"]

    def _add_portrait_action(self, context, import_folder=False):
        parent = getattr(self, "_control_dialog", None) or self.root
        folder = filedialog.askdirectory(title="选择动作立绘文件夹", parent=parent) if import_folder else ""
        if import_folder and not folder:
            return
        name = Path(folder).name if folder else self._prompt_portrait_action_name("新增动作")
        if not name:
            return
        outfit = next(item for item in context["portrait_outfits"]
                      if item["id"] == context["active_outfit_id"])
        try:
            name = self._validate_portrait_outfit_folder_name(name)
            if any(item["name"].casefold() == name.casefold() for item in
                   self._portrait_action_choices(outfit)):
                raise ValueError("动作名称已存在。")
            entries = self._scan_portrait_outfit_folder(folder)[0] if folder else []
            if folder and not entries:
                raise ValueError("动作文件夹中没有可用的立绘图片。")
        except (OSError, ValueError) as error:
            messagebox.showerror(
                "新增动作失败", str(error).replace("服装名称", "动作名称"), parent=parent,
            )
            return
        action_id = "action_" + uuid.uuid4().hex[:10]
        outfit.setdefault("actions", []).append({
            "id": action_id, "name": name, "folder_name": name, "portrait_assets": {}})
        self._select_portrait_action(context, action_id)
        for entry in entries:
            state = self._portrait_batch_supported_state_key(entry["label"])
            if not state:
                state = "emotion_" + uuid.uuid4().hex[:10]
            row = next((item for item in context["portrait_state_rows"]
                        if item["key"].get() == state), None)
            if row is None:
                row = self._append_portrait_manager_state(context, state, {
                    "label": entry["label"], "keywords": [],
                    "category": "special" if state == "idle" else "custom"})
            row["assets"]["full"] = entry["assets"]["full"]
            row["pending"]["full"] = entry["assets"]["full"]
            row["manager_hidden"] = False
        self._refresh_portrait_manager(context)

    def _rename_portrait_action(self, context):
        outfit = next(item for item in context["portrait_outfits"]
                      if item["id"] == context["active_outfit_id"])
        action_id = context.get("active_action_id", "")
        action = self._portrait_action(outfit, action_id)
        parent = getattr(self, "_control_dialog", None) or self.root
        name = self._prompt_portrait_action_name("重命名动作", initialvalue=action["name"])
        if not name:
            return
        try:
            name = self._validate_portrait_outfit_folder_name(name)
            if any(item["id"] != action_id and item["name"].casefold() == name.casefold()
                   for item in self._portrait_action_choices(outfit)):
                raise ValueError("动作名称已存在。")
        except ValueError as error:
            messagebox.showerror(
                "重命名失败", str(error).replace("服装名称", "动作名称"), parent=parent,
            )
            return
        if action_id:
            action.update(name=name, folder_name=name)
        else:
            outfit["default_action_name"] = name
        context["portrait_outfits_changed"] = True
        self._refresh_portrait_action_controls(context)

    def _delete_portrait_action(self, context):
        action_id = context.get("active_action_id", "")
        if not action_id:
            return
        outfit = next(item for item in context["portrait_outfits"]
                      if item["id"] == context["active_outfit_id"])
        if not messagebox.askyesno("删除动作", "删除当前动作记录？已保存的图片会保留。",
                                  parent=getattr(self, "_control_dialog", None)):
            return
        self._stash_portrait_action_rows(context)
        outfit["actions"] = [item for item in outfit["actions"] if item["id"] != action_id]
        choices = self._portrait_action_choices(
            outfit, context.get("portrait_outfit_rows", {}).get(outfit["id"]))
        self._select_portrait_action(context, choices[0]["id"])
        context.get("portrait_action_rows", {}).pop((outfit["id"], action_id), None)
        context.get("portrait_action_initial_assets", {}).pop((outfit["id"], action_id), None)
        self._refresh_portrait_action_controls(context)

    @staticmethod
    def _portrait_state_row_sort_key(row):
        state = DesktopPetApp._normalize_portrait_state_key(
            row["key"].get()
        )
        idle_label = DesktopPetApp._portrait_emotion_name_key(
            STATE_LABELS["idle"]
        )
        label = DesktopPetApp._portrait_emotion_name_key(
            row["label"].get()
        )
        return 0 if state == "idle" or label == idle_label else 1

    def _on_control_editor_tab_changed(self, notebook, context):
        sidebar_context = getattr(self, "_control_sidebar_editor_context", None)
        if (
            context is None
            or context is not getattr(self, "_control_edit_context", None)
            or context.get("editor_notebook") is not notebook
            or (sidebar_context is not None and sidebar_context is not context)
        ):
            return
        try:
            selected_index = notebook.index(notebook.select())
        except (tk.TclError, ValueError):
            selected_index = -1
        if (
            context.get("is_live2d")
            and not self._control_editor_tab_ready(context, selected_index)
        ):
            self._control_pending_editor_tab = selected_index
            self._refresh_control_editor_nav(notebook)
            preload = context.get("live2d_editor_preload")
            if not (
                isinstance(preload, dict)
                and preload.get("status") == "building"
            ):
                self._ensure_control_editor_preload(context)
            return
        if selected_index >= 0:
            self._control_pending_editor_tab = None
            context["control_last_ready_editor_tab"] = selected_index
        self._refresh_control_editor_nav(notebook)
        lazy_tabs = context.get("editor_lazy_tabs", {})
        for key, state in lazy_tabs.items():
            tab = state.get("tab")
            try:
                is_selected = (
                    tab is not None
                    and tab.winfo_exists()
                    and notebook.index(tab) == selected_index
                )
            except (tk.TclError, ValueError):
                is_selected = False
            if not is_selected or state.get("initialized"):
                continue
            hold_key = "editor_{}_tick_hold".format(key)
            if context.get("is_live2d") and key == "portrait":
                self._hold_live2d_tick_for_control_build(context, hold_key)
            try:
                self._ensure_control_editor_tab(context, key)
            except (OSError, RuntimeError, TypeError, ValueError, tk.TclError) as error:
                if tab is not None and tab.winfo_exists():
                    tk.Label(
                        tab,
                        text="页面加载失败：{}".format(error),
                        bg=BRAND_COLORS["bg_soft"],
                        fg=BRAND_COLORS["pink"],
                        anchor="w",
                    ).pack(fill="x", padx=16, pady=16)
                if hasattr(self, "_control_status"):
                    self._control_status.set(
                        "{}加载失败：{}".format(state.get("title", "页面"), error)
                    )
            finally:
                if context.get("is_live2d") and key == "portrait":
                    self._release_live2d_tick_after_control_build(
                        context,
                        hold_key,
                    )
            break
        if context.get("is_live2d"):
            self._end_live2d_preview()
            live2d_tab = context.get("live2d_tab")
            try:
                live2d_selected = (
                    live2d_tab is not None
                    and live2d_tab.winfo_exists()
                    and notebook.index(live2d_tab) == selected_index
                )
            except (tk.TclError, ValueError):
                live2d_selected = False
            if live2d_selected:
                self._schedule_live2d_settings_refresh(
                    context,
                    force=False,
                )
            elif not (
                "settings" in context.get("live2d_preload_pages", ())
                or context.get("live2d_settings_prepare_pending")
                or context.get("live2d_settings_building")
            ):
                self._cancel_live2d_settings_refresh(context)
                self._release_live2d_tick_after_control_build(
                    context,
                    "live2d_settings_tick_hold",
                )
        tab_work = context.setdefault(
            "editor_tab_work",
            {"after_id": None, "generation": 0},
        )
        tab_work["generation"] += 1
        generation = tab_work["generation"]
        after_id = tab_work.get("after_id")
        if after_id is not None:
            try:
                notebook.after_cancel(after_id)
            except tk.TclError:
                pass
            tab_work["after_id"] = None

        def apply_tab_work():
            if generation != tab_work.get("generation"):
                return
            tab_work["after_id"] = None
            if (
                not self._control_editor_context_is_alive(context)
                or not notebook.winfo_exists()
            ):
                return
            if context.get("is_live2d"):
                return
            if self._portrait_manager_is_visible(context):
                lazy = context.get("portrait_manager_lazy", {})
                if lazy.get("initialized"):
                    self._resume_portrait_manager_render(context)
                    self._load_portrait_manager_previews(context)
                else:
                    self._ensure_control_portrait_manager(context)
            else:
                self._pause_portrait_manager_work(context)

        try:
            tab_work["after_id"] = notebook.after_idle(apply_tab_work)
        except tk.TclError:
            tab_work["after_id"] = None

    def _portrait_manager_is_visible(self, context):
        notebook = context.get("editor_notebook")
        if (
            not self._control_editor_context_is_alive(context)
            or getattr(self, "_control_current_page", None) != "character_edit"
            or notebook is None
        ):
            return False
        try:
            return notebook.index(notebook.select()) == context.get(
                "portrait_tab_index",
                1,
            )
        except (tk.TclError, ValueError):
            return False

    def _pause_portrait_manager_work(self, context):
        lazy = context.get("portrait_manager_lazy", {})
        pending_build = lazy.get("after_id")
        if pending_build is not None:
            try:
                lazy.get("parent").after_cancel(pending_build)
            except (tk.TclError, AttributeError):
                pass
            lazy["after_id"] = None
        manager = context.get("portrait_manager", {})
        cards = manager.get("cards")
        if cards is None:
            return
        for key in ("render_after_id", "preview_after_id"):
            after_id = manager.get(key)
            if after_id is None:
                continue
            try:
                cards.after_cancel(after_id)
            except tk.TclError:
                pass
            manager[key] = None
        for item in manager.get("preview_queue", []):
            item[4].cancel()
        manager["preview_queue"] = []

    def _ensure_control_portrait_manager(self, context):
        lazy = context.get("portrait_manager_lazy", {})
        if (
            not lazy
            or lazy.get("initialized")
            or lazy.get("after_id") is not None
        ):
            return
        notebook = context.get("editor_notebook")
        if notebook is None:
            return

        def build_manager():
            lazy["after_id"] = None
            if (
                not self._control_editor_context_is_alive(context)
                or not notebook.winfo_exists()
            ):
                return
            if not self._portrait_manager_is_visible(context):
                return
            placeholder = lazy.get("placeholder")
            if placeholder is not None:
                try:
                    placeholder.destroy()
                except tk.TclError:
                    pass
            lazy["initialized"] = True
            self._add_portrait_states_manager(
                lazy["parent"],
                lazy["row"],
                context,
            )

        try:
            lazy["after_id"] = notebook.after(35, build_manager)
        except tk.TclError:
            lazy["after_id"] = None

    def _control_band(self, parent, title, subtitle="", bottom_gap=0):
        # 标题带独立占据一行，标题和说明始终落在同一块视觉层级中。
        # 这样历史记录、对话信息、任务等面板标题会和“模型类别”保持一致。
        frame = tk.Frame(
            parent,
            bg=BRAND_COLORS["bg_soft"],
            height=54 + max(0, int(bottom_gap)),
        )
        frame.pack(fill="x")
        frame.pack_propagate(False)
        canvas = tk.Canvas(
            frame,
            bg=BRAND_COLORS["bg_soft"],
            bd=0,
            highlightthickness=0,
        )
        canvas.pack(fill="both", expand=True)
        canvas.create_polygon(
            0, 15, 252, 15, 270, 54, 0, 54,
            fill=BRAND_COLORS["panel_soft"], outline=""
        )
        canvas.create_polygon(
            236, 15, 270, 15, 254, 54, 222, 54,
            fill=BRAND_COLORS["pink"], outline=""
        )
        canvas.create_text(
            13, 27, text=title, anchor="w",
            fill=BRAND_COLORS["white"],
            font=("Microsoft YaHei UI", 11, "bold"),
        )
        if subtitle:
            canvas.create_text(
                13, 37, text=subtitle, anchor="nw", width=205,
                fill=BRAND_COLORS["muted"],
                font=("Microsoft YaHei UI", 8),
            )

