    def _commit_companionship_interval(self, variable, persist=True):
        companionship = self.app_config.setdefault(
            "autonomous_conversation",
            {"enabled": False, "interval_minutes": 60},
        )
        try:
            fallback = max(
                1,
                min(1440, int(companionship.get("interval_minutes", 60))),
            )
        except (TypeError, ValueError):
            fallback = 60
        try:
            minutes = int(float(str(variable.get()).strip()))
        except (TypeError, ValueError):
            minutes = fallback
        minutes = max(1, min(1440, minutes))
        variable.set(str(minutes))
        companionship["interval_minutes"] = minutes
        companionship.setdefault("enabled", False)
        if persist:
            save_app_config(self.app_config)
            self._configure_companionship()
            if hasattr(self, "_control_status"):
                self._control_status.set("自主对话间隔已保存")
        try:
            self._control_dialog.focus_set()
        except (AttributeError, tk.TclError):
            pass
        return "break"
    def _control_image(self, path, max_size=(240, 300)):
        path = Path(path)
        if not path.is_file():
            return None
        try:
            if Image is not None and ImageTk is not None:
                with Image.open(str(path)) as opened:
                    image = opened.convert("RGBA")
                image.thumbnail(max_size, Image.Resampling.LANCZOS)
                photo = ImageTk.PhotoImage(image)
                self._control_images.append(photo)
                return photo
            image = tk.PhotoImage(file=str(path))
            factor = max(
                1,
                image.width() // max_size[0],
                image.height() // max_size[1],
            )
            if factor > 1:
                image = image.subsample(factor, factor)
            self._control_images.append(image)
            return image
        except (OSError, ValueError, tk.TclError):
            return None

    @staticmethod
    def _character_avatar_path(character_dir, character_config):
        relative_path = str(
            character_config.get("card_avatar", "") or ""
        ).strip()
        if not relative_path:
            return None
        path = Path(relative_path)
        if path.is_absolute():
            return None
        root = Path(character_dir).resolve()
        avatar_path = (root / path).resolve()
        try:
            avatar_path.relative_to(root)
        except ValueError:
            return None
        return avatar_path if avatar_path.is_file() else None

    @staticmethod
    def _commit_character_avatar(context, character_config):
        if not context.get("card_avatar_changed"):
            return
        source = Path(context.get("card_avatar_source", ""))
        if not source.is_file() or source.suffix.lower() not in IMAGE_EXTENSIONS:
            raise ValueError("请选择有效的头像图片文件。")
        character_dir = Path(context["character_dir"])
        avatar_dir = character_dir / "ui"
        if (character_dir / "signature.ed25519").exists():
            raise ValueError("签名角色包的头像资源不能直接替换，请由制作者更新并重新签名。")
        avatar_dir.mkdir(parents=True, exist_ok=True)
        destination = avatar_dir / ("avatar" + source.suffix.lower())
        if source.resolve() != destination.resolve():
            shutil.copy2(str(source), str(destination))
        character_config["card_avatar"] = destination.relative_to(
            character_dir
        ).as_posix()

    def _character_manager_items(self):
        return list_characters()

