    def _add_language_reference_fields(self, content, voice_config, context):
        tk.Label(
            content,
            text="参考音频",
            bg=BRAND_COLORS["bg_soft"],
            fg=BRAND_COLORS["white"],
            anchor="w",
            font=("Microsoft YaHei UI", 16, "bold"),
        ).grid(row=0, column=0, columnspan=3, sticky="ew", padx=12, pady=(12, 2))
        references = voice_config.setdefault("language_references", {})
        row = 1
        language_labels = {
            "zh": ("中文参考音频", "中文参考文本"),
            "ja": ("日文参考音频", "日文参考文本"),
        }
        for language in ("zh", "ja"):
            item = references.setdefault(language, {})
            if not isinstance(item, dict):
                item = {}
                references[language] = item
            audio = str(item.get("audio", "")).strip()
            text = str(item.get("text", "")).strip()
            audio_var = tk.StringVar(value=audio)
            text_var = tk.StringVar(value=text)
            audio_label, text_label = language_labels[language]
            tk.Label(
                content,
                text=audio_label,
                anchor="w",
                bg=BRAND_COLORS["bg_soft"],
                fg=BRAND_COLORS["cyan_soft"],
                font=("Microsoft YaHei UI", 13, "bold"),
            ).grid(row=row, column=0, columnspan=3, sticky="ew", padx=12, pady=(14, 4))
            row += 1
            self._add_upload_field(
                content,
                row,
                audio_var,
                ("上传{}文件".format(audio_label), "支持：wav、mp3、flac、ogg"),
                initial=audio,
                resource_key="language_reference_audio_{}".format(language),
                context=context,
                surface_color=BRAND_COLORS["panel"],
            )
            resource = (
                "上传{}文件".format(audio_label),
                "支持：wav、mp3、flac、ogg",
            )
            context["config_vars"].append(
                (
                    "voice",
                    "language_references.{}".format(language),
                    "audio",
                    audio,
                    audio_var,
                    False,
                    resource,
                )
            )
            context["config_field_vars"][
                ("voice", "language_references.{}".format(language), "audio")
            ] = audio_var
            row += 1
            tk.Label(
                content,
                text=text_label,
                anchor="w",
                bg=BRAND_COLORS["bg_soft"],
                fg=BRAND_COLORS["white"],
            ).grid(row=row, column=0, sticky="w", padx=20, pady=(4, 2))
            text_entry = tk.Entry(
                content,
                textvariable=text_var,
                bg=BRAND_COLORS["panel"],
                fg=BRAND_COLORS["white"],
                insertbackground=BRAND_COLORS["white"],
                relief="flat",
            )
            text_entry.grid(row=row, column=1, columnspan=2, sticky="ew", padx=(8, 20), pady=(4, 8))
            context["config_vars"].append(
                (
                    "voice",
                    "language_references.{}".format(language),
                    "text",
                    text,
                    text_var,
                    False,
                    None,
                )
            )
            context["config_field_vars"][
                ("voice", "language_references.{}".format(language), "text")
            ] = text_var
            row += 1
        content.grid_columnconfigure(1, weight=1)
        self._add_emotion_audio_section(
            content,
            row + 1,
            voice_config,
            context,
        )

