    def _enable_character_from_manager(self, character_id):
        if not (get_character_dir(character_id) / "character.json").exists():
            return
        self._pending_character_id = character_id
        self._sync_control_character_cards()

    def _sync_control_character_cards(self):
        for current_id, button in getattr(self, "_character_card_buttons", []):
            try:
                enabled = current_id == self.character_id
                pending = current_id == getattr(self, "_pending_character_id", self.character_id)
                button.configure(
                    text="当前使用" if enabled else "保存后使用" if pending else "使用角色",
                    state="disabled" if enabled or pending else "normal",
                    bg=BRAND_COLORS["panel_soft"] if enabled else BRAND_COLORS["cyan"],
                    disabledforeground=BRAND_COLORS["dark"],
                )
                card = getattr(button, "_character_card", None)
                if card is not None:
                    card.configure(highlightbackground=BRAND_COLORS["cyan"] if enabled else BRAND_COLORS["line"],
                                   highlightthickness=2 if enabled else 1)
            except tk.TclError:
                continue

    def _delete_character(self, character_id):
        if character_id == self.character_id:
            messagebox.showinfo("无法删除", "当前正在使用的角色不能删除，请先切换到其他角色。")
            return
        character_dir = get_character_dir(character_id)
        if not character_dir.is_dir():
            return
        try:
            if character_dir.resolve().parent != CHARACTERS_DIR.resolve():
                return
        except OSError:
            return
        character_config = load_character_config(character_id)
        display_name = character_config.get("display_name", character_id)
        confirmed = messagebox.askyesno(
            "删除角色",
            "确定删除角色“{}”及其项目内运行副本吗？此操作不可撤销。".format(display_name),
            parent=getattr(self, "_config_dialog", self.root),
        )
        if not confirmed:
            return
        try:
            shutil.rmtree(str(character_dir))
        except OSError as error:
            messagebox.showerror("删除失败", "无法删除角色目录：{}".format(error))
            return
        if getattr(self, "_pending_character_id", self.character_id) == character_id:
            self._pending_character_id = self.character_id
        self._refresh_character_manager_tab()
        if hasattr(self, "status_label"):
            self.status_label.configure(text="已删除角色：{}".format(display_name))

    def _find_character_window_portrait(self, character_id):
        character_dir = get_character_dir(character_id)
        full_portrait_directories = (
            character_dir / "portraits" / "outfits" / "default",
        )
        for full_portraits in full_portrait_directories:
            for idle_name in ("待机.png",):
                idle_path = full_portraits / idle_name
                if idle_path.is_file():
                    return idle_path
            for path in sorted(full_portraits.glob("*")):
                if path.is_file() and path.suffix.lower() in IMAGE_EXTENSIONS:
                    return path
        return None

    def show_create_character_dialog(self):
        self._show_inline_character_create()

    def _create_character_from_dialog(self, dialog, display_name, character_id, personality, full_folder, window_folder, ckpt, pth, reference, audio_folder):
        created_id = self._create_character_from_form(
            character_id, display_name, personality, full_folder, window_folder,
            ckpt, pth, reference, "", audio_folder
        )
        if created_id:
            dialog.destroy()
            self._refresh_character_manager_tab()

    @staticmethod
    def _file_spec(kind):
        specs = {
            "图片文件": ("上传图片", "支持：png、gif、ppm、jpg、jpeg"),
            "模型文件": ("上传模型文件", "支持：ckpt、pth、bin"),
            "音频文件": ("上传参考音频", "支持：wav、mp3、flac、ogg"),
            "立绘文件夹": ("上传立绘文件夹", "文件夹内可放 png、gif、ppm、jpg、jpeg"),
            "音频文件夹": ("上传参考音频文件夹", "文件夹内可放 wav、mp3、flac、ogg"),
        }
        return specs[kind]

    def _add_upload_field(
        self,
        parent,
        row,
        variable,
        spec,
        folder=False,
        callback=None,
        initial="",
        resource_key="",
        context=None,
        surface_color=None,
    ):
        title, hint = spec[:2]
        folder = spec[2] if len(spec) > 2 else folder
        initial = str(initial or "").strip()
        has_initial = bool(initial)
        surface_color = surface_color or BRAND_COLORS["panel"]
        character_dir = context.get("character_dir") if context else self.character_dir
        if resource_key == "full_portrait_folder":
            view_title = "查看角色立绘"
            add_title = "添加立绘"
            view_hint = "已有角色立绘"
        elif resource_key == "window_portrait_folder":
            view_title = "查看窗口立绘"
            add_title = "添加窗口立绘"
            view_hint = "打开当前窗口立绘文件夹"
        elif resource_key == "reference_audio_folder":
            view_title = "查看参考音频"
            add_title = "添加参考音频"
            view_hint = "打开当前参考音频文件夹"
        elif str(resource_key).startswith("language_reference_audio_"):
            language = str(resource_key).rsplit("_", 1)[-1]
            label = OUTPUT_LANGUAGE_NAMES.get(language, "当前语言")
            view_title = "查看{}参考音频".format(label)
            add_title = "更换{}参考音频".format(label)
            view_hint = "当前{}参考音频".format(label)
        else:
            view_title = "当前文件"
            add_title = {
                "ckpt_file": "更换 GPT 模型文件",
                "pth_file": "更换 SoVITS 模型文件",
                "default_audio": "更换语音文件",
            }.get(resource_key, "更换文件")
            view_hint = "当前文件"
        frame_height = 88 if has_initial else 62
        upload = tk.Frame(
            parent,
            bg=surface_color,
            relief="flat",
            bd=0,
            highlightbackground=BRAND_COLORS["line"],
            highlightthickness=1,
            height=frame_height,
            cursor="hand2",
        )
        upload.grid(row=row, column=1, columnspan=2, sticky="ew", padx=(10, 10), pady=5)
        upload.grid_propagate(False)
        upload.grid_columnconfigure(0, weight=1)
        action_frame = tk.Frame(upload, bg=surface_color)
        action_frame.grid(row=0, column=1, rowspan=2, padx=(6, 8), pady=5)
        label = tk.Label(
            upload,
            text=(view_hint if has_initial else title),
            bg=surface_color,
            fg=BRAND_COLORS["white"],
            cursor="hand2",
        )
        label.grid(row=0, column=0, sticky="ew", pady=(7, 0))
        path_label = tk.Label(
            upload,
            text=(
                "当前文件：{}".format(Path(initial).name)
                if has_initial and not folder
                else (Path(initial).name if has_initial else hint)
            ),
            bg=surface_color,
            fg=BRAND_COLORS["muted"],
            cursor="hand2",
        )
        path_label.grid(row=1, column=0, sticky="ew", pady=(0, 6))
        state = {
            "has_initial": has_initial,
            "add_title": add_title,
        }

        def resolve_initial_path():
            source_path = Path(str(variable.get()).strip() or initial)
            if source_path.is_absolute():
                return source_path
            candidates = (
                character_dir / "portraits" / source_path,
                character_dir / "voice" / source_path,
                character_dir / source_path,
                ROOT / source_path,
            )
            return next(
                (candidate for candidate in candidates if candidate.exists()),
                source_path,
            )

        def view_existing():
            existing_path = resolve_initial_path()
            if not existing_path.exists():
                messagebox.showinfo("资源不存在", "当前资源路径不存在：{}".format(existing_path))
                return
            location = existing_path if existing_path.is_dir() else existing_path.parent
            try:
                os.startfile(str(location))
            except OSError as error:
                messagebox.showerror("打开资源失败", "无法打开资源位置：{}".format(error))

        def choose(selected_title=title):
            if callback:
                callback(variable)
                return
            if resource_key in ("full_portrait_folder", "window_portrait_folder"):
                selected = self._browse_portrait_source(selected_title)
            else:
                selected = filedialog.askdirectory(title=selected_title) if folder else filedialog.askopenfilename(
                    title=selected_title,
                    filetypes=[(hint, self._file_pattern(hint)), ("所有文件", "*.*")],
                )
            if selected:
                variable.set(selected)
                if not state["has_initial"]:
                    state["has_initial"] = True
                    upload.configure(height=88)
                    label.configure(text=view_hint)
                    if resource_key == "full_portrait_folder":
                        state["add_title"] = "更换立绘"
                    for widget in (upload, label, path_label):
                        widget.unbind("<Button-1>")
                path_label.configure(
                    text=Path(selected).name
                    if folder
                    else "当前文件：{}".format(Path(selected).name)
                )
                render_actions()

        def render_actions():
            for child in action_frame.winfo_children():
                child.destroy()
            if not state["has_initial"]:
                return
            self._brand_button(
                action_frame,
                view_title,
                view_existing,
            ).pack(fill="x", pady=(0, 3))
            self._brand_button(
                action_frame,
                state["add_title"],
                lambda: choose(state["add_title"]),
                accent=True,
            ).pack(fill="x")

        if state["has_initial"]:
            render_actions()
        else:
            for widget in (upload, label, path_label):
                widget.bind("<Button-1>", lambda event: choose())
        return upload

    @staticmethod
    def _file_pattern(hint):
        if "png" in hint:
            return "*.png *.gif *.ppm *.jpg *.jpeg"
        if any(token in hint.lower() for token in ("ckpt", "pth", "bin")):
            return "*.ckpt *.pth *.bin"
        return "*.wav *.mp3 *.flac *.ogg"

    def _browse_character_file(self, variable, file_kind):
        spec = self._file_spec(file_kind)
        selected = filedialog.askdirectory(title=spec[0]) if "文件夹" in file_kind else filedialog.askopenfilename(
            title=spec[0], filetypes=[(spec[1], self._file_pattern(spec[1])), ("所有文件", "*.*")]
        )
        if selected:
            variable.set(selected)

    def _browse_portrait_source(self, title):
        return filedialog.askdirectory(title=title)

    def _create_character_from_form(
        self, character_id, display_name, personality, full_portrait,
        small_portrait, ckpt_file, pth_file, reference_audio,
        portrait_folder, reference_audio_folder, derive_small_from_full=True,
        require_idle_portrait=False, normalize_emotion_names=False,
        card_avatar_source="", switch_after_create=True, character_mode="static",
        live2d_model=""
    ):
        if not display_name.strip():
            messagebox.showerror("创建失败", "请填写角色名称。")
            return ""
        if require_idle_portrait:
            portrait_dir = Path(str(full_portrait or "").strip())
            if not portrait_dir.is_dir():
                messagebox.showerror("创建失败", "请选择有效的角色立绘文件夹。")
                return ""
            if not any(
                item.is_file()
                and item.suffix.lower() in IMAGE_EXTENSIONS
                and item.stem == "待机"
                for item in portrait_dir.rglob("*")
            ):
                messagebox.showerror(
                    "创建失败",
                    "角色立绘文件夹中必须包含一张文件名为“待机”的图片。",
                )
                return ""
        character_id = generate_character_id(display_name)
        try:
            if character_mode == "live2d":
                scan = validate_model(live2d_model).get("mapping_scan", {})
                preview = format_mapping_preview(scan)
                preview += (
                    "\n\n命名规则："
                    "\n表情：高兴.exp3.json、害羞.exp3.json、伤心.exp3.json"
                    "\n动作：待机.motion3.json、问候.motion3.json、特殊.motion3.json"
                )
                confirmed = messagebox.askyesno(
                    "确认 Live2D 映射",
                    preview + "\n\n是否按当前识别结果创建角色？",
                    parent=getattr(self, "_control_dialog", self.root),
                )
                if not confirmed:
                    return ""
                create_live2d_character(
                    character_id,
                    display_name,
                    personality,
                    live2d_model,
                    card_avatar=card_avatar_source,
                )
            else:
                create_character(
                    character_id, display_name, personality, full_portrait,
                    small_portrait, ckpt_file, pth_file, reference_audio,
                    portrait_folder, reference_audio_folder,
                    derive_small_from_full=derive_small_from_full,
                    require_idle_portrait=require_idle_portrait,
                    normalize_emotion_names=normalize_emotion_names,
                    card_avatar=card_avatar_source,
                )
        except FileExistsError:
            messagebox.showerror("创建失败", "这个角色 ID 已经存在。")
            return ""
        except ValueError as error:
            messagebox.showerror("创建失败", str(error))
            return ""
        except OSError as error:
            messagebox.showerror("创建失败", "无法创建角色目录：{}".format(error))
            return ""
        if switch_after_create:
            self.switch_character(character_id)
            success_message = "角色“{}”已创建并切换。".format(
                display_name or character_id
            )
        else:
            success_message = "角色“{}”已创建。".format(
                display_name or character_id
            )
        messagebox.showinfo("创建成功", success_message)
        return character_id

    def _add_config_tab(
        self,
        notebook,
        title,
        sections,
        only_keys=None,
        json_sections=False,
        upload_keys=None,
        config_vars=None,
        config_field_vars=None,
        context=None,
        tab=None,
    ):
        config_vars = self._config_vars if config_vars is None else config_vars
        config_field_vars = (
            self._config_field_vars if config_field_vars is None else config_field_vars
        )
        if tab is None:
            tab = tk.Frame(notebook, bg=BRAND_COLORS["bg_soft"])
            notebook.add(tab, text=title)
        tab.grid_rowconfigure(0, weight=1)
        tab.grid_columnconfigure(0, weight=1)
        canvas = tk.Canvas(
            tab,
            bd=0,
            highlightthickness=0,
            bg=BRAND_COLORS["bg_soft"],
        )
        scrollbar = _BrandScrollbar(
            tab,
            orient="vertical",
            command=canvas.yview,
            style="Brand.Vertical.TScrollbar",
        )
        content = tk.Frame(canvas, bg=BRAND_COLORS["bg_soft"])
        window_id = canvas.create_window((0, 0), window=content, anchor="nw")
        canvas.configure(yscrollcommand=scrollbar.set)
        canvas.grid(row=0, column=0, sticky="nsew")
        if title == "基础资料":
            tab.grid_columnconfigure(
                1,
                minsize=max(1, int(scrollbar.winfo_reqwidth())),
            )
        row = 0
        for section_title, values, target, prefix in sections:
            if target == "language_parameter_editor":
                row = self._add_language_parameter_editor(
                    content,
                    row,
                    section_title,
                    values,
                    config_vars,
                    config_field_vars,
                    target="voice",
                )
                continue
            tk.Label(
                content,
                text=section_title,
                anchor="w",
                bg=BRAND_COLORS["bg_soft"],
                fg=BRAND_COLORS["cyan_soft"],
                font=(
                    ("Microsoft YaHei UI", 13, "bold")
                    if section_title in {"角色信息", "本地 GPT-SoVITS 模型"}
                    else ("Microsoft YaHei UI", 10, "bold")
                ),
            ).grid(
                row=row, column=0, columnspan=2, sticky="ew", padx=12, pady=(12, 4)
            )
            row += 1
            for key, value in values.items():
                if only_keys is not None and key not in only_keys:
                    continue
                variable = tk.StringVar(value=self._config_value_text(value, json_sections))
                config_field_vars[(target, prefix, key)] = variable
                resource = upload_keys.get(key) if upload_keys else None
                if resource:
                    self._add_upload_field(
                        content,
                        row,
                        variable,
                        resource,
                        initial=value,
                        resource_key=key,
                        context=context,
                        surface_color=BRAND_COLORS["panel"],
                    )
                    config_vars.append((target, prefix, key, value, variable, json_sections, resource))
                    row += 1
                    continue
                tk.Label(
                    content,
                    text=self._field_label(key),
                    anchor="w",
                    bg=BRAND_COLORS["bg_soft"],
                    fg=BRAND_COLORS["white"],
                ).grid(
                    row=row, column=0, sticky="nw" if key == "user_address" else "w", padx=20, pady=4
                )
                if target == "character" and key == "display_name":
                    name_avatar_row = tk.Frame(
                        content,
                        bg=BRAND_COLORS["bg_soft"],
                    )
                    name_avatar_row.grid(
                        row=row,
                        column=1,
                        sticky="ew",
                        padx=(8, 20),
                        pady=4,
                    )
                    name_avatar_row.grid_columnconfigure(0, weight=1)
                    entry = tk.Entry(
                        name_avatar_row,
                        textvariable=variable,
                        width=70,
                        bg=BRAND_COLORS["panel"],
                        fg=BRAND_COLORS["white"],
                        insertbackground=BRAND_COLORS["white"],
                        relief="flat",
                    )
                    entry.grid(row=0, column=0, sticky="ew", padx=(0, 10))
                    avatar_view = tk.Frame(
                        name_avatar_row,
                        width=82,
                        height=82,
                        bg=BRAND_COLORS["panel"],
                        highlightbackground=BRAND_COLORS["line"],
                        highlightthickness=1,
                    )
                    avatar_view.grid(row=0, column=1)
                    avatar_view.grid_propagate(False)
                    avatar_label = tk.Label(
                        avatar_view,
                        bg=BRAND_COLORS["panel"],
                        fg=BRAND_COLORS["muted"],
                        wraplength=72,
                        justify="center",
                    )
                    avatar_label.pack(fill="both", expand=True)

                    avatar_actions = tk.Frame(
                        name_avatar_row,
                        bg=BRAND_COLORS["bg_soft"],
                    )
                    avatar_actions.grid(
                        row=0,
                        column=2,
                        padx=(8, 0),
                    )

                    def refresh_card_avatar(
                        source=context.get("card_avatar_source", "") if context else "",
                        label=avatar_label,
                    ):
                        self._load_control_avatar(source, label, (76, 76))

                    refresh_card_avatar()

                    def choose_card_avatar(
                        editor_context=context,
                        label=avatar_label,
                        button_parent=avatar_actions,
                    ):
                        if editor_context is None:
                            return
                        selected = filedialog.askopenfilename(
                            title="选择角色头像",
                            parent=getattr(self, "_control_dialog", self.root),
                            filetypes=[
                                (
                                    "图片文件",
                                    "*.png *.gif *.ppm *.jpg *.jpeg",
                                ),
                                ("所有文件", "*.*"),
                            ],
                        )
                        if not selected:
                            return
                        selected_path = Path(selected)
                        if selected_path.suffix.lower() not in IMAGE_EXTENSIONS:
                            messagebox.showerror(
                                "头像格式不支持",
                                "请选择 png、gif、ppm、jpg 或 jpeg 图片。",
                                parent=getattr(self, "_control_dialog", self.root),
                            )
                            return
                        photo = self._control_image(selected_path, (76, 76))
                        if photo is None:
                            messagebox.showerror(
                                "头像读取失败",
                                "无法读取所选图片，请换一张图片后重试。",
                                parent=getattr(self, "_control_dialog", self.root),
                            )
                            return
                        editor_context["card_avatar_source"] = str(selected_path)
                        editor_context["card_avatar_changed"] = True
                        label.configure(image=photo, text="")
                        label.image = photo
                        for child in button_parent.winfo_children():
                            child.configure(text="更换头像")

                    avatar_button = self._brand_button(
                        avatar_actions,
                        text=(
                            "更换头像"
                            if context and context.get("card_avatar_source")
                            else "上传头像"
                        ),
                        command=choose_card_avatar,
                        accent=True,
                    )
                    avatar_button.grid(row=0, column=0, sticky="w")
                    variable = entry
                elif key == "user_address":
                    address_field = tk.Frame(content, bg=BRAND_COLORS["bg_soft"])
                    address_field.grid(row=row, column=1, sticky="ew", padx=(8, 20), pady=4)
                    address_field.grid_columnconfigure(0, weight=1)
                    entry = tk.Entry(
                        address_field, textvariable=variable, bg=BRAND_COLORS["panel"],
                        fg=BRAND_COLORS["white"], insertbackground=BRAND_COLORS["white"],
                        relief="flat",
                    )
                    entry.grid(row=0, column=0, sticky="ew", ipady=4)
                    hint = tk.Label(
                        address_field, text="留空时默认称呼为‘你’。", anchor="w", justify="left",
                        bg=BRAND_COLORS["bg_soft"], fg=BRAND_COLORS["muted"],
                        font=("Microsoft YaHei UI", 8),
                    )
                    hint.grid(row=1, column=0, sticky="ew", pady=(4, 0))
                    address_field.bind("<Configure>", lambda event, label=hint: label.configure(
                        wraplength=max(1, event.width)), add="+")
                    self._add_user_address_language_editor(
                        address_field, config_vars, config_field_vars, context)
                elif isinstance(value, bool):
                    variable = tk.BooleanVar(value=value)
                    toggle = self._brand_checkbutton(
                        content,
                        variable=variable,
                        bg=BRAND_COLORS["bg_soft"],
                        fg=BRAND_COLORS["white"],
                    )
                    toggle.grid(row=row, column=1, sticky="w", padx=(8, 20), pady=4)
                elif key == "personality":
                    personality_field = tk.Frame(content, bg=BRAND_COLORS["bg_soft"])
                    personality_field.grid(
                        row=row, column=1, sticky="ew", padx=(8, 20), pady=4
                    )
                    personality_field.grid_columnconfigure(0, weight=1)
                    editor = tk.Frame(
                        personality_field,
                        bg=BRAND_COLORS["panel"],
                        highlightbackground=BRAND_COLORS["line"],
                        highlightthickness=1,
                    )
                    editor.grid(row=0, column=0, sticky="ew")
                    personality_hint = tk.Label(
                        personality_field,
                        text="仅需填写角色的身份、性格和说话风格，通用交流规则已内置，无需重复填写。",
                        bg=BRAND_COLORS["bg_soft"],
                        fg=BRAND_COLORS["muted"],
                        font=("Microsoft YaHei UI", 9),
                        anchor="w",
                        justify="left",
                        wraplength=360,
                    )
                    personality_hint.grid(row=1, column=0, sticky="ew", pady=(4, 0))
                    personality_field.bind(
                        "<Configure>",
                        lambda event, hint=personality_hint: hint.configure(
                            wraplength=max(1, event.width)
                        ),
                    )
                    editor.grid_columnconfigure(0, weight=1)
                    editor.grid_rowconfigure(0, weight=1)
                    entry = tk.Text(
                        editor,
                        height=7,
                        width=70,
                        wrap="word",
                        bg=BRAND_COLORS["panel"],
                        fg=BRAND_COLORS["white"],
                        insertbackground=BRAND_COLORS["white"],
                        relief="flat",
                        bd=0,
                        padx=7,
                        pady=6,
                    )
                    entry.insert("1.0", str(value))
                    entry.grid(row=0, column=0, sticky="nsew")
                    personality_scrollbar = _BrandScrollbar(
                        editor,
                        orient="vertical",
                        command=entry.yview,
                        style="Brand.Vertical.TScrollbar",
                    )
                    personality_scrollbar.grid(row=0, column=1, sticky="ns", pady=(0, 20))
                    self._setup_brand_widget_scroll(entry, personality_scrollbar)

                    grip = tk.Canvas(
                        editor,
                        width=20,
                        height=20,
                        bg=BRAND_COLORS["panel"],
                        highlightthickness=0,
                        cursor="size_nw_se",
                    )
                    grip.grid(row=0, column=1, sticky="se")
                    for offset in (7, 12, 17):
                        grip.create_line(
                            offset - 3,
                            19,
                            19,
                            offset - 3,
                            fill=BRAND_COLORS["cyan"],
                            width=1,
                        )
                    resize_state = {"dragging": False}

                    def begin_personality_resize(event, text_widget=entry, state=resize_state):
                        state["x"] = event.x_root
                        state["y"] = event.y_root
                        state["width"] = int(text_widget.cget("width"))
                        state["height"] = int(text_widget.cget("height"))
                        state["dragging"] = True
                        return "break"

                    def resize_personality(
                        event,
                        text_widget=entry,
                        state=resize_state,
                        editor_frame=editor,
                        resize_grip=grip,
                    ):
                        if not state["dragging"]:
                            return "break"
                        text_widget.configure(
                            width=max(
                                40,
                                min(
                                    110,
                                    state["width"]
                                    + round((event.x_root - state["x"]) / 8),
                                ),
                            ),
                            height=max(
                                5,
                                min(
                                    18,
                                    state["height"]
                                    + round((event.y_root - state["y"]) / 20),
                                ),
                            ),
                        )
                        self._set_personality_editor_height(
                            editor_frame,
                            text_widget,
                            resize_grip,
                            lines=int(text_widget.cget("height")),
                        )
                        return "break"

                    def finish_personality_resize(state=resize_state):
                        state["dragging"] = False
                        return "break"

                    grip.bind("<ButtonPress-1>", begin_personality_resize)
                    grip.bind("<B1-Motion>", resize_personality)
                    grip.bind("<ButtonRelease-1>", lambda _event: finish_personality_resize())
                    self._set_personality_editor_height(editor, entry, grip)
                    variable = entry
                elif key in ("speed", "temperature", "top_k"):
                    limits = {"speed": (0.5, 2.0, 0.01), "temperature": (0.1, 2.0, 0.01), "top_k": (1, 10, 1)}
                    low, high, step = limits[key]
                    scale = _brand_scale(
                        content,
                        from_=low,
                        to=high,
                        resolution=step,
                        orient="horizontal",
                        variable=variable,
                        showvalue=True,
                        length=360,
                        bg=BRAND_COLORS["bg_soft"],
                        fg=BRAND_COLORS["white"],
                        troughcolor=BRAND_COLORS["panel_soft"],
                        activebackground=BRAND_COLORS["cyan"],
                        highlightthickness=0,
                        bd=0,
                    )
                    scale.grid(row=row, column=1, sticky="ew", padx=(8, 20), pady=4)
                    variable = scale
                elif key == "language":
                    menu = self._brand_option_menu(
                        content,
                        variable,
                        ("中文", "日文"),
                    )
                    if str(value) in ("zh", "中文"):
                        variable.set("中文")
                    else:
                        variable.set("日文")
                    menu.grid(row=row, column=1, sticky="ew", padx=(8, 20), pady=4)
                    variable._language_menu = menu
                elif key == "text":
                    entry = tk.Entry(
                        content,
                        textvariable=variable,
                        width=58,
                        bg=BRAND_COLORS["panel"],
                        fg=BRAND_COLORS["white"],
                        insertbackground=BRAND_COLORS["white"],
                        relief="flat",
                    )
                    entry.grid(row=row, column=1, sticky="ew", padx=(8, 4), pady=4)
                else:
                    entry = tk.Entry(
                        content,
                        textvariable=variable,
                        width=70,
                        bg=BRAND_COLORS["panel"],
                        fg=BRAND_COLORS["white"],
                        insertbackground=BRAND_COLORS["white"],
                        relief="flat",
                    )
                    entry.grid(row=row, column=1, sticky="ew", padx=(8, 20), pady=4)
                help_text = self._field_help(key)
                if help_text:
                    tk.Label(
                        content,
                        text=help_text,
                        anchor="w",
                        bg=BRAND_COLORS["bg_soft"],
                        fg=BRAND_COLORS["muted"],
                    ).grid(
                        row=row, column=2, sticky="w", padx=(0, 20), pady=4
                    )
                config_vars.append((target, prefix, key, value, variable, json_sections, None))
                row += 1
        content.grid_columnconfigure(1, weight=1)
        self._setup_brand_canvas_scroll(
            canvas,
            content,
            scrollbar,
            window_id=window_id,
        )
        return tab, content, row

    def _user_address_preview_snapshot(self, config_vars, context=None):
        context = context or {}
        character = copy.deepcopy(context.get("character_config", self.character_config))
        voice = copy.deepcopy(context.get("voice_config", self.voice_config))
        fields = [(*item[:6], None) for item in config_vars if (
            item[0] == "voice" or (item[0] == "character" and (
                item[2] == "user_address" or item[1].startswith("user_address_by_language."))))]
        self._apply_config_vars(fields, character_config=character, voice_config=voice)
        return dict(character_id=context.get("character_id", self.character_id),
                    character_dir=context.get("character_dir", getattr(self, "character_dir", None)),
                    character_config=character, voice_config=voice)

    def _synthesize_user_address_preview(self, snapshot, language, speech_text):
        # A separate facade captures the edited role without changing the active role.
        preview = DesktopPetApp.__new__(DesktopPetApp)
        preview.__dict__.update(snapshot)
        preview.gpt_sovits_client = self.gpt_sovits_client
        preview._tts_lock = self._tts_lock
        model = snapshot["voice_config"].get("model", {})
        if isinstance(model, dict) and (model.get("ckpt_file") or model.get("pth_file")):
            weights = []
            for key in ("ckpt_file", "pth_file"):
                path = Path(str(model.get(key) or ""))
                if not path.is_absolute():
                    path = Path(snapshot["character_dir"]) / "voice" / path
                if not path.is_file():
                    raise ValueError("该角色的语音模型文件不完整。")
                weights.append(path.resolve())
            preview._tts_weights_override = (model, *weights)
        reference = preview._resolve_tts_reference(language)
        if reference is None:
            raise ValueError("请先配置该角色的{}参考音频。".format(
                OUTPUT_LANGUAGE_NAMES.get(language, language)))
        reference_audio, prompt_text, prompt_lang = reference
        path = preview._synthesize_tts_segment(
            speech_text, None, reference_audio, prompt_text,
            preview._tts_model_language(language), prompt_lang,
            generation_params=preview._tts_generation_params(language))
        try:
            preview._validate_complete_tts_audio(path, speech_text)
        except Exception:
            if path is not None:
                Path(path).unlink(missing_ok=True)
            raise
        return path

    def _add_user_address_language_editor(self, parent, config_vars, config_field_vars, context):
        config = context["character_config"] if context else self.character_config
        settings = address_settings(config)
        panel = tk.Frame(parent, bg=BRAND_COLORS["bg_soft"])
        panel.grid(row=3, column=0, sticky="ew", pady=(6, 0))
        controls = tk.Frame(panel, bg=BRAND_COLORS["bg_soft"])
        language_bar = tk.Frame(controls, bg=BRAND_COLORS["bg_soft"])
        language_bar.pack(fill="x", pady=(0, 8))
        language_buttons = {}
        selected_language = {"value": "zh"}
        expanded = tk.BooleanVar(master=panel, value=False)

        def toggle():
            expanded.set(not expanded.get())
            if expanded.get():
                controls.pack(fill="x", pady=(6, 0))
            else:
                controls.pack_forget()
                invalidate()
            disclosure.configure(text="按语言调整与试听  {}".format("收起" if expanded.get() else "展开"))

        disclosure = tk.Button(
            panel, text="按语言调整与试听  展开", command=toggle, relief="flat", bd=0,
            bg=BRAND_COLORS["bg_soft"], fg=BRAND_COLORS["cyan_soft"],
            activebackground=BRAND_COLORS["bg_soft"], anchor="w", cursor="hand2")
        disclosure.pack(fill="x")
        rows = {}
        traces = []
        alive = threading.Event()
        alive.set()

        def select_language(language):
            selected_language["value"] = language
            for key, row in rows.items():
                if key == language:
                    row["frame"].pack(fill="x")
                else:
                    row["frame"].pack_forget()
                    cancel(row)
                language_buttons[key].configure(
                    bg=BRAND_COLORS["cyan"] if key == language else BRAND_COLORS["panel_soft"],
                    fg=BRAND_COLORS["dark"] if key == language else BRAND_COLORS["muted"],
                    font=("Microsoft YaHei UI", 10, "bold" if key == language else "normal"),
                    relief="sunken" if key == language else "flat")

        def discard(path):
            if path is not None:
                try:
                    Path(path).unlink(missing_ok=True)
                except OSError:
                    # A cancelled playback worker also retries after closing its reader.
                    pass

        def cancel(row):
            row["cancel"].set()
            player = row.get("player")
            if player:
                player.abort()
            row["player"] = None
            if row.get("poll") is not None:
                panel.after_cancel(row["poll"])
                row["poll"] = None
            if row.get("path"):
                discard(row["path"])
            row["path"] = None
            while True:
                try:
                    _success, value = row["queue"].get_nowait()
                    if _success:
                        discard(value[0])
                except queue.Empty:
                    break
            if row["generate"].winfo_exists():
                row["generate"].configure(state=tk.NORMAL)
            if row["play"].winfo_exists():
                row["play"].configure(state=tk.DISABLED, text="重播")
                row["play"].pack_forget()
            row["text"].set("")
            row["status"].set("")

        def invalidate(*_args):
            for row in rows.values():
                cancel(row)
                row["status"].set("")
                row["text"].set("")

        def play(language):
            row = rows[language]
            if row.get("player"):
                row["player"].abort()
                row["player"] = None
                row["play"].configure(text="重播")
                return
            if not row.get("path"):
                return
            try:
                unchanged = row.get("snapshot") == self._user_address_preview_snapshot(config_vars, context)
            except Exception:
                unchanged = False
            if not unchanged:
                invalidate()
                row["status"].set("设置已变化，请重新试听。")
                return
            for other in rows.values():
                if other is not row and other.get("player"):
                    other["player"].abort()
                    other["player"] = None
                    other["play"].configure(text="重播")
            path = row["path"]
            player = PCMStreamPlayer()
            cancelled = row["cancel"]
            playback = {"failed": False}
            row["player"] = player
            row["play"].configure(text="停止")

            def worker():
                try:
                    with wave.open(str(path), "rb") as audio:
                        rate, channels, width = audio.getframerate(), audio.getnchannels(), audio.getsampwidth()
                        while True:
                            frames = audio.readframes(max(1, rate // 2))
                            if not frames:
                                break
                            player.write(frames, rate, channels, width)
                    player.finish()
                except Exception:
                    playback["failed"] = True
                    player.abort()
                finally:
                    if cancelled.is_set():
                        discard(path)

            def poll_playback():
                row["poll"] = None
                if not alive.is_set() or row.get("player") is not player:
                    return
                if not player.done:
                    row["poll"] = panel.after(80, poll_playback)
                else:
                    row["player"] = None
                    row["play"].configure(text="重播")
                    if player.error or playback["failed"]:
                        row["status"].set("播放失败，可重新试听。")

            threading.Thread(target=worker, daemon=True).start()
            row["poll"] = panel.after(80, poll_playback)

        def generate(language):
            row = rows[language]
            cancel(row)
            try:
                snapshot = self._user_address_preview_snapshot(config_vars, context)
                visible = address_preview_text(snapshot["character_config"], language)
                speech = address_speech_text(visible, snapshot["character_config"], language)
                if language == "ja":
                    speech = self._normalize_japanese_tts_text(speech)
                else:
                    speech = self._tts_text(speech)
            except Exception:
                row["status"].set("请检查当前角色和语音设置。")
                return
            row["snapshot"] = snapshot
            needs_translation = language == "ja" and address_needs_japanese_translation(visible, snapshot["character_config"])
            row["status"].set("正在转换日语读法并生成试听……" if needs_translation else "正在生成试听语音……")
            row["generate"].configure(state=tk.DISABLED)
            cancelled = row["cancel"] = threading.Event()
            results = row["queue"] = queue.Queue()

            def worker():
                path = None
                actual_speech = speech
                try:
                    if cancelled.is_set():
                        return
                    if language == "ja" and address_needs_japanese_translation(visible, snapshot["character_config"]):
                        preview = DesktopPetApp.__new__(DesktopPetApp)
                        preview.character_config = snapshot["character_config"]
                        preview.app_config = self.app_config
                        actual_speech = preview._translate_tts_text(visible, language)
                    if cancelled.is_set():
                        return
                    path = self._synthesize_user_address_preview(
                        dict(snapshot, _tts_cancel_event=cancelled), language, actual_speech)
                    results.put((True, (path, actual_speech)))
                except Exception as error:
                    results.put((False, error))
                finally:
                    if cancelled.is_set() and path is not None:
                        discard(path)

            def poll():
                row["poll"] = None
                if not alive.is_set() or cancelled.is_set():
                    return
                try:
                    success, result = results.get_nowait()
                except queue.Empty:
                    row["poll"] = panel.after(80, poll)
                    return
                row["generate"].configure(state=tk.NORMAL)
                try:
                    unchanged = snapshot == self._user_address_preview_snapshot(config_vars, context)
                except Exception:
                    unchanged = False
                if not unchanged:
                    if success:
                        Path(result[0]).unlink(missing_ok=True)
                    row["status"].set("设置已变化，请重新试听。")
                    return
                if success:
                    row["path"], actual_speech = result
                    row["text"].set("试听句：{}\n实际朗读：{}".format(visible, actual_speech))
                    row["play"].configure(state=tk.NORMAL)
                    row["play"].pack(side="left", padx=(8, 0))
                    row["status"].set("试听已生成。")
                    play(language)
                else:
                    # Do not echo service payloads/credentials into settings.
                    row["status"].set("试听失败，请检查对话模型、语音模型及参考音频；也可填写语音读法后重试。")

            threading.Thread(target=worker, daemon=True).start()
            row["poll"] = panel.after(80, poll)

        for language, label in (("zh", "中文"), ("ja", "日文")):
            column = len(language_buttons)
            language_bar.grid_columnconfigure(column, weight=1, uniform="address_language")
            button = self._brand_button(language_bar, label, lambda lang=language: select_language(lang))
            button.grid(row=0, column=column, sticky="ew", padx=(0, 4) if column == 0 else (4, 0))
            language_buttons[language] = button
            tab = tk.Frame(controls, bg=BRAND_COLORS["bg_soft"])
            tab.grid_columnconfigure(1, weight=1)
            for index, (key, caption) in enumerate((("address", "称呼"), ("reading", "读法（选填）"))):
                variable = tk.StringVar(master=panel, value=settings[language][key])
                prefix = "user_address_by_language." + language
                config_vars.append(("character", prefix, key, settings[language][key], variable, False, None))
                config_field_vars[("character", prefix, key)] = variable
                traces.append((variable, variable.trace_add("write", invalidate)))
                tk.Label(tab, text=caption, bg=BRAND_COLORS["bg_soft"], fg=BRAND_COLORS["white"],
                         anchor="w").grid(row=index, column=0, sticky="w", padx=5, pady=5)
                tk.Entry(tab, textvariable=variable, width=12, bg=BRAND_COLORS["panel"],
                         fg=BRAND_COLORS["white"], insertbackground=BRAND_COLORS["white"],
                         relief="flat").grid(row=index, column=1, sticky="ew", padx=5, pady=5, ipady=4)
            actions = tk.Frame(tab, bg=BRAND_COLORS["bg_soft"])
            actions.grid(row=3, column=0, columnspan=2, sticky="w", padx=5, pady=(6, 3))
            generate_button = self._brand_button(actions, "试听", lambda lang=language: generate(lang), width=6)
            generate_button.pack(side="left")
            play_button = self._brand_button(actions, "重播", lambda lang=language: play(lang), width=6)
            play_button.configure(state=tk.DISABLED)
            text, status = tk.StringVar(master=panel), tk.StringVar(master=panel)
            result_widgets = []
            for index, variable in enumerate((text, status), 4):
                label_widget = tk.Label(tab, textvariable=variable, anchor="w", justify="left",
                                       bg=BRAND_COLORS["bg_soft"], fg=BRAND_COLORS["muted"],
                                       font=("Microsoft YaHei UI", 8))
                label_widget.grid(row=index, column=0, columnspan=2, sticky="ew", padx=5, pady=3)
                label_widget.grid_remove()
                result_widgets.append(label_widget)
                def update_result(*_args, value=variable, widget=label_widget):
                    if not alive.is_set() or not widget.winfo_exists():
                        return
                    if value.get():
                        widget.grid()
                    else:
                        widget.grid_remove()
                traces.append((variable, variable.trace_add("write", update_result)))
                tab.bind("<Configure>", lambda event, widget=label_widget: widget.configure(
                    wraplength=max(1, event.width - 10)), add="+")
            if language in ("zh", "ja"):
                hint = tk.Label(tab, text=("称呼留空沿用默认称呼；读法留空自动转换为日语。" if language == "ja"
                                          else "称呼留空沿用默认称呼；读法留空按称呼朗读。"),
                                bg=BRAND_COLORS["bg_soft"], fg=BRAND_COLORS["muted"],
                                font=("Microsoft YaHei UI", 8), anchor="w", wraplength=330,
                                justify="left")
                hint.grid(row=2, column=0, columnspan=2, sticky="ew", padx=5, pady=(2, 3))
                tab.bind("<Configure>", lambda event, widget=hint: widget.configure(
                    wraplength=max(1, event.width - 10)), add="+")
            rows[language] = dict(generate=generate_button, play=play_button, text=text,
                                  status=status, frame=tab, result_widgets=result_widgets,
                                  cancel=threading.Event(), queue=queue.Queue(), poll=None)
        select_language("zh")
        default_var = config_field_vars.get(("character", "", "user_address"))
        if default_var is not None:
            traces.append((default_var, default_var.trace_add("write", invalidate)))

        def destroy(event):
            if event.widget is panel:
                alive.clear()
                for row in rows.values():
                    cancel(row)
                for variable, trace in traces:
                    variable.trace_remove("write", trace)

        panel.bind("<Destroy>", destroy, add="+")
        panel._address_preview = dict(rows=rows, toggle=toggle, generate=generate, play=play,
                                      controls=controls, language_buttons=language_buttons,
                                      select_language=select_language, invalidate=invalidate)
        return panel

    def _add_language_parameter_editor(
        self, content, row, section_title, values, config_vars, config_field_vars,
        target="voice",
    ):
        """One folded editor for ordinary and autonomous speech generation."""
        expanded = tk.BooleanVar(master=content, value=False)
        header = tk.Frame(content, bg=BRAND_COLORS["bg_soft"])
        header.grid(row=row, column=0, columnspan=3, sticky="ew", padx=12, pady=(12, 6))
        controls = tk.Frame(content, bg=BRAND_COLORS["bg_soft"])
        controls.grid(row=row + 1, column=0, columnspan=3, sticky="ew", padx=12)
        controls.grid_columnconfigure(1, weight=1)

        def toggle():
            expanded.set(not expanded.get())
            if expanded.get():
                controls.grid()
            else:
                controls.grid_remove()
            disclosure.configure(text="高级生成参数  {}".format("收起" if expanded.get() else "展开"))

        disclosure = tk.Button(
            header, text="高级生成参数  展开", command=toggle,
            bg=BRAND_COLORS["bg_soft"], fg=BRAND_COLORS["cyan_soft"],
            activebackground=BRAND_COLORS["bg_soft"], relief="flat", bd=0,
            font=("Microsoft YaHei UI", 10, "bold"), cursor="hand2", anchor="w",
        )
        disclosure.pack(anchor="w")
        defaults = {"speed": 1.0, "temperature": .4, "top_k": 7, "top_p": 1.0,
                    "repetition_penalty": 1.35, "seed": 10201,
                    "parallel_infer": False, "streaming_mode": False, "sample_steps": 32}
        common = dict(defaults, **values.get("common", {}))
        scopes = {"common": common, **{lang: dict(common, **values.get(lang, {})) for lang in ("zh", "ja")}}
        mode = tk.StringVar(master=content, value=values.get("mode", "general"))
        language = tk.StringVar(master=content, value=values.get("language", "zh"))
        mode_buttons = {}
        editors = {}
        mode_row = tk.Frame(controls, bg=BRAND_COLORS["bg_soft"])
        mode_row.grid(row=0, column=0, columnspan=2, sticky="ew", pady=(0, 8))
        limits = {"speed": (.5, 2.0, .01), "temperature": (.1, 1.5, .01),
                  "top_k": (1, 20, 1), "top_p": (.5, 1.0, .01),
                  "repetition_penalty": (1.0, 2.0, .01), "sample_steps": (8, 64, 1)}

        def refresh():
            selected = "common" if mode.get() == "general" else language.get()
            for scope, widgets in editors.items():
                for widget in widgets:
                    widget.grid() if scope == selected else widget.grid_remove()
            for scope, button in mode_buttons.items():
                button.configure(bg=BRAND_COLORS["cyan"] if scope == selected else BRAND_COLORS["panel"])

        def choose(scope):
            mode.set("general" if scope == "common" else "language")
            if scope != "common":
                language.set(scope)
            refresh()

        for index, (scope, label) in enumerate((("common", "通用"), ("zh", "中文"), ("ja", "日文"))):
            button = self._brand_button(mode_row, label, lambda scope=scope: choose(scope))
            button.grid(row=0, column=index, sticky="ew", padx=(0, 2))
            mode_row.grid_columnconfigure(index, weight=1)
            mode_buttons[scope] = button
        for index, (key, default) in enumerate(defaults.items(), start=1):
            tk.Label(controls, text=self._field_label(key), anchor="w",
                     bg=BRAND_COLORS["bg_soft"], fg=BRAND_COLORS["white"]).grid(
                         row=index, column=0, sticky="w", padx=(8, 16), pady=4)
        for scope, parameters in scopes.items():
            editors[scope] = []
            prefix = "generation" if scope == "common" else "generation_by_language." + scope
            for index, (key, default) in enumerate(defaults.items(), start=1):
                old = parameters[key]
                variable = (tk.BooleanVar(master=content, value=bool(old)) if isinstance(default, bool)
                            else tk.StringVar(master=content, value=str(old)))
                config_vars.append((target, prefix, key, old, variable, False, None))
                config_field_vars[(target, prefix, key)] = variable
                if key in limits:
                    low, high, step = limits[key]
                    editor = _brand_scale(controls, from_=low, to=high, resolution=step,
                        orient="horizontal", variable=variable, showvalue=True, length=280,
                        bg=BRAND_COLORS["bg_soft"], fg=BRAND_COLORS["white"],
                        troughcolor=BRAND_COLORS["panel"], highlightthickness=0, bd=0)
                elif isinstance(default, bool):
                    editor = self._brand_checkbutton(controls, variable=variable,
                        bg=BRAND_COLORS["bg_soft"], fg=BRAND_COLORS["white"])
                else:
                    editor = tk.Entry(controls, textvariable=variable, relief="flat",
                                      bg=BRAND_COLORS["panel"], fg=BRAND_COLORS["white"])
                editor.grid(row=index, column=1, sticky="ew", pady=4, padx=(0, 8))
                editors[scope].append(editor)
        for key, variable in ((values["mode_key"], mode), (values["language_key"], language)):
            config_vars.append((target, "", key, variable.get(), variable, False, None))
            config_field_vars[(target, "", key)] = variable
        refresh()
        controls.grid_remove()
        return row + 2


    def _setup_brand_widget_scroll(self, widget, scrollbar, keep_visible=False):
        """给 Listbox/Text 等直接滚动控件接入品牌滚动条。"""
        try:
            widget.master.grid_columnconfigure(
                1,
                minsize=max(1, int(scrollbar.winfo_reqwidth())),
            )
        except (AttributeError, tk.TclError, TypeError, ValueError):
            pass
        state = {"visible": False}

        def update_scrollbar(first, last):
            scrollbar.set(first, last)
            if keep_visible:
                if scrollbar.winfo_manager() != "grid":
                    scrollbar.grid()
                return
            try:
                first = float(first)
                last = float(last)
            except (TypeError, ValueError):
                first, last = 0.0, 0.0
            if state["visible"]:
                needs_scroll = first > 0.001 or last < 0.995
            else:
                needs_scroll = first > 0.001 or last < 0.999
            if needs_scroll == state["visible"]:
                return
            state["visible"] = needs_scroll
            if needs_scroll:
                scrollbar.grid()
            else:
                scrollbar.grid_remove()

        widget.configure(yscrollcommand=update_scrollbar)
        widget._brand_inner_scroll = True

        def scroll(event):
            delta = getattr(event, "delta", 0)
            if delta:
                units = -max(1, abs(delta) // 120) * (1 if delta > 0 else -1)
            elif getattr(event, "num", None) == 4:
                units = -1
            elif getattr(event, "num", None) == 5:
                units = 1
            else:
                return "break"
            widget.yview_scroll(units, "units")
            return "break"

        widget.bind("<MouseWheel>", scroll, add="+")
        widget.bind("<Button-4>", scroll, add="+")
        widget.bind("<Button-5>", scroll, add="+")
        if keep_visible:
            scrollbar.grid()
        else:
            scrollbar.grid_remove()
        try:
            reset_job = widget.after_idle(lambda: widget.yview_moveto(0))
            def cancel_reset(event):
                if event.widget is widget:
                    try:
                        widget.after_cancel(reset_job)
                    except (AttributeError, tk.TclError):
                        pass
            widget.bind("<Destroy>", cancel_reset, add="+")
        except tk.TclError:
            pass

    def _setup_brand_canvas_scroll(
        self,
        canvas,
        content,
        scrollbar,
        window_id=None,
    ):
        """统一设置蓝色滚动区域、自动隐藏滚动条和子控件滚轮操作。"""
        def sync_scrollbar(first, last):
            view = (float(first), float(last))
            previous = getattr(canvas, "_brand_last_popup_view", None)
            if previous is not None and previous[0] != view[0]:
                self._dismiss_brand_scroll_popups(canvas)
            canvas._brand_last_popup_view = view
            scrollbar.set(first, last)
        canvas.configure(yscrollcommand=sync_scrollbar)
        state = {
            "needs_scroll": False,
            "scrollbar_visible": False,
            "update_after_id": None,
            "bind_after_id": None,
            "wheel_pixel_remainder": 0.0,
            "pending_scroll_pixels": 0,
            "redraw_after_id": None,
            "redraw_pending": False,
            "idle_after_id": None,
            "disposed": False,
        }
        try:
            scrollbar.grid_remove()
        except tk.TclError:
            pass

        def update_scrollbar(_event=None):
            try:
                if (
                    not canvas.winfo_ismapped()
                    or canvas.winfo_height() <= 1
                ):
                    if state["scrollbar_visible"] is not False:
                        scrollbar.grid_remove()
                        state["scrollbar_visible"] = False
                    state["needs_scroll"] = False
                    return
                bbox = canvas.bbox("all")
                if bbox:
                    canvas.configure(scrollregion=bbox)
                content_height = content.winfo_reqheight()
                canvas_height = canvas.winfo_height()
                previous_needs_scroll = state["needs_scroll"]
                threshold = (
                    canvas_height - 8
                    if previous_needs_scroll
                    else canvas_height + 2
                )
                needs_scroll = content_height > threshold
                state["needs_scroll"] = needs_scroll
                if needs_scroll and state["scrollbar_visible"] is not True:
                    scrollbar.grid()
                    state["scrollbar_visible"] = True
                elif not needs_scroll and state["scrollbar_visible"] is not False:
                    scrollbar.grid_remove()
                    state["scrollbar_visible"] = False
                if previous_needs_scroll and not needs_scroll:
                    view = canvas.yview()
                    if view and float(view[0]) > 0.001:
                        canvas.yview_moveto(0)
            except tk.TclError:
                return

        canvas._brand_scroll_update = update_scrollbar
        content._brand_scroll_update = update_scrollbar

        def schedule_update():
            if state["disposed"] or state["update_after_id"] is not None:
                return
            try:
                state["update_after_id"] = canvas.after(24, flush_update)
            except tk.TclError:
                state["update_after_id"] = None

        def flush_update():
            state["update_after_id"] = None
            update_scrollbar()

        def flush_scroll_and_redraw():
            state["redraw_after_id"] = None
            pixels = state["pending_scroll_pixels"]
            state["pending_scroll_pixels"] = 0
            redraw_pending = state["redraw_pending"]
            state["redraw_pending"] = False
            try:
                if pixels:
                    canvas.yview_scroll(pixels, "units")
                if pixels or redraw_pending:
                    self._redraw_scroll_canvas(canvas, content)
            except tk.TclError:
                return

        def schedule_scroll_redraw():
            state["redraw_pending"] = True
            if state["redraw_after_id"] is not None:
                return
            try:
                state["redraw_after_id"] = canvas.after(
                    16,
                    flush_scroll_and_redraw,
                )
            except tk.TclError:
                state["redraw_after_id"] = None

        def scroll_from_bar(*args):
            try:
                canvas.yview(*args)
            except tk.TclError:
                return
            state["pending_scroll_pixels"] = 0
            schedule_scroll_redraw()

        def schedule_bind_tree():
            if state["disposed"] or state["bind_after_id"] is not None:
                return
            try:
                state["bind_after_id"] = canvas.after(24, flush_bind_tree)
            except tk.TclError:
                state["bind_after_id"] = None

        def scroll(event):
            if not state["needs_scroll"]:
                update_scrollbar()
            if not state["needs_scroll"]:
                return forward_scroll_to_parent(event)
            delta = getattr(event, "delta", 0)
            if delta:
                pixels = -float(delta) * 20.0 / 120.0
                pixels += state["wheel_pixel_remainder"]
                scroll_pixels = int(pixels)
                state["wheel_pixel_remainder"] = pixels - scroll_pixels
            elif getattr(event, "num", None) == 4:
                scroll_pixels = -20
            elif getattr(event, "num", None) == 5:
                scroll_pixels = 20
            else:
                return None
            if not scroll_pixels:
                return forward_scroll_to_parent(event)
            try:
                first, last = canvas.yview()
                if (scroll_pixels < 0 and first <= 0.001) or (
                    scroll_pixels > 0 and last >= 0.999
                ):
                    return forward_scroll_to_parent(event)
            except (tk.TclError, TypeError, ValueError):
                return None
            state["pending_scroll_pixels"] += scroll_pixels
            schedule_scroll_redraw()
            return "break"

        def forward_scroll_to_parent(event):
            parent = getattr(canvas, "master", None)
            while parent is not None:
                parent_scroll = getattr(parent, "_brand_scroll_handler", None)
                if callable(parent_scroll):
                    return parent_scroll(event)
                parent = getattr(parent, "master", None)
            return None

        canvas._brand_scroll_handler = scroll

        def bind_tree(widget):
            try:
                if (
                    not getattr(widget, "_brand_inner_scroll", False)
                    and getattr(widget, "_brand_scroll_canvas_id", None) != id(canvas)
                ):
                    widget.bind("<MouseWheel>", scroll, add="+")
                    widget.bind("<Button-4>", scroll, add="+")
                    widget.bind("<Button-5>", scroll, add="+")
                    widget._brand_scroll_canvas_id = id(canvas)
                for child in widget.winfo_children():
                    bind_tree(child)
            except tk.TclError:
                return

        state["bind_tree"] = bind_tree
        try:
            content._brand_scroll_bind_tree = bind_tree
        except tk.TclError:
            pass

        def flush_bind_tree():
            state["bind_after_id"] = None
            bind_tree(content)

        def on_content_configure(event=None):
            try:
                bbox = canvas.bbox("all")
                if bbox:
                    canvas.configure(scrollregion=bbox)
                schedule_bind_tree()
                schedule_update()
            except tk.TclError:
                return

        def on_canvas_configure(event):
            try:
                if window_id is not None:
                    canvas.itemconfigure(window_id, width=event.width)
                schedule_update()
            except tk.TclError:
                return

        content.bind("<Configure>", on_content_configure, add="+")
        canvas.bind("<Configure>", on_canvas_configure, add="+")
        canvas.bind(
            "<Map>",
            lambda _event: schedule_update(),
            add="+",
        )
        try:
            canvas.configure(yscrollincrement=1)
        except tk.TclError:
            pass
        try:
            scrollbar.configure(command=scroll_from_bar)
        except (AttributeError, tk.TclError):
            pass
        bind_tree(content)
        bind_tree(canvas)
        scrollbar.grid(row=0, column=1, sticky="ns")
        scrollbar.grid_remove()
        def cancel_scroll_jobs(event):
            if event.widget is not canvas:
                return
            state["disposed"] = True
            for key in ("idle_after_id", "update_after_id", "bind_after_id", "redraw_after_id"):
                if state[key] is not None:
                    try:
                        canvas.after_cancel(state[key])
                    except (AttributeError, tk.TclError):
                        pass
                    state[key] = None
        canvas.bind("<Destroy>", cancel_scroll_jobs, add="+")
        try:
            state["idle_after_id"] = canvas.after_idle(schedule_update)
        except tk.TclError:
            pass

    @staticmethod
    def _redraw_scroll_canvas(canvas, content=None):
        """刷新滚动区域及其嵌入控件，清除 Windows 滚动后的旧像素。"""
        try:
            canvas.update_idletasks()
        except tk.TclError:
            pass
        if sys.platform == "win32":
            try:
                import ctypes

                redraw_window = ctypes.windll.user32.RedrawWindow
                redraw_window.argtypes = (
                    ctypes.c_void_p,
                    ctypes.c_void_p,
                    ctypes.c_void_p,
                    ctypes.c_uint,
                )
                redraw_window.restype = ctypes.c_int
                flags = 0x0001 | 0x0004 | 0x0080 | 0x0100
                redrawn = False
                for widget in (canvas, content):
                    if widget is None:
                        continue
                    try:
                        window_id = int(widget.winfo_id())
                    except (AttributeError, tk.TclError, TypeError, ValueError):
                        continue
                    if not window_id:
                        continue
                    redrawn = bool(
                        redraw_window(
                            ctypes.c_void_p(window_id),
                            None,
                            None,
                            flags,
                        )
                    ) or redrawn
                if redrawn:
                    return
            except (AttributeError, OSError, tk.TclError, TypeError, ValueError):
                pass
        try:
            canvas.update_idletasks()
        except tk.TclError:
            pass



    def _resolve_reference_audio(self, context=None):
        """将 voice.json 中的默认参考音频路径解析为可读取的本地路径。"""
        voice_config = context["voice_config"] if context else self.voice_config
        character_dir = context["character_dir"] if context else self.character_dir
        value = voice_config.get("reference", {}).get("default_audio", "")
        if not value:
            return ""
        candidate = Path(str(value)).expanduser()
        if candidate.is_absolute() and candidate.is_file():
            return str(candidate)
        for base in (character_dir / "voice", character_dir / "portraits", character_dir):
            resolved = base / candidate
            if resolved.is_file():
                return str(resolved)
        return str(candidate) if candidate.is_file() else ""

