    def _layout_portrait_manager_cards(self, context):
        manager = context.get("portrait_manager", {})
        manager["layout_after_id"] = None
        cards = manager.get("cards")
        if cards is None:
            return
        try:
            width = max(1, cards.winfo_width())
            selected = manager.get("selected_emotion_row")
            rows = [selected] if selected is not None else []
            columns = 1
            if (
                columns == manager.get("layout_columns")
                and all(
                    row.get("frame") is not None
                    and row["frame"].winfo_exists()
                    for row in rows
                )
            ):
                return
            manager["layout_columns"] = columns
            for column in range(max(columns, cards.grid_size()[0])):
                cards.grid_columnconfigure(
                    column,
                    weight=1 if column < columns else 0,
                    uniform="portrait_cards" if column < columns else "",
                    minsize=0,
                )
            for index, row in enumerate(rows):
                frame = row.get("frame")
                if frame is None or not frame.winfo_exists():
                    continue
                frame.grid(
                    row=index // columns,
                    column=index % columns,
                    sticky="nsew",
                    padx=5,
                    pady=5,
                )
            manager["layout_row_count"] = len(rows)
            canvas = context.get("portrait_manager_canvas")
            refresh_scroll = (
                getattr(canvas, "_brand_scroll_update", None)
                if canvas is not None
                else None
            )
            if callable(refresh_scroll):
                refresh_scroll()
            anchor = manager.pop("pending_scroll_anchor", None)
            if anchor and canvas is not None and rows:
                def restore_anchor():
                    try:
                        target_index = min(
                            max(0, int(anchor.get("row_index", 0))), len(rows) - 1
                        )
                        target_frame = rows[target_index].get("frame")
                        bbox = canvas.bbox("all")
                        if target_frame is None or not bbox:
                            return
                        region_top, _left, region_right, region_bottom = bbox
                        region_height = max(1, region_bottom - region_top)
                        desired_top = (
                            cards.winfo_y() + target_frame.winfo_y()
                            - float(anchor.get("viewport_offset", 0))
                        )
                        desired_top = min(
                            max(region_top, desired_top),
                            max(region_top, region_bottom - max(1, canvas.winfo_height())),
                        )
                        canvas.yview_moveto(
                            (desired_top - region_top) / float(region_height)
                        )
                    except tk.TclError:
                        pass

                cards.after_idle(restore_anchor)
        except tk.TclError:
            return

    @staticmethod
    def _update_treeview_scrollbar(table, scrollbar, first, last):
        scrollbar.set(first, last)
        try:
            needs_scroll = float(last) - float(first) < 0.999
        except (TypeError, ValueError):
            needs_scroll = False
        if needs_scroll:
            scrollbar.grid()
        else:
            scrollbar.grid_remove()
            try:
                table.yview_moveto(0)
            except tk.TclError:
                pass

    @staticmethod
    def _portrait_manager_column_count(width, card_min_width=260):
        card_min_width = max(1, int(card_min_width))
        return min(3, max(1, max(0, int(width)) // card_min_width))

    @staticmethod
    def _portrait_manager_should_hide_state(definition, assets):
        return (
            definition.get("category") == "preset"
            and not any((assets or {}).values())
        )

    def _append_portrait_manager_state(
        self,
        context,
        state,
        definition,
        initial_assets=None,
    ):
        is_initial = initial_assets is not None
        initial_assets = dict(initial_assets or {})
        portrait_assets = definition.get("portrait_assets", {})
        row = {
            "key": tk.StringVar(value=state),
            "label": tk.StringVar(
                value=str(definition.get("label", "") or state)
            ),
            "keywords": tk.StringVar(
                value=", ".join(definition.get("keywords", ()))
            ),
            "category": definition.get("category", "custom"),
            "usage_scenario": definition.get("usage_scenario", ""),
            "initial_key": state if is_initial else None,
            "initial_label": str(definition.get("label", "") or state),
            "initial_assets": initial_assets,
            "assets": dict(initial_assets),
            "portrait_assets": (
                dict(portrait_assets) if isinstance(portrait_assets, dict) else {}
            ),
            "pending": {"full": None, "small": None},
            "frame": None,
        }
        context["portrait_state_rows"].append(row)
        return row

    def _add_common_portrait_emotions(self, context):
        rows = context.get("portrait_state_rows", [])
        visible_keys = {
            self._normalize_portrait_state_key(row["key"].get())
            for row in rows
            if not row.get("manager_hidden")
        }
        available = [
            (
                key,
                {
                    "label": preset["label"],
                    "keywords": list(preset["keywords"]),
                    "enabled": True,
                    "portrait_assets": {},
                    "category": "preset",
                },
            )
            for key, preset in PRESET_EMOTIONS.items()
            if key not in visible_keys
        ]
        parent = getattr(self, "_control_dialog", None) or self.root
        if not available:
            messagebox.showinfo(
                "常用情绪已添加",
                "所有常用情绪都已加入立绘差分。",
                parent=parent,
            )
            return

        dialog = tk.Toplevel(parent)
