        dialog.transient(parent)
        dialog.resizable(False, False)
        dialog.configure(bg=BRAND_COLORS["panel"])
        dialog.grab_set()
        dialog.grid_columnconfigure(0, weight=1)
        tk.Label(
            dialog,
            text="情绪名称",
            bg=BRAND_COLORS["panel"],
            fg=BRAND_COLORS["white"],
            anchor="w",
        ).grid(row=0, column=0, sticky="ew", padx=16, pady=(14, 3))
        selected_label = tk.StringVar(master=dialog)
        EmotionSelector(
            dialog, selected_label, [key for key, _definition in available],
            BRAND_COLORS, width=400,
        ).grid(row=1, column=0, sticky="ew", padx=16, pady=(0, 10))

        tk.Label(
            dialog,
            text="仅显示当前动作尚未添加的常用情绪。",
            bg=BRAND_COLORS["panel"],
            fg=BRAND_COLORS["muted"],
            anchor="w",
            justify="left",
            wraplength=320,
        ).grid(row=2, column=0, sticky="ew", padx=16, pady=(0, 8))

        selected_assets = {"full": None}
