    @staticmethod
    def _config_value_text(value, json_value=False):
        if json_value:
            import json
            return json.dumps(value, ensure_ascii=False)
        return str(value)

    @staticmethod
    def _toggle_text(value):
        return "已开启" if value else "已关闭"

    def _toggle_bool(self, variable, button):
        value = not bool(variable.get())
        variable.set(value)
        button.configure(text=self._toggle_text(value))

    def _read_config_value(self, old_value, variable, json_value=False):
        import json

        if isinstance(variable, tk.Text):
            text = variable.get("1.0", "end").strip()
        else:
            text = variable.get()
        if json_value:
            value = json.loads(text)
        elif isinstance(old_value, bool):
            value = bool(text)
        elif isinstance(old_value, int) and not isinstance(old_value, bool):
            value = int(text)
        elif isinstance(old_value, float):
            value = float(text)
        else:
            value = text
        if text in ("中文", "日文"):
            value = "zh" if text == "中文" else "ja"
        return text, value

    def _apply_config_vars(self, config_vars, character_config=None, voice_config=None, context=None):
        import json

        character_config = self.character_config if character_config is None else character_config
        voice_config = self.voice_config if voice_config is None else voice_config
        for target, prefix, key, old_value, variable, json_value, resource in config_vars:
            text, value = self._read_config_value(old_value, variable, json_value)
            if target == "character" and (key == "user_address" or prefix.startswith("user_address_by_language.")):
                value = str(text or "").strip()
            elif target == "settings" and key == "theme":
                theme_names = {theme["name"]: name for name, theme in THEMES.items()}
                value = theme_names.get(text, self.theme_name)
            elif target == "app" and key == "screenshot_directory":
                value = str(resolve_screenshot_directory(text))
            elif target == "app" and key == "voice_directory":
                value = str(ensure_voice_directory(text))
            if resource and text:
                value = self._import_character_resource(key, text, context=context)
            if target == "app":
                target_config = self.app_config
            elif target == "voice":
                target_config = voice_config
            elif target == "character":
                target_config = character_config
            elif target == "settings":
                target_config = self.store.settings
            else:
                target_config = self.character_config
            if prefix:
                for section in prefix.split("."):
                    target_config = target_config.setdefault(section, {})
            target_config[key] = value

    def _validate_shortcut_vars(self):
        values = {}
        for target, prefix, key, _old_value, variable, _json_value, _resource in self._config_vars:
            mapping_key = getattr(variable, "_mapping_key", None)
            if mapping_key:
                values[mapping_key] = str(variable.get()).strip()
        parsed = {}
        for key, value in values.items():
            variable_type = next(
                (
                    getattr(variable, "_mapping_type", "shortcut")
                    for _target, _prefix, _config_key, _old_value, variable, _json_value, _resource in self._config_vars
                    if getattr(variable, "_mapping_key", None) == key
                ),
                "shortcut",
            )
            if variable_type == "shortcut":
                try:
                    parsed[key] = ("keyboard",) + parse_hotkey(value)
                except ValueError as error:
                    raise ValueError("{}快捷键无效：{}".format(key, error))
            elif not value or value.startswith("请按键"):
                raise ValueError("{}尚未完成按键录入。".format(key))
            else:
                parsed[key] = value.lower()
        duplicates = {}
        for key, normalized in parsed.items():
            duplicates.setdefault(normalized, []).append(key)
        repeated = ["/".join(keys) for keys in duplicates.values() if len(keys) > 1]
        if repeated:
            raise ValueError("快捷键冲突：{}".format("、".join(repeated)))

    @staticmethod
    def _emotion_audio_row_key(row):
        label = row["emotion"].get().strip()
        if "emotion_choices" not in row:
            return label
        key = row["emotion_choices"].get(label)
        if key:
            return key
        if label == row.get("initial_display"):
            return row["legacy_emotion"]
        raise ValueError("请从该角色已添加的情绪中选择参考情绪。")

    @staticmethod
    def _collect_emotion_groups(rows):
        emotion_groups = {}
        for row in rows:
            emotion = DesktopPetApp._emotion_audio_row_key(row)
            if not emotion:
                continue
            audios = [item.strip() for item in row["audios"].get().splitlines() if item.strip()]
            merged = emotion_groups.setdefault(emotion, [])
            merged.extend(item for item in audios if item not in merged)
        return emotion_groups

    def _save_config_dialog(self, dialog):
        import json
        try:
            self._validate_shortcut_vars()
            self._apply_config_vars(self._config_vars)
            self._apply_operation_bindings()
            save_app_config(self.app_config)
            self.shortcuts = self.app_config.get("shortcuts", self.shortcuts)
            self.root.unbind(
                getattr(self, "_quit_binding_sequence", "<Control-KeyPress-q>"),
                getattr(self, "_quit_binding_id", None),
            )
            self._quit_binding_sequence = self._tk_shortcut(
                self.shortcuts.get("quit", "Ctrl+Q")
            )
            self._quit_binding_id = self.root.bind(
                self._quit_binding_sequence,
                lambda event: self.quit_app(),
            )
            self.store.save_settings({"theme": self.store.settings.get("theme", self.theme_name)})
            self.theme_name = self.store.settings.get("theme", self.theme_name)
            self.theme = THEMES.get(self.theme_name, THEMES["pink"])
            self._apply_theme()
            self._render_state()
            hotkey_manager = getattr(self, "hotkey_manager", None)
            if hotkey_manager is not None:
                hotkey_manager.stop()
            self._start_global_hotkeys()
            pending_character_id = getattr(self, "_pending_character_id", self.character_id)
            if pending_character_id != self.character_id:
                self.switch_character(pending_character_id)
            if hasattr(self, "status_label"):
                self.status_label.configure(text="配置已保存")
            self._close_config_dialog(dialog)
        except (ValueError, json.JSONDecodeError, OSError) as error:
            messagebox.showerror("配置保存失败", "请检查数字或 JSON 格式：{}".format(error), parent=dialog)

    def _import_character_resource(self, key, source, context=None):
        source_path = Path(source)
        character_dir = context["character_dir"] if context else self.character_dir
        if (Path(character_dir) / "signature.ed25519").exists():
            if key in ("ckpt_file", "pth_file", "default_audio") or key.startswith("language_reference_audio_"):
                if source_path.is_absolute() and source_path.is_file():
                    return str(source_path.resolve())
                return source
            raise ValueError("签名角色包资源不能直接覆盖，请使用包内已有资源或导入更新后的签名包。")
        if not source_path.is_absolute():
            character_relative = character_dir / "portraits" / source_path
            if character_relative.exists():
                source_path = character_relative
            else:
                voice_relative = character_dir / "voice" / source_path
                if voice_relative.exists():
                    source_path = voice_relative
        if key in ("full_portrait_folder", "window_portrait_folder") and (
            source_path.is_dir()
            or (
                source_path.is_file()
                and source_path.suffix.lower() in IMAGE_EXTENSIONS
            )
        ):
            if key == "full_portrait_folder":
                destination = character_dir / "portraits" / "outfits" / "默认"
                relative = "outfits/默认"
                mode = "full"
            else:
                destination = character_dir / "portraits" / "mode_assets" / "small"
                relative = "mode_assets/small"
                mode = "small"
            try:
                if source_path.resolve() == destination.resolve():
                    return relative
            except OSError:
                pass
            copied = enhance_portrait_folder(source_path, destination, mode=mode)
            return relative if copied else source
        if not source_path.is_file():
            return source
        if key == "active_full_portrait":
            destination = character_dir / "portraits" / "outfits" / "默认" / "待机.png"
            relative = "outfits/默认/待机.png"
        elif key == "active_small_portrait":
            destination = character_dir / "portraits" / "mode_assets" / "small" / "idle.png"
            relative = "mode_assets/small/idle.png"
        elif key == "ckpt_file":
            destination = character_dir / "voice" / "models" / source_path.name
            relative = "models/{}".format(source_path.name)
        elif key == "pth_file":
            destination = character_dir / "voice" / "models" / source_path.name
            relative = "models/{}".format(source_path.name)
        elif key == "default_audio":
            destination = character_dir / "voice" / "references" / source_path.name
            relative = "references/{}".format(source_path.name)
        elif key.startswith("language_reference_audio_"):
            destination = character_dir / "voice" / "references" / source_path.name
            relative = "references/{}".format(source_path.name)
        else:
            return source
        destination.parent.mkdir(parents=True, exist_ok=True)
        try:
            if source_path.resolve() == destination.resolve():
                return relative
        except OSError:
            pass
        shutil.copy2(str(source_path), str(destination))
        return relative
